import type { LocalizedString } from '~/lib/domain'
import { L } from '../../locale'

/** Generated TOPIK 4 usage-note shard 3/5. */
export const USAGE_NOTES: Record<string, LocalizedString> = {
  '-(으)ㄹ 듯하다 / -(으)ㄹ 듯이': L(
      '-(으)ㄹ 듯하다 means "seems about to" or "looks like (something is happening)," expressing a guess based on what you observe, often with a sense of imminence. It attaches to verb/adjective stems: a vowel or ㄹ stem takes -ㄹ 듯하다 (오다 → 올 듯하다 "seems about to come," 살다 → 살 듯하다, ㄹ kept), while a consonant (받침) stem takes -을 듯하다 (먹다 → 먹을 듯하다 "looks about to eat"). For "looks like it\'s about to rain" you need the noun 비, as in 비가 올 듯하다, since 오다 by itself just means "come." With -(으)ㄴ 듯하다 it reads as past/completed ("seems to have"), and with -는 듯하다 as ongoing. The sibling form -(으)ㄹ 듯이 (often shortened to -(으)ㄹ 듯) works adverbially, "as if / in the manner of," modifying the following verb: 비가 쏟아질 듯이 하늘이 어두워졌다 "the sky darkened as if rain would pour down."\n\nThe closest neighbor to watch is -(으)ㄹ 것 같다, which also means "seems / probably will." The nuance: 곧 비가 올 듯하다 and 곧 비가 올 것 같다 both mean "it looks like it\'ll rain soon," but -듯하다 is slightly more bookish and literary, common in writing and narration, while -(으)ㄹ 것 같다 is the everyday spoken default. Register-wise, attach the usual endings to 하다: 올 듯해요 (polite), 올 듯합니다 (formal). The most common learner mistake is confusing the two forms — using 듯하다 (a sentence-ending predicate) where you need adverbial 듯이 to modify a verb, e.g. saying 울 듯하다 웃었다 instead of the correct 울 듯이 웃었다 "smiled as if about to cry."',
      '-(으)ㄹ 듯하다 significa "parece estar a punto de" o "parece que (algo está pasando)", y expresa una suposición basada en lo que observás, a menudo con una sensación de inminencia. Se une a raíces de verbos/adjetivos: una raíz terminada en vocal o en ㄹ toma -ㄹ 듯하다 (오다 → 올 듯하다 "parece estar a punto de venir", 살다 → 살 듯하다, con ㄹ conservada), mientras que una raíz terminada en consonante (받침) toma -을 듯하다 (먹다 → 먹을 듯하다 "parece estar a punto de comer"). Para "parece que va a llover" necesitás el sustantivo 비, como en 비가 올 듯하다, ya que 오다 por sí solo solo significa "venir". Con -(으)ㄴ 듯하다 se lee como pasado/terminado ("parece haber..."), y con -는 듯하다 como algo en curso. La forma hermana -(으)ㄹ 듯이 (a menudo acortada a -(으)ㄹ 듯) funciona de manera adverbial, "como si / a la manera de", modificando el verbo que sigue: 비가 쏟아질 듯이 하늘이 어두워졌다 "el cielo se oscureció como si fuera a caer un aguacero".\n\nEl vecino más cercano que tenés que vigilar es -(으)ㄹ 것 같다, que también significa "parece / probablemente vaya a". El matiz: 곧 비가 올 듯하다 y 곧 비가 올 것 같다 ambos significan "parece que va a llover pronto", pero -듯하다 es un poco más libresco y literario, común en la escritura y la narración, mientras que -(으)ㄹ 것 같다 es lo normal y cotidiano en el habla. En cuanto al registro, agregá las terminaciones habituales a 하다: 올 듯해요 (cortés), 올 듯합니다 (formal). El error más común de quien aprende es confundir las dos formas: usar 듯하다 (un predicado que cierra la oración) donde necesitás el adverbial 듯이 para modificar un verbo, por ejemplo decir 울 듯하다 웃었다 en vez de lo correcto, 울 듯이 웃었다 "sonrió como si fuera a llorar".',
      '-(으)ㄹ 듯하다 signifie « semble sur le point de » ou « on dirait que (quelque chose est en train d\'arriver) », et exprime une supposition fondée sur ce que tu observes, souvent avec une idée d\'imminence. Il s\'attache aux radicaux de verbes/adjectifs : un radical en voyelle ou en ㄹ prend -ㄹ 듯하다 (오다 → 올 듯하다 « semble sur le point de venir », 살다 → 살 듯하다, le ㄹ étant conservé), tandis qu\'un radical en consonne (받침) prend -을 듯하다 (먹다 → 먹을 듯하다 « semble sur le point de manger »). Pour « on dirait qu\'il va pleuvoir », il te faut le nom 비, comme dans 비가 올 듯하다, car 오다 seul signifie simplement « venir ». Avec -(으)ㄴ 듯하다, cela se lit comme un passé/accompli (« semble avoir... »), et avec -는 듯하다 comme une action en cours. La forme sœur -(으)ㄹ 듯이 (souvent abrégée en -(으)ㄹ 듯) fonctionne de façon adverbiale, « comme si / à la manière de », en modifiant le verbe qui suit : 비가 쏟아질 듯이 하늘이 어두워졌다 « le ciel s\'est assombri comme si une averse allait s\'abattre ».\n\nLe voisin le plus proche à surveiller est -(으)ㄹ 것 같다, qui signifie aussi « semble / va probablement ». La nuance : 곧 비가 올 듯하다 et 곧 비가 올 것 같다 signifient tous deux « on dirait qu\'il va bientôt pleuvoir », mais -듯하다 est un peu plus livresque et littéraire, courant à l\'écrit et dans la narration, tandis que -(으)ㄹ 것 같다 est la tournure quotidienne par défaut à l\'oral. Côté registre, ajoute les terminaisons habituelles à 하다 : 올 듯해요 (poli), 올 듯합니다 (formel). L\'erreur la plus fréquente chez les apprenants est de confondre les deux formes : utiliser 듯하다 (un prédicat qui termine la phrase) là où il faut l\'adverbial 듯이 pour modifier un verbe, par exemple dire 울 듯하다 웃었다 au lieu de la forme correcte 울 듯이 웃었다 « il a souri comme s\'il allait pleurer ».',
      '-(으)ㄹ 듯하다 significa "parece estar prestes a" ou "parece que (algo está acontecendo)", expressando uma suposição com base no que você observa, muitas vezes com uma ideia de iminência. Liga-se a radicais de verbos/adjetivos: um radical terminado em vogal ou em ㄹ leva -ㄹ 듯하다 (오다 → 올 듯하다 "parece estar prestes a vir", 살다 → 살 듯하다, com o ㄹ mantido), enquanto um radical terminado em consoante (받침) leva -을 듯하다 (먹다 → 먹을 듯하다 "parece estar prestes a comer"). Para "parece que vai chover" você precisa do substantivo 비, como em 비가 올 듯하다, já que 오다 sozinho significa apenas "vir". Com -(으)ㄴ 듯하다 lê-se como passado/concluído ("parece ter..."), e com -는 듯하다 como algo em andamento. A forma irmã -(으)ㄹ 듯이 (frequentemente abreviada para -(으)ㄹ 듯) funciona de modo adverbial, "como se / à maneira de", modificando o verbo seguinte: 비가 쏟아질 듯이 하늘이 어두워졌다 "o céu escureceu como se fosse desabar um aguaceiro".\n\nO vizinho mais próximo a observar é -(으)ㄹ 것 같다, que também significa "parece / provavelmente vai". A nuance: 곧 비가 올 듯하다 e 곧 비가 올 것 같다 ambos significam "parece que vai chover logo", mas -듯하다 é um pouco mais culto e literário, comum na escrita e na narração, enquanto -(으)ㄹ 것 같다 é o padrão cotidiano da fala. Quanto ao registro, acrescente as terminações usuais a 하다: 올 듯해요 (polido), 올 듯합니다 (formal). O erro mais comum de quem aprende é confundir as duas formas: usar 듯하다 (um predicado que encerra a frase) onde você precisa do adverbial 듯이 para modificar um verbo, por exemplo dizer 울 듯하다 웃었다 em vez do correto 울 듯이 웃었다 "sorriu como se fosse chorar".',
      '-(으)ㄹ 듯하다 หมายถึง "ดูเหมือนกำลังจะ" หรือ "ดูเหมือนว่า (บางอย่างกำลังเกิดขึ้น)" เป็นการคาดเดาจากสิ่งที่คุณสังเกตเห็น มักมีความรู้สึกว่าใกล้จะเกิดขึ้น มันเชื่อมกับรากศัพท์ของคำกริยา/คำคุณศัพท์: รากที่ลงท้ายด้วยสระหรือ ㄹ ใช้ -ㄹ 듯하다 (오다 → 올 듯하다 "ดูเหมือนกำลังจะมา", 살다 → 살 듯하다 โดยคง ㄹ ไว้) ส่วนรากที่ลงท้ายด้วยพยัญชนะ (받침) ใช้ -을 듯하다 (먹다 → 먹을 듯하다 "ดูเหมือนกำลังจะกิน") สำหรับ "ดูเหมือนฝนกำลังจะตก" คุณต้องใช้คำนาม 비 อย่างใน 비가 올 듯하다 เพราะ 오다 เพียงลำพังแปลแค่ว่า "มา" เมื่อใช้ -(으)ㄴ 듯하다 จะอ่านได้เป็นอดีต/เสร็จสิ้น ("ดูเหมือนได้...") และเมื่อใช้ -는 듯하다 จะเป็นการกระทำที่กำลังดำเนินอยู่ รูปพี่น้องอย่าง -(으)ㄹ 듯이 (มักย่อเป็น -(으)ㄹ 듯) ทำหน้าที่เป็นคำวิเศษณ์ "ราวกับว่า / ในลักษณะของ" ขยายคำกริยาที่ตามมา: 비가 쏟아질 듯이 하늘이 어두워졌다 "ท้องฟ้ามืดลงราวกับว่าฝนจะกระหน่ำลงมา"\n\nเพื่อนบ้านที่ใกล้เคียงที่สุดที่ต้องระวังคือ -(으)ㄹ 것 같다 ซึ่งก็แปลว่า "ดูเหมือน / น่าจะ" เช่นกัน ความต่างเล็กน้อย: 곧 비가 올 듯하다 และ 곧 비가 올 것 같다 ทั้งคู่แปลว่า "ดูเหมือนฝนจะตกเร็ว ๆ นี้" แต่ -듯하다 ออกแนวเป็นภาษาหนังสือและวรรณกรรมมากกว่าเล็กน้อย พบบ่อยในงานเขียนและการเล่าเรื่อง ในขณะที่ -(으)ㄹ 것 같다 เป็นรูปที่ใช้ในภาษาพูดทั่วไปในชีวิตประจำวัน ในแง่ระดับภาษา ให้เติมท้ายตามปกติเข้ากับ 하다: 올 듯해요 (สุภาพ), 올 듯합니다 (ทางการ) ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการสับสนระหว่างสองรูปนี้ — ใช้ 듯하다 (ภาคแสดงที่ปิดท้ายประโยค) ในที่ที่ควรใช้คำวิเศษณ์ 듯이 เพื่อขยายคำกริยา เช่น พูดว่า 울 듯하다 웃었다 แทนที่จะเป็นรูปที่ถูกต้อง 울 듯이 웃었다 "ยิ้มราวกับว่ากำลังจะร้องไห้"',
      '-(으)ㄹ 듯하다 berarti "tampaknya hampir" atau "kelihatannya (sesuatu sedang terjadi)", mengungkapkan dugaan berdasarkan apa yang kamu amati, sering kali dengan kesan akan segera terjadi. Bentuk ini menempel pada akar kata kerja/kata sifat: akar yang berakhiran vokal atau ㄹ memakai -ㄹ 듯하다 (오다 → 올 듯하다 "tampaknya hampir datang", 살다 → 살 듯하다, ㄹ tetap dipertahankan), sedangkan akar yang berakhiran konsonan (받침) memakai -을 듯하다 (먹다 → 먹을 듯하다 "kelihatannya hampir makan"). Untuk "kelihatannya akan turun hujan" kamu memerlukan nomina 비, seperti dalam 비가 올 듯하다, karena 오다 sendiri hanya berarti "datang". Dengan -(으)ㄴ 듯하다 maknanya menjadi lampau/selesai ("tampaknya sudah..."), dan dengan -는 듯하다 menjadi sesuatu yang sedang berlangsung. Bentuk saudaranya -(으)ㄹ 듯이 (sering disingkat menjadi -(으)ㄹ 듯) berfungsi secara adverbial, "seolah-olah / dengan cara", memodifikasi kata kerja yang mengikutinya: 비가 쏟아질 듯이 하늘이 어두워졌다 "langit menggelap seolah-olah hujan akan tumpah".\n\nTetangga terdekat yang perlu diwaspadai adalah -(으)ㄹ 것 같다, yang juga berarti "tampaknya / mungkin akan". Nuansanya: 곧 비가 올 듯하다 dan 곧 비가 올 것 같다 keduanya berarti "kelihatannya sebentar lagi akan hujan", tetapi -듯하다 sedikit lebih bersifat kebukuan dan sastrawi, lazim dalam tulisan dan narasi, sedangkan -(으)ㄹ 것 같다 adalah pilihan sehari-hari yang umum dalam percakapan. Soal ragam, tambahkan akhiran biasa pada 하다: 올 듯해요 (sopan), 올 듯합니다 (formal). Kesalahan yang paling sering dilakukan pembelajar adalah mengacaukan kedua bentuk ini — memakai 듯하다 (predikat penutup kalimat) di tempat yang seharusnya memakai adverbial 듯이 untuk memodifikasi kata kerja, misalnya mengatakan 울 듯하다 웃었다 alih-alih bentuk yang benar 울 듯이 웃었다 "tersenyum seolah-olah hampir menangis".',
      '-(으)ㄹ 듯하다 nghĩa là "có vẻ sắp" hoặc "trông như (điều gì đó đang xảy ra)", diễn đạt một sự phỏng đoán dựa trên những gì bạn quan sát, thường mang sắc thái sắp sửa diễn ra. Nó gắn vào gốc động từ/tính từ: gốc kết thúc bằng nguyên âm hoặc ㄹ dùng -ㄹ 듯하다 (오다 → 올 듯하다 "có vẻ sắp đến", 살다 → 살 듯하다, ㄹ được giữ lại), trong khi gốc kết thúc bằng phụ âm (받침) dùng -을 듯하다 (먹다 → 먹을 듯하다 "trông như sắp ăn"). Để nói "trông như trời sắp mưa" bạn cần danh từ 비, như trong 비가 올 듯하다, vì 오다 đứng một mình chỉ có nghĩa là "đến". Với -(으)ㄴ 듯하다 thì hiểu là quá khứ/hoàn thành ("có vẻ đã..."), còn với -는 듯하다 thì là điều đang diễn ra. Dạng anh em -(으)ㄹ 듯이 (thường rút gọn thành -(으)ㄹ 듯) hoạt động như trạng từ, "như thể / theo kiểu", bổ nghĩa cho động từ theo sau: 비가 쏟아질 듯이 하늘이 어두워졌다 "bầu trời tối sầm lại như thể mưa sắp trút xuống".\n\nNgười hàng xóm gần nhất cần để ý là -(으)ㄹ 것 같다, cũng có nghĩa "có vẻ / có lẽ sẽ". Sắc thái: 곧 비가 올 듯하다 và 곧 비가 올 것 같다 đều có nghĩa "trông như trời sắp mưa", nhưng -듯하다 mang tính sách vở và văn chương hơn một chút, phổ biến trong văn viết và lời kể, còn -(으)ㄹ 것 같다 là cách nói thông dụng hằng ngày trong văn nói. Về sắc thái lịch sự, hãy thêm các đuôi thông thường vào 하다: 올 듯해요 (lịch sự), 올 듯합니다 (trang trọng). Lỗi phổ biến nhất của người học là nhầm lẫn hai dạng này — dùng 듯하다 (vị ngữ kết thúc câu) ở chỗ cần trạng từ 듯이 để bổ nghĩa cho động từ, ví dụ nói 울 듯하다 웃었다 thay vì dạng đúng là 울 듯이 웃었다 "mỉm cười như thể sắp khóc".',
      '-(으)ㄹ 듯하다 は「今にも〜しそうだ」「〜しているように見える」という意味で、観察したことに基づく推測を表し、しばしば「もうすぐ起こりそうだ」という切迫したニュアンスを伴います。動詞・形容詞の語幹に付きます。母音または ㄹ で終わる語幹には -ㄹ 듯하다 が付き(오다 → 올 듯하다「今にも来そうだ」、살다 → 살 듯하다、ㄹ は残る)、子音(받침)で終わる語幹には -을 듯하다 が付きます(먹다 → 먹을 듯하다「今にも食べそうだ」)。「雨が降りそうだ」と言うには名詞 비 が必要で、비가 올 듯하다 のようにします。오다 だけでは単に「来る」という意味だからです。-(으)ㄴ 듯하다 では過去・完了(「〜したようだ」)、-는 듯하다 では進行中の意味になります。姉妹形の -(으)ㄹ 듯이(しばしば -(으)ㄹ 듯 と短縮される)は副詞的に働き、「まるで〜のように／〜するかのように」と後ろの動詞を修飾します。例:비가 쏟아질 듯이 하늘이 어두워졌다「雨が降り注ぎそうに空が暗くなった」。\n\n注意すべき最も近い隣人は -(으)ㄹ 것 같다 で、これも「〜しそうだ／たぶん〜だろう」という意味です。ニュアンスの違いとして、곧 비가 올 듯하다 と 곧 비가 올 것 같다 はどちらも「もうすぐ雨が降りそうだ」という意味ですが、-듯하다 はやや文語的・文学的で、書き言葉や語りでよく使われる一方、-(으)ㄹ 것 같다 は日常会話の標準的な言い方です。文体の面では、いつもの語尾を 하다 に付けます:올 듯해요(丁寧)、올 듯합니다(フォーマル)。学習者が最もよくする間違いは、この二つの形を混同することです。動詞を修飾するには副詞的な 듯이 が必要なのに、文を締めくくる述語の 듯하다 を使ってしまう、たとえば正しい 울 듯이 웃었다「泣きそうに笑った」の代わりに 울 듯하다 웃었다 と言ってしまう、というものです。',
    ),
  '-기에 앞서': L(
      'Signals that one action happens "before / prior to" another, with a formal flavour that implies the first event is a deliberate lead-up or precondition. The full pattern is verb stem + -기에 앞서. It attaches to a plain verb stem with no allomorph change, so the ending is identical after a vowel/ㄹ stem and a consonant (받침) stem: 가다 → 가기에 앞서 ("before going / prior to departure"), 만들다 → 만들기에 앞서 (ㄹ is kept, "before making it"), 먹다 → 먹기에 앞서 ("before eating"), 시작하다 → 시작하기에 앞서 ("before beginning"). It does not take tense — never 갔기에 앞서 — because the timing is already fixed by 앞서; you also see it on noun-like 회의 → 회의에 앞서 ("ahead of the meeting"), where 앞서 attaches to the noun with -에.\n\nThe close neighbour to watch is the everyday -기 전에 ("before"). Compare 발표하기 전에 자료를 확인했어요 ("I checked the materials before presenting") with 발표하기에 앞서 자료를 확인했습니다 ("Prior to presenting, I reviewed the materials"). The meaning overlaps, but -기 전에 is neutral and conversational, whereas -기에 앞서 is stiff, ceremonial language for speeches, reports and announcements, and it stresses that the first act is preparatory groundwork rather than just an earlier point in time. Because of that register, it pairs naturally with 습니다 endings; the most common learner mistake is using it in casual speech (it sounds oddly pompous over coffee) or wrongly adding tense as in 했기에 앞서. There is no spoken contraction — keep the full 기에 앞서.',
      'Indica que una acción ocurre "antes de / con anterioridad a" otra, con un tono formal que sugiere que el primer evento es una preparación o condición previa deliberada. El patrón completo es raíz verbal + -기에 앞서. Se pega a la raíz simple del verbo sin cambio de alomorfo, así que la terminación es idéntica después de una raíz en vocal/ㄹ y una raíz en consonante (받침): 가다 → 가기에 앞서 ("antes de ir / con anterioridad a la partida"), 만들다 → 만들기에 앞서 (se conserva la ㄹ, "antes de hacerlo"), 먹다 → 먹기에 앞서 ("antes de comer"), 시작하다 → 시작하기에 앞서 ("antes de empezar"). No lleva tiempo —nunca 갔기에 앞서— porque 앞서 ya fija la temporalidad; también lo ves sobre sustantivos como 회의 → 회의에 앞서 ("antes de la reunión"), donde 앞서 se une al sustantivo con -에.\n\nEl vecino cercano que tenés que vigilar es el cotidiano -기 전에 ("antes de"). Compará 발표하기 전에 자료를 확인했어요 ("revisé los materiales antes de presentar") con 발표하기에 앞서 자료를 확인했습니다 ("Con anterioridad a presentar, revisé los materiales"). El significado se solapa, pero -기 전에 es neutro y conversacional, mientras que -기에 앞서 es lenguaje rígido y ceremonioso para discursos, informes y anuncios, y subraya que el primer acto es un trabajo preparatorio y no solo un punto anterior en el tiempo. Por ese registro, combina de forma natural con terminaciones 습니다; el error más común de quien aprende es usarlo en el habla casual (suena raramente pomposo tomando un café) o agregar tiempo de forma incorrecta como en 했기에 앞서. No hay contracción hablada: mantené el 기에 앞서 completo.',
      'Indique qu\'une action se produit "avant / préalablement à" une autre, avec une nuance formelle laissant entendre que le premier événement est une préparation ou une condition préalable délibérée. Le schéma complet est radical verbal + -기에 앞서. Il s\'attache à un radical verbal simple sans changement d\'allomorphe, donc la terminaison est identique après un radical en voyelle/ㄹ et un radical en consonne (받침) : 가다 → 가기에 앞서 ("avant de partir / préalablement au départ"), 만들다 → 만들기에 앞서 (le ㄹ est conservé, "avant de le faire"), 먹다 → 먹기에 앞서 ("avant de manger"), 시작하다 → 시작하기에 앞서 ("avant de commencer"). Il ne prend pas de temps —jamais 갔기에 앞서— car le moment est déjà fixé par 앞서 ; tu le vois aussi sur des noms comme 회의 → 회의에 앞서 ("avant la réunion"), où 앞서 s\'attache au nom avec -에.\n\nLe voisin proche à surveiller est le quotidien -기 전에 ("avant"). Compare 발표하기 전에 자료를 확인했어요 ("j\'ai vérifié les documents avant de présenter") avec 발표하기에 앞서 자료를 확인했습니다 ("Préalablement à la présentation, j\'ai examiné les documents"). Le sens se recoupe, mais -기 전에 est neutre et conversationnel, tandis que -기에 앞서 est une langue rigide et cérémonielle pour les discours, les rapports et les annonces, et il souligne que le premier acte est un travail préparatoire plutôt qu\'un simple point antérieur dans le temps. À cause de ce registre, il se marie naturellement avec les terminaisons 습니다 ; l\'erreur la plus fréquente des apprenants est de l\'employer dans la langue parlée familière (cela sonne curieusement pompeux autour d\'un café) ou d\'ajouter à tort un temps comme dans 했기에 앞서. Il n\'y a pas de contraction à l\'oral : garde le 기에 앞서 complet.',
      'Indica que uma ação acontece "antes de / previamente a" outra, com um tom formal que sugere que o primeiro evento é uma preparação ou condição prévia deliberada. O padrão completo é raiz verbal + -기에 앞서. Ele se anexa à raiz simples do verbo sem mudança de alomorfe, então a terminação é idêntica depois de uma raiz em vogal/ㄹ e uma raiz em consoante (받침): 가다 → 가기에 앞서 ("antes de ir / previamente à partida"), 만들다 → 만들기에 앞서 (o ㄹ é mantido, "antes de fazê-lo"), 먹다 → 먹기에 앞서 ("antes de comer"), 시작하다 → 시작하기에 앞서 ("antes de começar"). Não recebe tempo verbal —nunca 갔기에 앞서— porque o momento já está fixado por 앞서; você também o vê em substantivos como 회의 → 회의에 앞서 ("antes da reunião"), onde 앞서 se junta ao substantivo com -에.\n\nO vizinho próximo que você deve observar é o cotidiano -기 전에 ("antes"). Compare 발표하기 전에 자료를 확인했어요 ("verifiquei os materiais antes de apresentar") com 발표하기에 앞서 자료를 확인했습니다 ("Previamente à apresentação, revisei os materiais"). O significado se sobrepõe, mas -기 전에 é neutro e conversacional, enquanto -기에 앞서 é uma linguagem rígida e cerimoniosa para discursos, relatórios e anúncios, e enfatiza que o primeiro ato é um trabalho preparatório, e não apenas um ponto anterior no tempo. Por causa desse registro, ele combina naturalmente com terminações 습니다; o erro mais comum de quem aprende é usá-lo na fala casual (soa estranhamente pomposo durante um café) ou acrescentar tempo verbal de forma incorreta, como em 했기에 앞서. Não há contração falada: mantenha o 기에 앞서 completo.',
      'บ่งบอกว่าการกระทำหนึ่งเกิดขึ้น "ก่อน / ก่อนหน้า" อีกการกระทำหนึ่ง โดยมีกลิ่นอายที่เป็นทางการซึ่งสื่อว่าเหตุการณ์แรกเป็นการเตรียมการหรือเงื่อนไขล่วงหน้าอย่างตั้งใจ รูปแบบเต็มคือ รากศัพท์กริยา + -기에 앞서 มันเกาะกับรากกริยาธรรมดาโดยไม่มีการเปลี่ยน allomorph ดังนั้นส่วนลงท้ายจึงเหมือนกันทั้งหลังรากที่ลงท้ายด้วยสระ/ㄹ และรากที่ลงท้ายด้วยพยัญชนะ (받침): 가다 → 가기에 앞서 ("ก่อนไป / ก่อนการออกเดินทาง"), 만들다 → 만들기에 앞서 (ㄹ ยังคงอยู่, "ก่อนทำมัน"), 먹다 → 먹기에 앞서 ("ก่อนกิน"), 시작하다 → 시작하기에 앞서 ("ก่อนเริ่ม") มันไม่รับกาล —ไม่มีทางเป็น 갔기에 앞서— เพราะเวลาถูกกำหนดไว้แล้วโดย 앞서 และคุณยังเห็นมันใช้กับคำนามอย่าง 회의 → 회의에 앞서 ("ก่อนการประชุม") ซึ่ง 앞서 เกาะกับคำนามด้วย -에\n\nเพื่อนบ้านใกล้ชิดที่ต้องระวังคือ -기 전에 ("ก่อน") ที่ใช้ในชีวิตประจำวัน เปรียบเทียบ 발표하기 전에 자료를 확인했어요 ("ฉันตรวจสอบเอกสารก่อนนำเสนอ") กับ 발표하기에 앞서 자료를 확인했습니다 ("ก่อนการนำเสนอ ดิฉันได้ทบทวนเอกสาร") ความหมายซ้อนทับกัน แต่ -기 전에 เป็นกลางและใช้ในการสนทนา ในขณะที่ -기에 앞서 เป็นภาษาที่แข็งและเป็นพิธีการ สำหรับสุนทรพจน์ รายงาน และประกาศ และเน้นว่าการกระทำแรกเป็นงานเตรียมการพื้นฐาน ไม่ใช่เพียงจุดที่เกิดก่อนในเวลา เพราะระดับภาษานี้ มันจึงเข้าคู่กับส่วนลงท้าย 습니다 อย่างเป็นธรรมชาติ ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการใช้มันในการพูดแบบไม่เป็นทางการ (ฟังดูโอ้อวดแปลก ๆ ขณะนั่งจิบกาแฟ) หรือใส่กาลผิด ๆ อย่างใน 했기에 앞서 ไม่มีการย่อในการพูด ให้คงรูป 기에 앞서 เต็มไว้',
      'Menandakan bahwa satu tindakan terjadi "sebelum / mendahului" tindakan lain, dengan nuansa formal yang menyiratkan bahwa peristiwa pertama adalah persiapan atau prasyarat yang disengaja. Pola lengkapnya adalah akar kata kerja + -기에 앞서. Pola ini menempel pada akar kata kerja biasa tanpa perubahan alomorf, sehingga akhirannya identik setelah akar berhuruf vokal/ㄹ maupun akar berhuruf konsonan (받침): 가다 → 가기에 앞서 ("sebelum pergi / mendahului keberangkatan"), 만들다 → 만들기에 앞서 (ㄹ dipertahankan, "sebelum membuatnya"), 먹다 → 먹기에 앞서 ("sebelum makan"), 시작하다 → 시작하기에 앞서 ("sebelum memulai"). Pola ini tidak menerima kala —tidak pernah 갔기에 앞서— karena waktunya sudah ditetapkan oleh 앞서; kamu juga melihatnya pada kata benda seperti 회의 → 회의에 앞서 ("menjelang rapat"), di mana 앞서 menempel pada kata benda dengan -에.\n\nTetangga dekat yang perlu diwaspadai adalah -기 전에 ("sebelum") yang sehari-hari. Bandingkan 발표하기 전에 자료를 확인했어요 ("saya memeriksa materi sebelum presentasi") dengan 발표하기에 앞서 자료를 확인했습니다 ("Mendahului presentasi, saya meninjau materi"). Maknanya tumpang tindih, tetapi -기 전에 bersifat netral dan percakapan, sedangkan -기에 앞서 adalah bahasa yang kaku dan seremonial untuk pidato, laporan, dan pengumuman, dan menekankan bahwa tindakan pertama merupakan kerja persiapan, bukan sekadar titik yang lebih awal dalam waktu. Karena ragam bahasa itu, pola ini berpasangan secara alami dengan akhiran 습니다; kesalahan paling umum pembelajar adalah menggunakannya dalam percakapan santai (terdengar aneh dan sok megah saat ngopi) atau keliru menambahkan kala seperti pada 했기에 앞서. Tidak ada kontraksi lisan: pertahankan 기에 앞서 secara utuh.',
      'Báo hiệu rằng một hành động xảy ra "trước / trước khi" một hành động khác, với sắc thái trang trọng ngụ ý rằng sự kiện đầu tiên là một bước chuẩn bị hoặc điều kiện tiên quyết có chủ đích. Mẫu đầy đủ là gốc động từ + -기에 앞서. Nó gắn vào gốc động từ thuần túy mà không thay đổi biến thể, nên đuôi giống hệt nhau sau gốc kết thúc bằng nguyên âm/ㄹ và gốc kết thúc bằng phụ âm (받침): 가다 → 가기에 앞서 ("trước khi đi / trước lúc khởi hành"), 만들다 → 만들기에 앞서 (giữ lại ㄹ, "trước khi làm nó"), 먹다 → 먹기에 앞서 ("trước khi ăn"), 시작하다 → 시작하기에 앞서 ("trước khi bắt đầu"). Nó không mang thì —không bao giờ là 갔기에 앞서— vì thời điểm đã được 앞서 cố định rồi; bạn cũng thấy nó dùng với danh từ như 회의 → 회의에 앞서 ("trước cuộc họp"), nơi 앞서 gắn vào danh từ bằng -에.\n\nNgười hàng xóm gần gũi cần để ý là -기 전에 ("trước khi") quen thuộc hằng ngày. Hãy so sánh 발표하기 전에 자료를 확인했어요 ("tôi đã kiểm tra tài liệu trước khi thuyết trình") với 발표하기에 앞서 자료를 확인했습니다 ("Trước khi thuyết trình, tôi đã rà soát tài liệu"). Ý nghĩa có phần chồng lấn, nhưng -기 전에 trung tính và mang tính hội thoại, trong khi -기에 앞서 là thứ ngôn ngữ cứng nhắc, mang tính nghi thức dùng cho diễn văn, báo cáo và thông báo, và nó nhấn mạnh rằng hành động đầu tiên là công việc chuẩn bị nền tảng chứ không chỉ là một thời điểm trước đó. Vì sắc thái đó, nó kết hợp tự nhiên với đuôi 습니다; lỗi phổ biến nhất của người học là dùng nó trong lời nói thường ngày (nghe khoa trương một cách kỳ quặc khi đang nhâm nhi cà phê) hoặc thêm thì sai như trong 했기에 앞서. Không có dạng rút gọn khi nói: hãy giữ nguyên 기에 앞서 đầy đủ.',
      'ある動作が別の動作の「前に・先立って」起こることを示し、最初の出来事が意図的な前段階や前提条件であることをにじませる、改まった響きを持ちます。完全な形は動詞の語幹 + -기에 앞서 です。異形態の変化なく素の動詞語幹に付くので、母音・ㄹ語幹のあとでも子音(받침)語幹のあとでも語尾は同じです。가다 → 가기에 앞서(「行く前に・出発に先立って」)、만들다 → 만들기에 앞서(ㄹが保たれ、「それを作る前に」)、먹다 → 먹기에 앞서(「食べる前に」)、시작하다 → 시작하기에 앞서(「始める前に」)。時制は取りません——갔기에 앞서 とは決して言いません——なぜなら時間関係はすでに 앞서 によって定まっているからです。また名詞的な 회의 → 회의에 앞서(「会議に先立って」)のように、앞서 が -에 で名詞に付く形も見られます。\n\n注意すべき近い隣人は、日常的な -기 전에(「前に」)です。발표하기 전에 자료를 확인했어요(「発表する前に資料を確認した」)と 발표하기에 앞서 자료를 확인했습니다(「発表に先立ち、資料を確認いたしました」)を比べてみましょう。意味は重なりますが、-기 전에 は中立的で会話的なのに対し、-기에 앞서 は演説・報告・告知のための硬く儀式ばった言い回しで、最初の行為が単に時間的に早い時点というだけでなく、準備的な下地であることを強調します。その語感ゆえに 습니다 体の語尾と自然になじみます。学習者が最もよくやる間違いは、くだけた話し言葉で使ってしまうこと(コーヒーを飲みながらだと妙にもったいぶって聞こえます)や、했기에 앞서 のように誤って時制を付けることです。話し言葉での縮約はありません——기에 앞서 はそのまま完全な形で使ってください。',
    ),
  '-(으)로서 / -(으)로써': L(
      '-(으)로서 and -(으)로써 are a near-identical pair that sound the same in speech but differ in meaning. -(으)로서 means "as / in the capacity (role/status) of" and attaches only to nouns: 부모로서 "as a parent", 학생으로서 "as a student", 친구로서 "as a friend". -(으)로써 means "by means of / with / using" and marks the method, tool, or material: 대화로써 "by means of dialogue", 노력으로써 "through effort". Both follow the same allomorph rule — after a vowel or ㄹ use 로서/로써 (친구 → 친구로서, 대화 → 대화로써), and after a consonant 받침 use 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). They attach to nouns directly; to apply them to a verb, first nominalize it (예: 노력함으로써 "by making an effort").\n\nThe classic confusion is between the two themselves, so use a minimal pair: 교사로서 말한다 means "I speak as a teacher (in my role)", while 교사로써 무엇을 할 수 있을까 would wrongly use the "means" particle for a role. Contrast 칼로서 vs 칼로써: only 칼로써 (자르다) "cut with a knife" is correct, since a knife is a tool, not a role. Register is neutral and rather formal/written; in everyday speech the plain instrumental 로/으로 often replaces 로써 (칼로 잘라요). The most common learner mistake is swapping them — remember 로서 = 자격(qualification/role), 로써 = 수단(means/method). Memory hook: the 써 in 로써 echoes 쓰다 "to use".',
      '-(으)로서 y -(으)로써 son un par casi idéntico que suena igual al hablar pero difiere en significado. -(으)로서 significa "como / en calidad (rol/condición) de" y se une solo a sustantivos: 부모로서 "como padre/madre", 학생으로서 "como estudiante", 친구로서 "como amigo". -(으)로써 significa "por medio de / con / usando" y marca el método, la herramienta o el material: 대화로써 "por medio del diálogo", 노력으로써 "mediante el esfuerzo". Ambos siguen la misma regla de alomorfos: después de vocal o ㄹ usá 로서/로써 (친구 → 친구로서, 대화 → 대화로써), y después de una consonante 받침 usá 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). Se unen directamente a sustantivos; para aplicarlos a un verbo, primero nominalizalo (예: 노력함으로써 "haciendo un esfuerzo").\n\nLa confusión clásica es entre los dos mismos, así que usá un par mínimo: 교사로서 말한다 significa "hablo como profesor (en mi rol)", mientras que 교사로써 무엇을 할 수 있을까 usaría incorrectamente la partícula de "medio" para un rol. Contrastá 칼로서 vs 칼로써: solo 칼로써 (자르다) "cortar con un cuchillo" es correcto, ya que un cuchillo es una herramienta, no un rol. El registro es neutro y más bien formal/escrito; en el habla cotidiana el instrumental simple 로/으로 a menudo reemplaza a 로써 (칼로 잘라요). El error más común de quien aprende es intercambiarlos: acordate de que 로서 = 자격 (cualificación/rol), 로써 = 수단 (medio/método). Truco de memoria: el 써 en 로써 hace eco de 쓰다 "usar".',
      '-(으)로서 et -(으)로써 forment une paire quasi identique qui se prononce de la même façon mais diffère par le sens. -(으)로서 signifie « en tant que / en qualité (rôle/statut) de » et ne s\'attache qu\'à des noms : 부모로서 « en tant que parent », 학생으로서 « en tant qu\'étudiant », 친구로서 « en tant qu\'ami ». -(으)로써 signifie « au moyen de / avec / en utilisant » et marque la méthode, l\'outil ou le matériau : 대화로써 « au moyen du dialogue », 노력으로써 « par l\'effort ». Les deux suivent la même règle d\'allomorphes : après une voyelle ou ㄹ, utilise 로서/로써 (친구 → 친구로서, 대화 → 대화로써), et après une consonne 받침, utilise 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). Ils s\'attachent directement aux noms ; pour les appliquer à un verbe, nominalise-le d\'abord (예 : 노력함으로써 « en faisant un effort »).\n\nLa confusion classique se situe entre les deux eux-mêmes, alors utilise une paire minimale : 교사로서 말한다 signifie « je parle en tant qu\'enseignant (dans mon rôle) », tandis que 교사로써 무엇을 할 수 있을까 utiliserait à tort la particule de « moyen » pour un rôle. Compare 칼로서 vs 칼로써 : seul 칼로써 (자르다) « couper avec un couteau » est correct, car un couteau est un outil, pas un rôle. Le registre est neutre et plutôt formel/écrit ; dans le langage courant, l\'instrumental simple 로/으로 remplace souvent 로써 (칼로 잘라요). L\'erreur la plus fréquente des apprenants est de les inverser : retiens que 로서 = 자격 (qualification/rôle), 로써 = 수단 (moyen/méthode). Astuce mnémotechnique : le 써 dans 로써 fait écho à 쓰다 « utiliser ».',
      '-(으)로서 e -(으)로써 formam um par quase idêntico que soa igual na fala, mas difere no significado. -(으)로서 significa "como / na condição (papel/status) de" e se liga apenas a substantivos: 부모로서 "como pai/mãe", 학생으로서 "como estudante", 친구로서 "como amigo". -(으)로써 significa "por meio de / com / usando" e marca o método, a ferramenta ou o material: 대화로써 "por meio do diálogo", 노력으로써 "através do esforço". Ambos seguem a mesma regra de alomorfes: depois de vogal ou ㄹ, use 로서/로써 (친구 → 친구로서, 대화 → 대화로써), e depois de uma consoante 받침, use 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). Eles se ligam diretamente a substantivos; para aplicá-los a um verbo, primeiro nominalize-o (예: 노력함으로써 "fazendo um esforço").\n\nA confusão clássica é entre os dois em si, então use um par mínimo: 교사로서 말한다 significa "falo como professor (no meu papel)", enquanto 교사로써 무엇을 할 수 있을까 usaria erroneamente a partícula de "meio" para um papel. Contraste 칼로서 vs 칼로써: apenas 칼로써 (자르다) "cortar com uma faca" está correto, já que uma faca é uma ferramenta, não um papel. O registro é neutro e bastante formal/escrito; na fala cotidiana, o instrumental simples 로/으로 frequentemente substitui 로써 (칼로 잘라요). O erro mais comum de quem aprende é trocá-los: lembre-se de que 로서 = 자격 (qualificação/papel), 로써 = 수단 (meio/método). Dica de memória: o 써 em 로써 ecoa 쓰다 "usar".',
      '-(으)로서 และ -(으)로써 เป็นคู่ที่เกือบจะเหมือนกัน ออกเสียงเหมือนกันแต่มีความหมายต่างกัน -(으)로서 หมายถึง "ในฐานะ / ในบทบาท (ฐานะ/สถานะ) ของ" และเติมเฉพาะกับคำนามเท่านั้น: 부모로서 "ในฐานะพ่อแม่", 학생으로서 "ในฐานะนักเรียน", 친구로서 "ในฐานะเพื่อน" ส่วน -(으)로써 หมายถึง "โดยอาศัย / ด้วย / โดยใช้" และบ่งบอกวิธีการ เครื่องมือ หรือวัสดุ: 대화로써 "โดยการพูดคุย", 노력으로써 "ด้วยความพยายาม" ทั้งสองคำใช้กฎอัลโลมอร์ฟแบบเดียวกัน คือหลังสระหรือ ㄹ ให้ใช้ 로서/로써 (친구 → 친구로서, 대화 → 대화로써) และหลังพยัญชนะตัวสะกด 받침 ให้ใช้ 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써) ทั้งสองเติมกับคำนามโดยตรง หากต้องการใช้กับคำกริยา ให้แปลงเป็นคำนามก่อน (예: 노력함으로써 "ด้วยการพยายาม")\n\nความสับสนที่พบบ่อยคือระหว่างสองคำนี้เอง ดังนั้นลองดูคู่ที่ต่างกันเพียงจุดเดียว: 교사로서 말한다 หมายถึง "ฉันพูดในฐานะครู (ในบทบาทของฉัน)" ในขณะที่ 교사로써 무엇을 할 수 있을까 จะใช้คำชี้ "วิธีการ" กับบทบาทอย่างผิด ๆ ลองเทียบ 칼로서 กับ 칼로써: มีเพียง 칼로써 (자르다) "ตัดด้วยมีด" เท่านั้นที่ถูกต้อง เพราะมีดเป็นเครื่องมือ ไม่ใช่บทบาท ระดับภาษาเป็นกลางและค่อนข้างเป็นทางการ/ภาษาเขียน ในการพูดในชีวิตประจำวันมักใช้รูปบ่งบอกเครื่องมือธรรมดา 로/으로 แทน 로써 (칼로 잘라요) ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือสลับสองคำนี้ ให้จำว่า 로서 = 자격 (คุณสมบัติ/บทบาท), 로써 = 수단 (วิธีการ/เครื่องมือ) เคล็ดลับช่วยจำ: 써 ใน 로써 พ้องกับ 쓰다 "ใช้"',
      '-(으)로서 dan -(으)로써 adalah pasangan yang nyaris identik, terdengar sama saat diucapkan tetapi berbeda makna. -(으)로서 berarti "sebagai / dalam kapasitas (peran/status)" dan hanya melekat pada kata benda: 부모로서 "sebagai orang tua", 학생으로서 "sebagai pelajar", 친구로서 "sebagai teman". -(으)로써 berarti "dengan cara / dengan / menggunakan" dan menandai metode, alat, atau bahan: 대화로써 "melalui dialog", 노력으로써 "melalui usaha". Keduanya mengikuti aturan alomorf yang sama: setelah vokal atau ㄹ gunakan 로서/로써 (친구 → 친구로서, 대화 → 대화로써), dan setelah konsonan 받침 gunakan 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). Keduanya melekat langsung pada kata benda; untuk menerapkannya pada kata kerja, nominalisasikan dulu (예: 노력함으로써 "dengan berusaha").\n\nKebingungan klasik justru terletak di antara keduanya sendiri, jadi gunakan pasangan minimal: 교사로서 말한다 berarti "saya berbicara sebagai guru (dalam peran saya)", sedangkan 교사로써 무엇을 할 수 있을까 keliru memakai partikel "cara" untuk sebuah peran. Bandingkan 칼로서 dan 칼로써: hanya 칼로써 (자르다) "memotong dengan pisau" yang benar, karena pisau adalah alat, bukan peran. Ragamnya netral dan cenderung formal/tertulis; dalam percakapan sehari-hari, bentuk instrumental sederhana 로/으로 sering menggantikan 로써 (칼로 잘라요). Kesalahan paling umum di kalangan pelajar adalah menukar keduanya: ingatlah bahwa 로서 = 자격 (kualifikasi/peran), 로써 = 수단 (cara/metode). Kiat mengingat: 써 dalam 로써 menggemakan 쓰다 "memakai".',
      '-(으)로서 và -(으)로써 là một cặp gần như giống hệt nhau, phát âm như nhau nhưng khác nghĩa. -(으)로서 nghĩa là "với tư cách / trong vai trò (vai trò/địa vị) của" và chỉ gắn vào danh từ: 부모로서 "với tư cách cha mẹ", 학생으로서 "với tư cách học sinh", 친구로서 "với tư cách bạn bè". -(으)로써 nghĩa là "bằng / với / sử dụng" và đánh dấu phương pháp, công cụ hoặc nguyên liệu: 대화로써 "bằng đối thoại", 노력으로써 "thông qua nỗ lực". Cả hai đều theo cùng một quy tắc biến thể: sau nguyên âm hoặc ㄹ thì dùng 로서/로써 (친구 → 친구로서, 대화 → 대화로써), và sau phụ âm 받침 thì dùng 으로서/으로써 (학생 → 학생으로서, 노력 → 노력으로써). Chúng gắn trực tiếp vào danh từ; để áp dụng cho động từ, trước tiên hãy danh từ hóa nó (예: 노력함으로써 "bằng việc nỗ lực").\n\nSự nhầm lẫn kinh điển nằm ở chính hai dạng này, nên hãy dùng một cặp tối thiểu: 교사로서 말한다 nghĩa là "tôi nói với tư cách giáo viên (trong vai trò của mình)", trong khi 교사로써 무엇을 할 수 있을까 lại dùng nhầm trợ từ "phương tiện" cho một vai trò. Hãy so sánh 칼로서 với 칼로써: chỉ có 칼로써 (자르다) "cắt bằng dao" là đúng, vì con dao là công cụ, không phải vai trò. Sắc thái trung tính và khá trang trọng/văn viết; trong lời nói hằng ngày, dạng công cụ đơn giản 로/으로 thường thay thế 로써 (칼로 잘라요). Lỗi phổ biến nhất của người học là đảo lẫn hai dạng: hãy nhớ 로서 = 자격 (tư cách/vai trò), 로써 = 수단 (phương tiện/phương pháp). Mẹo ghi nhớ: chữ 써 trong 로써 vọng lại 쓰다 "dùng".',
      '-(으)로서 と -(으)로써 はほぼ同じ形のペアで、話すと同じように聞こえますが意味が異なります。-(으)로서 は「~として／（役割・身分の）資格で」という意味で、名詞にのみ付きます：부모로서「親として」、학생으로서「学生として」、친구로서「友人として」。-(으)로써 は「~によって／~で／~を用いて」という意味で、手段・道具・材料を表します：대화로써「対話によって」、노력으로써「努力によって」。どちらも同じ異形態の規則に従います。母音または ㄹ の後では 로서/로써 を使い（친구 → 친구로서、대화 → 대화로써）、子音の 받침 の後では 으로서/으로써 を使います（학생 → 학생으로서、노력 → 노력으로써）。名詞には直接付きます。動詞に付けるには、まず名詞化してください（예：노력함으로써「努力することによって」）。\n\n典型的な混同はこの二つの間で起こるので、最小対を使いましょう：교사로서 말한다 は「教師として（その役割で）話す」を意味しますが、교사로써 무엇을 할 수 있을까 は役割に対して「手段」の助詞を誤って使っています。칼로서 と 칼로써 を比べてください：칼은 道具であって役割ではないので、칼로써 (자르다)「ナイフで切る」だけが正しいです。文体は中立的でやや改まった書き言葉寄りで、日常会話では単純な道具の 로/으로 が 로써 の代わりによく使われます（칼로 잘라요）。学習者が最もよくする間違いは両者を入れ替えることです。로서 = 자격（資格・役割）、로써 = 수단（手段・方法）と覚えましょう。記憶のヒント：로써 の 써 は 쓰다「使う」を響かせています。',
    ),
  '-았/었더라면': L(
      '-았/었더라면 marks a *past counterfactual* condition — "if (only) I/you had ...", looking back at something that did NOT happen and speculating about its result. It attaches after the past marker -았/었-, chosen by the stem\'s final vowel: bright vowels ㅏ/ㅗ take -았더라면 (가다 → 갔더라면 "if I had gone", 오다 → 왔더라면), other vowels take -었더라면 (먹다 → 먹었더라면 "if I had eaten", 읽다 → 읽었더라면). 하다 verbs become 했더라면 (공부하다 → 공부했더라면 "if I had studied"). Nouns go through 이다, with the 받침-sensitive past form: 학생이었더라면 "if I had been a student", 의사였더라면 "if I had been a doctor". The second clause normally carries -았/었을 텐데 or -았/었을 거예요 to voice the imagined (and now impossible) outcome: 일찍 출발했더라면 늦지 않았을 텐데 "if I\'d left early, I wouldn\'t have been late."\n\nThe closest *open* neighbour is plain -(으)면, a neutral condition that can still come true: 비가 오면 소풍을 취소할 거예요 "if it rains, we\'ll cancel the picnic" leaves the door open, whereas 비가 왔더라면 좋았을 텐데 "if only it had rained (it didn\'t)" firmly closes it and adds regret or relief. Its nearest *counterfactual* synonym, though, is -았/었으면 (+ 좋았을 텐데), which carries almost the same "had ..." regret and is interchangeable in most sentences; -았/었더라면 simply sounds a touch more deliberate and bookish. Register: it is neutral and works in both 해요 and 합니다 speech, common in writing and in heartfelt spoken regret. The most frequent learner mistake is dropping the past -았/었- and writing a bare -더라면 (먹더라면) — without the past marker the counterfactual "had done" reading collapses, so the -았/었- is effectively obligatory here. It pairs naturally with 그때 ("back then") or 진작 ("sooner") to sharpen the regret: 진작 말했더라면 "if only I\'d said so sooner."',
      '-았/었더라면 marca una *condición contrafáctica en pasado* — "si (tan solo) hubiera/hubieras ...", mirando hacia atrás a algo que NO ocurrió y especulando sobre su resultado. Se une después del marcador de pasado -았/었-, elegido según la vocal final de la raíz: las vocales brillantes ㅏ/ㅗ toman -았더라면 (가다 → 갔더라면 "si hubiera ido", 오다 → 왔더라면), las demás vocales toman -었더라면 (먹다 → 먹었더라면 "si hubiera comido", 읽다 → 읽었더라면 "si hubiera leído"). Los verbos con 하다 se vuelven 했더라면 (공부하다 → 공부했더라면 "si hubiera estudiado"). Los sustantivos pasan por 이다, con la forma de pasado sensible al 받침: 학생이었더라면 "si hubiera sido estudiante", 의사였더라면 "si hubiera sido médico". La segunda cláusula normalmente lleva -았/었을 텐데 o -았/었을 거예요 para expresar el resultado imaginado (y ahora imposible): 일찍 출발했더라면 늦지 않았을 텐데 "si hubiera salido temprano, no habría llegado tarde".\n\nEl vecino *abierto* más cercano es el simple -(으)면, una condición neutral que todavía puede cumplirse: 비가 오면 소풍을 취소할 거예요 "si llueve, cancelaremos el picnic" deja la puerta abierta, mientras que 비가 왔더라면 좋았을 텐데 "si tan solo hubiera llovido (no llovió)" la cierra firmemente y agrega arrepentimiento o alivio. Su sinónimo *contrafáctico* más cercano, sin embargo, es -았/었으면 (+ 좋았을 텐데), que lleva casi el mismo arrepentimiento de "si hubiera ..." y es intercambiable en la mayoría de las oraciones; -았/었더라면 simplemente suena un poco más deliberado y libresco. Registro: es neutral y funciona tanto en el habla 해요 como 합니다, común en la escritura y en el arrepentimiento sincero al hablar. El error más frecuente del estudiante es omitir el pasado -았/었- y escribir un -더라면 desnudo (먹더라면) — sin el marcador de pasado, la lectura contrafáctica de "hubiera hecho" se desploma, así que el -았/었- es aquí prácticamente obligatorio. Se combina naturalmente con 그때 ("en aquel entonces") o 진작 ("antes") para afilar el arrepentimiento: 진작 말했더라면 "si tan solo lo hubiera dicho antes".',
      '-았/었더라면 marque une *condition contrefactuelle au passé* — « si (seulement) j\'avais / tu avais ... », en regardant en arrière vers quelque chose qui NE s\'est PAS produit et en spéculant sur son résultat. Il s\'attache après le marqueur du passé -았/었-, choisi selon la voyelle finale du radical : les voyelles claires ㅏ/ㅗ prennent -았더라면 (가다 → 갔더라면 « si j\'étais allé », 오다 → 왔더라면), les autres voyelles prennent -었더라면 (먹다 → 먹었더라면 « si j\'avais mangé », 읽다 → 읽었더라면 « si j\'avais lu »). Les verbes en 하다 deviennent 했더라면 (공부하다 → 공부했더라면 « si j\'avais étudié »). Les noms passent par 이다, avec la forme du passé sensible au 받침 : 학생이었더라면 « si j\'avais été étudiant », 의사였더라면 « si j\'avais été médecin ». La seconde proposition porte normalement -았/었을 텐데 ou -았/었을 거예요 pour exprimer le résultat imaginé (et désormais impossible) : 일찍 출발했더라면 늦지 않았을 텐데 « si j\'étais parti tôt, je n\'aurais pas été en retard ».\n\nLe voisin *ouvert* le plus proche est le simple -(으)면, une condition neutre qui peut encore se réaliser : 비가 오면 소풍을 취소할 거예요 « s\'il pleut, nous annulerons le pique-nique » laisse la porte ouverte, tandis que 비가 왔더라면 좋았을 텐데 « si seulement il avait plu (il n\'a pas plu) » la ferme fermement et ajoute du regret ou du soulagement. Son synonyme *contrefactuel* le plus proche, cependant, est -았/었으면 (+ 좋았을 텐데), qui porte presque le même regret de « si j\'avais ... » et est interchangeable dans la plupart des phrases ; -았/었더라면 sonne simplement un peu plus délibéré et littéraire. Registre : il est neutre et fonctionne aussi bien dans le langage 해요 que 합니다, courant à l\'écrit et dans le regret sincère à l\'oral. L\'erreur la plus fréquente des apprenants est d\'omettre le passé -았/었- et d\'écrire un -더라면 nu (먹더라면) — sans le marqueur du passé, la lecture contrefactuelle « j\'aurais fait » s\'effondre, donc le -았/었- est ici en pratique obligatoire. Il se combine naturellement avec 그때 (« à l\'époque ») ou 진작 (« plus tôt ») pour aiguiser le regret : 진작 말했더라면 « si seulement je l\'avais dit plus tôt ».',
      '-았/었더라면 marca uma *condição contrafactual no passado* — "se (ao menos) eu/você tivesse ...", olhando para trás para algo que NÃO aconteceu e especulando sobre o seu resultado. Ele se anexa depois do marcador de passado -았/었-, escolhido conforme a vogal final do radical: as vogais claras ㅏ/ㅗ recebem -았더라면 (가다 → 갔더라면 "se eu tivesse ido", 오다 → 왔더라면), as outras vogais recebem -었더라면 (먹다 → 먹었더라면 "se eu tivesse comido", 읽다 → 읽었더라면 "se eu tivesse lido"). Os verbos com 하다 viram 했더라면 (공부하다 → 공부했더라면 "se eu tivesse estudado"). Os substantivos passam por 이다, com a forma de passado sensível ao 받침: 학생이었더라면 "se eu tivesse sido estudante", 의사였더라면 "se eu tivesse sido médico". A segunda oração normalmente leva -았/었을 텐데 ou -았/었을 거예요 para expressar o resultado imaginado (e agora impossível): 일찍 출발했더라면 늦지 않았을 텐데 "se eu tivesse saído cedo, não teria me atrasado".\n\nO vizinho *aberto* mais próximo é o simples -(으)면, uma condição neutra que ainda pode se concretizar: 비가 오면 소풍을 취소할 거예요 "se chover, vamos cancelar o piquenique" deixa a porta aberta, enquanto 비가 왔더라면 좋았을 텐데 "se ao menos tivesse chovido (não choveu)" a fecha firmemente e acrescenta arrependimento ou alívio. Seu sinônimo *contrafactual* mais próximo, porém, é -았/었으면 (+ 좋았을 텐데), que carrega quase o mesmo arrependimento de "se eu tivesse ..." e é intercambiável na maioria das frases; -았/었더라면 apenas soa um pouco mais deliberado e literário. Registro: é neutro e funciona tanto na fala 해요 quanto 합니다, comum na escrita e no arrependimento sincero ao falar. O erro mais frequente dos aprendizes é omitir o passado -았/었- e escrever um -더라면 nu (먹더라면) — sem o marcador de passado, a leitura contrafactual de "teria feito" desmorona, então o -았/었- é aqui praticamente obrigatório. Combina naturalmente com 그때 ("naquela época") ou 진작 ("mais cedo") para aguçar o arrependimento: 진작 말했더라면 "se ao menos eu tivesse dito mais cedo".',
      '-았/었더라면 บ่งบอก *เงื่อนไขที่ขัดกับความจริงในอดีต* — "ถ้า (เพียงแต่) ฉัน/คุณ ได้ ... ไปแล้ว" โดยมองย้อนกลับไปยังสิ่งที่ไม่ได้เกิดขึ้นจริงและคาดเดาถึงผลลัพธ์ของมัน มันต่อท้ายเครื่องหมายอดีต -았/었- ซึ่งเลือกตามสระตัวสุดท้ายของรากศัพท์: สระสว่าง ㅏ/ㅗ ใช้ -았더라면 (가다 → 갔더라면 "ถ้าฉันได้ไป", 오다 → 왔더라면) สระอื่น ๆ ใช้ -었더라면 (먹다 → 먹었더라면 "ถ้าฉันได้กิน", 읽다 → 읽었더라면 "ถ้าฉันได้อ่าน") คำกริยา 하다 จะกลายเป็น 했더라면 (공부하다 → 공부했더라면 "ถ้าฉันได้เรียน") คำนามผ่าน 이다 ด้วยรูปอดีตที่ขึ้นกับ 받침: 학생이었더라면 "ถ้าฉันได้เป็นนักเรียน", 의사였더라면 "ถ้าฉันได้เป็นหมอ" อนุประโยคที่สองโดยปกติจะมี -았/었을 텐데 หรือ -았/었을 거예요 เพื่อบอกผลลัพธ์ที่จินตนาการขึ้น (และตอนนี้เป็นไปไม่ได้แล้ว): 일찍 출발했더라면 늦지 않았을 텐데 "ถ้าฉันออกเดินทางแต่เนิ่น ๆ ก็คงไม่สาย"\n\nเพื่อนบ้านที่ *เปิดกว้าง* ที่สุดคือ -(으)면 ธรรมดา ซึ่งเป็นเงื่อนไขที่เป็นกลางและยังเกิดขึ้นได้: 비가 오면 소풍을 취소할 거예요 "ถ้าฝนตก เราจะยกเลิกการไปปิกนิก" ยังเปิดประตูทิ้งไว้ ในขณะที่ 비가 왔더라면 좋았을 텐데 "ถ้าเพียงแต่ฝนตก (แต่มันไม่ตก)" ปิดประตูอย่างแน่นหนาและเพิ่มความเสียดายหรือความโล่งใจเข้าไป แต่คำพ้องความหมายแบบ *ขัดกับความจริง* ที่ใกล้เคียงที่สุดคือ -았/었으면 (+ 좋았을 텐데) ซึ่งให้ความรู้สึกเสียดายแบบ "ได้ ... ไปแล้ว" เกือบเหมือนกันและใช้แทนกันได้ในประโยคส่วนใหญ่; -았/었더라면 เพียงแต่ฟังดูจงใจและเป็นทางการหรือเป็นภาษาเขียนมากกว่าเล็กน้อย ระดับภาษา: เป็นกลางและใช้ได้ทั้งในการพูดแบบ 해요 และ 합니다 พบบ่อยในงานเขียนและในการพูดแสดงความเสียดายอย่างจริงใจ ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือการละเครื่องหมายอดีต -았/었- แล้วเขียน -더라면 เปล่า ๆ (먹더라면) — หากไม่มีเครื่องหมายอดีต ความหมายแบบขัดกับความจริง "ได้ทำไปแล้ว" จะพังทลายลง ดังนั้น -았/었- จึงแทบจะเป็นสิ่งบังคับในที่นี้ มันเข้าคู่ได้อย่างเป็นธรรมชาติกับ 그때 ("ตอนนั้น") หรือ 진작 ("ตั้งแต่เนิ่น ๆ") เพื่อเน้นย้ำความเสียดาย: 진작 말했더라면 "ถ้าเพียงแต่ฉันได้พูดเสียตั้งแต่เนิ่น ๆ"',
      '-았/었더라면 menandai *kondisi kontrafaktual pada masa lampau* — "seandainya (saja) saya/kamu sudah ...", menengok kembali ke sesuatu yang TIDAK terjadi dan berspekulasi tentang hasilnya. Ia melekat setelah penanda lampau -았/었-, yang dipilih berdasarkan vokal akhir akar kata: vokal terang ㅏ/ㅗ mengambil -았더라면 (가다 → 갔더라면 "seandainya saya pergi", 오다 → 왔더라면), vokal lain mengambil -었더라면 (먹다 → 먹었더라면 "seandainya saya makan", 읽다 → 읽었더라면 "seandainya saya membaca"). Kata kerja 하다 menjadi 했더라면 (공부하다 → 공부했더라면 "seandainya saya belajar"). Kata benda melewati 이다, dengan bentuk lampau yang peka terhadap 받침: 학생이었더라면 "seandainya saya seorang pelajar", 의사였더라면 "seandainya saya seorang dokter". Klausa kedua biasanya membawa -았/었을 텐데 atau -았/었을 거예요 untuk menyuarakan hasil yang dibayangkan (dan kini mustahil): 일찍 출발했더라면 늦지 않았을 텐데 "seandainya saya berangkat lebih awal, saya tidak akan terlambat".\n\nTetangga *terbuka* yang paling dekat adalah -(으)면 biasa, sebuah kondisi netral yang masih bisa terwujud: 비가 오면 소풍을 취소할 거예요 "jika hujan, kita akan membatalkan piknik" membiarkan pintu tetap terbuka, sedangkan 비가 왔더라면 좋았을 텐데 "seandainya saja hujan (ternyata tidak)" menutupnya dengan tegas dan menambahkan penyesalan atau kelegaan. Namun, sinonim *kontrafaktual* yang paling dekat adalah -았/었으면 (+ 좋았을 텐데), yang membawa penyesalan "seandainya sudah ..." yang nyaris sama dan dapat dipertukarkan dalam sebagian besar kalimat; -았/었더라면 hanya terdengar sedikit lebih disengaja dan kebukuan. Ragam: ia netral dan berfungsi baik dalam tutur 해요 maupun 합니다, lazim dalam tulisan dan dalam penyesalan tulus saat berbicara. Kesalahan pemelajar yang paling sering adalah menghilangkan penanda lampau -았/었- dan menulis -더라면 telanjang (먹더라면) — tanpa penanda lampau, pembacaan kontrafaktual "sudah melakukan" runtuh, sehingga -았/었- di sini praktis wajib. Ia berpasangan secara alami dengan 그때 ("waktu itu") atau 진작 ("lebih awal") untuk menajamkan penyesalan: 진작 말했더라면 "seandainya saja saya mengatakannya lebih awal".',
      '-았/었더라면 đánh dấu một *điều kiện phản thực ở quá khứ* — "giá (mà) tôi/bạn đã ...", nhìn lại một điều đã KHÔNG xảy ra và suy đoán về kết quả của nó. Nó gắn sau dấu hiệu quá khứ -았/었-, được chọn theo nguyên âm cuối của thân từ: nguyên âm sáng ㅏ/ㅗ dùng -았더라면 (가다 → 갔더라면 "giá mà tôi đã đi", 오다 → 왔더라면), các nguyên âm khác dùng -었더라면 (먹다 → 먹었더라면 "giá mà tôi đã ăn", 읽다 → 읽었더라면 "giá mà tôi đã đọc"). Động từ 하다 trở thành 했더라면 (공부하다 → 공부했더라면 "giá mà tôi đã học"). Danh từ đi qua 이다, với dạng quá khứ nhạy cảm với 받침: 학생이었더라면 "giá mà tôi đã là học sinh", 의사였더라면 "giá mà tôi đã là bác sĩ". Mệnh đề thứ hai thường mang -았/었을 텐데 hoặc -았/었을 거예요 để nói lên kết quả tưởng tượng (và giờ đã không thể xảy ra): 일찍 출발했더라면 늦지 않았을 텐데 "giá mà tôi đã đi sớm thì đã không bị muộn".\n\nNgười hàng xóm *để ngỏ* gần nhất là -(으)면 đơn thuần, một điều kiện trung tính vẫn còn có thể thành hiện thực: 비가 오면 소풍을 취소할 거예요 "nếu trời mưa, chúng ta sẽ hủy buổi dã ngoại" vẫn để cửa ngỏ, trong khi 비가 왔더라면 좋았을 텐데 "giá mà trời đã mưa (nhưng đã không mưa)" đóng chặt cửa lại và thêm vào sự tiếc nuối hoặc nhẹ nhõm. Tuy nhiên, từ đồng nghĩa *phản thực* gần nhất của nó là -았/었으면 (+ 좋았을 텐데), vốn mang gần như cùng một sự tiếc nuối "giá mà đã ..." và có thể thay thế cho nhau trong hầu hết các câu; -았/었더라면 chỉ nghe có vẻ chủ ý và mang tính văn viết hơn một chút. Ngữ vực: nó trung tính và dùng được cả trong lối nói 해요 lẫn 합니다, phổ biến trong văn viết và trong sự tiếc nuối chân thành khi nói. Lỗi thường gặp nhất của người học là bỏ dấu quá khứ -았/었- và viết một -더라면 trơ trọi (먹더라면) — nếu không có dấu hiệu quá khứ, nghĩa phản thực "đã làm" sẽ sụp đổ, nên ở đây -았/었- gần như bắt buộc. Nó kết hợp tự nhiên với 그때 ("hồi đó") hoặc 진작 ("sớm hơn") để làm sắc nét thêm sự tiếc nuối: 진작 말했더라면 "giá mà tôi đã nói ra sớm hơn".',
      '-았/었더라면 は *過去の反事実* の条件を表します ——「(もし)…していたら」と、実際には起こらなかったことを振り返り、その結果を推測する表現です。過去の標識 -았/었- の後に付き、語幹の最後の母音によって選ばれます。明るい母音 ㅏ/ㅗ は -았더라면 をとり(가다 → 갔더라면「行っていたら」、오다 → 왔더라면)、その他の母音は -었더라면 をとります(먹다 → 먹었더라면「食べていたら」、읽다 → 읽었더라면「読んでいたら」)。하다 動詞は 했더라면 になります(공부하다 → 공부했더라면「勉強していたら」)。名詞は 이다 を介し、받침 に応じた過去形になります:학생이었더라면「学生だったら」、의사였더라면「医者だったら」。後半の節は通常、想像上の(そして今や不可能な)結果を述べるために -았/었을 텐데 または -았/었을 거예요 を伴います:일찍 출발했더라면 늦지 않았을 텐데「早く出発していたら、遅れなかったのに」。\n\n最も近い *開かれた* 隣人は単なる -(으)면 で、これはまだ実現しうる中立的な条件です。비가 오면 소풍을 취소할 거예요「雨が降れば、ピクニックを中止します」は可能性を残しますが、비가 왔더라면 좋았을 텐데「雨が降っていたらよかったのに(降らなかった)」はそれをきっぱりと閉じ、後悔や安堵を加えます。ただし、最も近い *反事実* の類義語は -았/었으면 (+ 좋았을 텐데) で、ほぼ同じ「…していたら」という後悔を帯び、ほとんどの文で置き換え可能です。-았/었더라면 は単に少し意図的で文語的に聞こえるだけです。文体:中立的で、해요 体でも 합니다 体でも使え、書き言葉でも心のこもった話し言葉の後悔でもよく使われます。学習者が最も犯しやすい誤りは、過去の -았/었- を落として裸の -더라면 を書いてしまうこと(먹더라면)です ——過去の標識がなければ「…していたら」という反事実の解釈が崩れてしまうため、ここでの -았/었- は事実上必須です。後悔を鋭くするために、그때「あの時」や 진작「もっと早く」と自然に組み合わさります:진작 말했더라면「もっと早く言っていたら」。',
    ),
  '-ㄴ/는다는 것이': L(
      'The pattern -(ㄴ/는)다는 것이 reports that you set out to do one thing but, by accident, an unintended (often unfortunate) result came about — "I meant to..., but ended up...". It builds on the indirect-quotation form -(ㄴ/는)다고 하다, contracted into the noun-modifier -(ㄴ/는)다는 ("the ...-ing that I say/intend") plus 것이 ("the thing"). Attach -ㄴ다 to a vowel/ㄹ verb stem (자다 → 잔다는 것이 "I meant to sleep, but...", 만들다 → 만든다는 것이, ㄹ drops) and -는다 to a consonant stem (먹다 → 먹는다는 것이 "I meant to eat just a bit, but..."). Only action verbs take this; adjectives and 이다 do not. Example: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "I meant to rest a moment, but ended up sleeping a full two hours."\n\nThe closest neighbour is -(으)려고 했는데 ("I tried/intended to ... but"). Both express a thwarted plan, yet -(으)려고 했는데 reports a deliberate intention that simply didn\'t happen, while -(ㄴ/는)다는 것이 stresses that your own action slipped and produced the wrong outcome by mistake. Compare 소금을 넣으려고 했는데 안 넣었어요 "I meant to add salt but didn\'t (forgot)" with 소금을 넣는다는 것이 설탕을 넣었어요 "meaning to add salt, I ended up adding sugar (by mistake)" — the second always carries that botched, slip-of-the-hand nuance. It is style-neutral and combines with any politeness ending (the resulting clause is usually -았/었어요 or -아/어 버렸어요). The frequent learner mistake is using it with mere unfulfilled plans where -(으)려고 했는데 is needed, and forgetting that the verb must stay in the -ㄴ/는다 present form even though the real event is past. In speech the 것이 is regularly contracted to 게: 산다는 게, 본다는 게.',
      'El patrón -(ㄴ/는)다는 것이 expresa que te propusiste hacer una cosa pero, por accidente, terminó pasando algo no buscado (a menudo desafortunado): "quería..., pero terminé...". Se construye sobre la forma de cita indirecta -(ㄴ/는)다고 하다, contraída en el modificador nominal -(ㄴ/는)다는 ("eso que digo/me propongo hacer") más 것이 ("la cosa"). Agregá -ㄴ다 a una raíz verbal terminada en vocal o en ㄹ (자다 → 잔다는 것이 "iba a dormir, pero...", 만들다 → 만든다는 것이, la ㄹ se cae) y -는다 a una raíz terminada en consonante (먹다 → 먹는다는 것이 "iba a comer solo un poco, pero..."). Solo los verbos de acción lo toman; los adjetivos y 이다 no. Ejemplo: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "quería descansar un momento, pero terminé durmiendo dos horas enteras".\n\nEl vecino más cercano es -(으)려고 했는데 ("intenté/quería... pero"). Ambos expresan un plan frustrado, pero -(으)려고 했는데 reporta una intención deliberada que simplemente no se concretó, mientras que -(ㄴ/는)다는 것이 enfatiza que tu propia acción se te escapó y produjo el resultado equivocado por error. Compará 소금을 넣으려고 했는데 안 넣었어요 "quería echar sal pero no lo hice (me olvidé)" con 소금을 넣는다는 것이 설탕을 넣었어요 "queriendo echar sal, terminé echando azúcar (por error)": la segunda siempre lleva ese matiz de descuido, de mano que se equivoca. Es neutral en cuanto a estilo y se combina con cualquier terminación de cortesía (la cláusula resultante suele ser -았/었어요 o -아/어 버렸어요). El error frecuente del estudiante es usarlo con simples planes incumplidos donde hace falta -(으)려고 했는데, y olvidar que el verbo debe quedar en la forma de presente -ㄴ/는다 aunque el hecho real sea pasado. En el habla, 것이 se contrae habitualmente a 게: 산다는 게, 본다는 게.',
      'Le schéma -(ㄴ/는)다는 것이 indique que tu avais l\'intention de faire une chose mais que, par accident, un résultat non voulu (souvent malheureux) s\'est produit — « je voulais..., mais j\'ai fini par... ». Il se construit sur la forme de discours indirect -(ㄴ/는)다고 하다, contractée en modificateur nominal -(ㄴ/는)다는 (« ce que je dis/compte faire ») plus 것이 (« la chose »). Ajoute -ㄴ다 à une base verbale terminée par une voyelle ou par ㄹ (자다 → 잔다는 것이 « je voulais dormir, mais... », 만들다 → 만든다는 것이, le ㄹ tombe) et -는다 à une base terminée par une consonne (먹다 → 먹는다는 것이 « je voulais juste manger un peu, mais... »). Seuls les verbes d\'action le prennent ; les adjectifs et 이다 ne le prennent pas. Exemple : 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 « je voulais me reposer un instant, mais j\'ai fini par dormir deux heures entières ».\n\nLe voisin le plus proche est -(으)려고 했는데 (« j\'ai essayé/voulu... mais »). Tous deux expriment un plan contrarié, mais -(으)려고 했는데 rapporte une intention délibérée qui ne s\'est tout simplement pas réalisée, tandis que -(ㄴ/는)다는 것이 souligne que ta propre action a dérapé et a produit le mauvais résultat par erreur. Compare 소금을 넣으려고 했는데 안 넣었어요 « je voulais ajouter du sel mais je ne l\'ai pas fait (j\'ai oublié) » avec 소금을 넣는다는 것이 설탕을 넣었어요 « voulant ajouter du sel, j\'ai fini par ajouter du sucre (par erreur) » — la seconde porte toujours cette nuance de bévue, de geste qui dérape. Il est neutre du point de vue du style et se combine avec n\'importe quelle terminaison de politesse (la proposition résultante est généralement en -았/었어요 ou -아/어 버렸어요). L\'erreur fréquente de l\'apprenant est de l\'employer pour de simples projets non réalisés là où il faut -(으)려고 했는데, et d\'oublier que le verbe doit rester à la forme de présent -ㄴ/는다 même si l\'événement réel est au passé. À l\'oral, 것이 se contracte régulièrement en 게 : 산다는 게, 본다는 게.',
      'O padrão -(ㄴ/는)다는 것이 expressa que você pretendia fazer uma coisa mas, por acidente, acabou acontecendo um resultado não pretendido (muitas vezes infeliz) — "eu queria..., mas acabei...". Ele se constrói a partir da forma de citação indireta -(ㄴ/는)다고 하다, contraída no modificador nominal -(ㄴ/는)다는 ("aquilo que eu digo/pretendo fazer") mais 것이 ("a coisa"). Acrescente -ㄴ다 a uma raiz verbal terminada em vogal ou em ㄹ (자다 → 잔다는 것이 "eu ia dormir, mas...", 만들다 → 만든다는 것이, o ㄹ cai) e -는다 a uma raiz terminada em consoante (먹다 → 먹는다는 것이 "eu ia comer só um pouco, mas..."). Só os verbos de ação aceitam isso; adjetivos e 이다 não. Exemplo: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "eu queria descansar um instante, mas acabei dormindo duas horas inteiras".\n\nO vizinho mais próximo é -(으)려고 했는데 ("eu tentei/pretendia... mas"). Ambos expressam um plano frustrado, mas -(으)려고 했는데 relata uma intenção deliberada que simplesmente não se concretizou, enquanto -(ㄴ/는)다는 것이 enfatiza que a sua própria ação escapou e produziu o resultado errado por engano. Compare 소금을 넣으려고 했는데 안 넣었어요 "eu queria pôr sal mas não pus (esqueci)" com 소금을 넣는다는 것이 설탕을 넣었어요 "querendo pôr sal, acabei pondo açúcar (por engano)" — a segunda sempre carrega aquela nuance de descuido, de mão que escorrega. É neutro quanto ao estilo e combina com qualquer terminação de cortesia (a oração resultante costuma ser -았/었어요 ou -아/어 버렸어요). O erro frequente do aprendiz é usá-lo com meros planos não cumpridos, onde é necessário -(으)려고 했는데, e esquecer que o verbo deve permanecer na forma de presente -ㄴ/는다 mesmo que o evento real seja passado. Na fala, 것이 é regularmente contraído para 게: 산다는 게, 본다는 게.',
      'รูปแบบ -(ㄴ/는)다는 것이 บอกว่าคุณตั้งใจจะทำสิ่งหนึ่ง แต่เกิดเหตุบังเอิญทำให้ได้ผลลัพธ์ที่ไม่ได้ตั้งใจ (มักเป็นผลที่ไม่ดี) ขึ้นมาแทน — "ตั้งใจจะ... แต่กลับ...". รูปนี้สร้างขึ้นจากรูปการอ้างถึงทางอ้อม -(ㄴ/는)다고 하다 ที่ย่อรวมเป็นตัวขยายนาม -(ㄴ/는)다는 ("สิ่งที่ฉันพูด/ตั้งใจจะทำ") บวกกับ 것이 ("สิ่งนั้น"). เติม -ㄴ다 หลังรากกริยาที่ลงท้ายด้วยสระหรือ ㄹ (자다 → 잔다는 것이 "ตั้งใจจะนอน แต่...", 만들다 → 만든다는 것이 โดย ㄹ หลุดหายไป) และเติม -는다 หลังรากที่ลงท้ายด้วยพยัญชนะ (먹다 → 먹는다는 것이 "ตั้งใจจะกินแค่นิดเดียว แต่..."). มีแต่กริยาแสดงการกระทำเท่านั้นที่ใช้รูปนี้ได้ คำคุณศัพท์และ 이다 ใช้ไม่ได้. ตัวอย่าง: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "ตั้งใจจะพักแค่ครู่เดียว แต่กลับนอนไปตั้งสองชั่วโมงเต็มๆ".\n\nรูปที่ใกล้เคียงที่สุดคือ -(으)려고 했는데 ("พยายาม/ตั้งใจจะ... แต่"). ทั้งสองรูปสื่อถึงแผนที่ไม่เป็นไปตามที่หวัง แต่ -(으)려고 했는데 บอกถึงความตั้งใจที่จงใจแล้วไม่ได้เกิดขึ้นเฉยๆ ขณะที่ -(ㄴ/는)다는 것이 เน้นว่าการกระทำของคุณเองพลาดไปและให้ผลลัพธ์ที่ผิดโดยไม่ตั้งใจ. เปรียบเทียบ 소금을 넣으려고 했는데 안 넣었어요 "ตั้งใจจะใส่เกลือ แต่ไม่ได้ใส่ (ลืม)" กับ 소금을 넣는다는 것이 설탕을 넣었어요 "ตั้งใจจะใส่เกลือ แต่กลับใส่น้ำตาลไป (โดยพลาด)" — รูปหลังจะมีนัยของความพลาดพลั้ง ทำมือไปผิดเสมอ. รูปนี้เป็นกลางทางระดับภาษา และเข้ากับการลงท้ายแบบสุภาพได้ทุกแบบ (อนุประโยคที่ตามมามักลงท้ายด้วย -았/었어요 หรือ -아/어 버렸어요). ข้อผิดพลาดที่ผู้เรียนมักทำคือเอาไปใช้กับแผนที่แค่ไม่สำเร็จซึ่งต้องใช้ -(으)려고 했는데, และลืมว่ากริยาต้องคงรูปปัจจุบัน -ㄴ/는다 ไว้แม้เหตุการณ์จริงจะเป็นอดีต. ในภาษาพูด 것이 มักย่อเป็น 게: 산다는 게, 본다는 게.',
      'Pola -(ㄴ/는)다는 것이 menyatakan bahwa kamu bermaksud melakukan satu hal, tetapi secara tidak sengaja muncul hasil yang tidak diinginkan (sering kali tidak menguntungkan) — "aku bermaksud..., tapi malah...". Pola ini dibangun dari bentuk kutipan tidak langsung -(ㄴ/는)다고 하다, yang dikontraksikan menjadi pemodifikasi nomina -(ㄴ/는)다는 ("hal yang kukatakan/kuniatkan") ditambah 것이 ("hal itu"). Tambahkan -ㄴ다 pada akar kata kerja berakhiran vokal atau ㄹ (자다 → 잔다는 것이 "aku bermaksud tidur, tapi...", 만들다 → 만든다는 것이, ㄹ-nya luruh) dan -는다 pada akar berakhiran konsonan (먹다 → 먹는다는 것이 "aku bermaksud makan sedikit saja, tapi..."). Hanya kata kerja tindakan yang bisa memakainya; kata sifat dan 이다 tidak bisa. Contoh: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "aku bermaksud istirahat sebentar, tapi malah tertidur sampai dua jam penuh".\n\nPola yang paling mirip adalah -(으)려고 했는데 ("aku mencoba/bermaksud... tapi"). Keduanya mengungkapkan rencana yang gagal, tetapi -(으)려고 했는데 melaporkan niat yang disengaja yang sekadar tidak terjadi, sedangkan -(ㄴ/는)다는 것이 menekankan bahwa tindakanmu sendiri meleset dan menghasilkan hasil yang salah karena keliru. Bandingkan 소금을 넣으려고 했는데 안 넣었어요 "aku bermaksud menambahkan garam tapi tidak jadi (lupa)" dengan 소금을 넣는다는 것이 설탕을 넣었어요 "bermaksud menambahkan garam, aku malah menambahkan gula (keliru)" — kalimat kedua selalu membawa nuansa keteledoran, salah tangan itu. Pola ini netral dari segi gaya dan bisa digabung dengan akhiran kesopanan apa pun (klausa yang dihasilkan biasanya -았/었어요 atau -아/어 버렸어요). Kesalahan yang sering dilakukan pembelajar adalah memakainya untuk sekadar rencana yang tidak terlaksana, padahal yang diperlukan adalah -(으)려고 했는데, serta lupa bahwa kata kerjanya harus tetap dalam bentuk kini -ㄴ/는다 meskipun peristiwa sebenarnya sudah lampau. Dalam percakapan, 것이 lazim dikontraksikan menjadi 게: 산다는 게, 본다는 게.',
      'Cấu trúc -(ㄴ/는)다는 것이 diễn tả rằng bạn định làm một việc nhưng do vô tình, một kết quả ngoài ý muốn (thường là không hay) lại xảy ra — "tôi định..., nhưng rốt cuộc lại...". Nó được dựng từ dạng trích dẫn gián tiếp -(ㄴ/는)다고 하다, rút gọn thành định ngữ bổ nghĩa cho danh từ -(ㄴ/는)다는 ("cái việc mà tôi nói/định làm") cộng với 것이 ("cái việc"). Gắn -ㄴ다 vào gốc động từ kết thúc bằng nguyên âm hoặc ㄹ (자다 → 잔다는 것이 "tôi định ngủ, nhưng...", 만들다 → 만든다는 것이, ㄹ bị rụng) và gắn -는다 vào gốc kết thúc bằng phụ âm (먹다 → 먹는다는 것이 "tôi định ăn một chút thôi, nhưng..."). Chỉ động từ hành động mới dùng được; tính từ và 이다 thì không. Ví dụ: 잠깐 쉰다는 것이 두 시간이나 자 버렸어요 "tôi định nghỉ một lát, nhưng rốt cuộc lại ngủ hẳn hai tiếng đồng hồ".\n\nCấu trúc gần gũi nhất là -(으)려고 했는데 ("tôi đã cố/định... nhưng"). Cả hai đều diễn tả một kế hoạch bị bất thành, nhưng -(으)려고 했는데 thuật lại một ý định có chủ đích mà đơn giản là đã không xảy ra, còn -(ㄴ/는)다는 것이 nhấn mạnh rằng chính hành động của bạn đã trượt đi và tạo ra kết quả sai do nhầm lẫn. Hãy so sánh 소금을 넣으려고 했는데 안 넣었어요 "tôi định cho muối nhưng đã không cho (quên mất)" với 소금을 넣는다는 것이 설탕을 넣었어요 "định cho muối, tôi rốt cuộc lại cho đường (do nhầm)" — câu thứ hai luôn mang sắc thái lóng ngóng, làm hớ tay đó. Nó trung tính về văn phong và kết hợp được với bất kỳ đuôi lịch sự nào (mệnh đề theo sau thường là -았/었어요 hoặc -아/어 버렸어요). Lỗi người học hay mắc là dùng nó cho những kế hoạch chỉ đơn thuần không thành nơi cần đến -(으)려고 했는데, và quên rằng động từ phải giữ ở dạng hiện tại -ㄴ/는다 dù sự việc thực tế đã thuộc về quá khứ. Trong khẩu ngữ, 것이 thường được rút gọn thành 게: 산다는 게, 본다는 게.',
      '-(ㄴ/는)다는 것이 は、あることをするつもりだったのに、うっかり意図しない（多くは残念な）結果になってしまった、ということを表します——「…しようとして、結局…してしまった」。これは間接引用の -(ㄴ/는)다고 하다 をもとに、名詞修飾形 -(ㄴ/는)다는（「…すると言う/しようとする」）に 것이（「こと」）が付いて縮約した形です。母音語幹や ㄹ 語幹には -ㄴ다 を付け（자다 → 잔다는 것이「寝ようとして…」、만들다 → 만든다는 것이、ㄹ は脱落）、子音語幹には -는다 を付けます（먹다 → 먹는다는 것이「ちょっとだけ食べようとして…」）。これを取るのは動作動詞だけで、形容詞や 이다 は使えません。例：잠깐 쉰다는 것이 두 시간이나 자 버렸어요「ちょっと休もうとして、結局まる二時間も寝てしまいました」。\n\n最も近いのは -(으)려고 했는데（「…しようとしたけれど」）です。どちらも頓挫した計画を表しますが、-(으)려고 했는데 は意図したことが単に実現しなかったと述べるのに対し、-(ㄴ/는)다는 것이 は自分の行動がうっかりずれて、間違った結果を引き起こしてしまった点を強調します。소금을 넣으려고 했는데 안 넣었어요「塩を入れようとしたけれど入れなかった（忘れた）」と、소금을 넣는다는 것이 설탕을 넣었어요「塩を入れるつもりが、砂糖を入れてしまった（間違って）」を比べてみてください——後者には常に、やり損なった・手元が狂ったというニュアンスがあります。文体的には中立で、どんな丁寧さの語尾とも組み合わせられます（後続の節はたいてい -았/었어요 か -아/어 버렸어요 になります）。学習者によくある間違いは、-(으)려고 했는데 を使うべき単なる未実現の計画にこれを使ってしまうこと、そして実際の出来事は過去なのに動詞は現在形の -ㄴ/는다 のままにしなければならないのを忘れることです。話し言葉では 것이 はよく 게 に縮約されます：산다는 게、본다는 게。',
    ),
  '-고서야': L(
      'Expresses that something happens or becomes possible "only after / not until" a necessary precondition is met — and usually with the nuance that it happened belatedly, later than it should have. It attaches directly to a verb stem with no allomorph change, since 고 already begins with a consonant: vowel/ㄹ stem 가다 → 가고서야, 알다 → 알고서야 (no ㄹ drop); consonant stem 먹다 → 먹고서야, 듣다 → 듣고서야. It does not take tense on the 고 clause itself — past/present is carried by the final verb (그가 떠나고서야 진실을 알았다 "only after he left did I learn the truth"). It is essentially the emphatic 고서 + 야 ("only/precisely"), so it spotlights that one action as the indispensable trigger for the next.\n\nCompare 아/어서야, which makes the same "only after" point but builds on the 아/어서 connector (도착해서야 "only after arriving"). The split is in the link between clauses: 고서야 chains two sequential actions ("having done X, only then Y"), while 아/어서야 leans toward cause/means or time-of-arrival. Minimal pair: 약을 먹고서야 나았다 "I got better only after taking the medicine" (took it, then recovered) vs. 병원에 가서야 알았다 "I only found out once I went to the hospital" (going there caused/enabled the discovery). 고서야 is neutral in register and fine in both writing and speech; politeness sits on the final verb (나았어요 / 나았습니다), not on this connector. The most common learner mistake is forcing a future or wished-for result after it — 고서야 reports a real, completed late realization, so 알았다/깨달았다 (past) is natural, not 알 거예요. Also avoid stacking tense on the 고 part (✗먹었고서야); keep it bare 먹고서야.',
      'Expresa que algo sucede o se vuelve posible "solo después / recién cuando" se cumple una condición previa necesaria, y normalmente con el matiz de que pasó tardíamente, más tarde de lo que debería. Se pega directo a la raíz verbal sin cambio de alomorfo, porque 고 ya empieza con consonante: raíz en vocal/ㄹ 가다 → 가고서야, 알다 → 알고서야 (sin caída de ㄹ); raíz en consonante 먹다 → 먹고서야, 듣다 → 듣고서야. No lleva tiempo en la cláusula del 고: el pasado/presente lo carga el verbo final (그가 떠나고서야 진실을 알았다 "recién cuando él se fue supe la verdad"). Es esencialmente el 고서 enfático + 야 ("solo/justamente"), así que pone el foco en esa acción como el disparador imprescindible para la siguiente.\n\nCompará con 아/어서야, que marca el mismo "solo después" pero se construye sobre el conector 아/어서 (도착해서야 "recién al llegar"). La diferencia está en el enlace entre cláusulas: 고서야 encadena dos acciones secuenciales ("habiendo hecho X, recién entonces Y"), mientras que 아/어서야 se inclina hacia causa/medio o momento de llegada. Par mínimo: 약을 먹고서야 나았다 "me curé recién después de tomar el remedio" (lo tomó, después se recuperó) vs. 병원에 가서야 알았다 "recién me enteré cuando fui al hospital" (ir ahí causó/permitió el descubrimiento). 고서야 es neutro de registro y va bien tanto en escritura como en habla; la cortesía la lleva el verbo final (나았어요 / 나았습니다), no este conector. El error más común del que aprende es forzar un resultado futuro o deseado después: 고서야 reporta una toma de conciencia real, completada y tardía, así que lo natural es 알았다/깨달았다 (pasado), no 알 거예요. Tampoco apiles tiempo en la parte del 고 (✗먹었고서야); dejalo pelado, 먹고서야.',
      'Exprime que quelque chose se produit ou devient possible « seulement après / pas avant que » une condition préalable nécessaire soit remplie, et généralement avec la nuance que cela est arrivé tardivement, plus tard que ça n\'aurait dû. Il s\'attache directement au radical verbal sans changement d\'allomorphe, puisque 고 commence déjà par une consonne : radical en voyelle/ㄹ 가다 → 가고서야, 알다 → 알고서야 (pas de chute du ㄹ) ; radical en consonne 먹다 → 먹고서야, 듣다 → 듣고서야. Il ne porte pas le temps sur la proposition en 고 : le passé/présent est porté par le verbe final (그가 떠나고서야 진실을 알았다 « ce n\'est qu\'après son départ que j\'ai appris la vérité »). C\'est essentiellement le 고서 emphatique + 야 (« seulement/précisément »), donc il met en lumière cette action comme le déclencheur indispensable de la suivante.\n\nCompare avec 아/어서야, qui exprime le même « seulement après » mais se construit sur le connecteur 아/어서 (도착해서야 « seulement une fois arrivé »). La différence est dans le lien entre les propositions : 고서야 enchaîne deux actions séquentielles (« ayant fait X, alors seulement Y »), tandis que 아/어서야 penche vers la cause/le moyen ou le moment d\'arrivée. Paire minimale : 약을 먹고서야 나았다 « je n\'ai guéri qu\'après avoir pris le médicament » (il l\'a pris, puis s\'est rétabli) vs 병원에 가서야 알았다 « je ne l\'ai su qu\'une fois allé à l\'hôpital » (le fait d\'y aller a causé/permis la découverte). 고서야 est neutre en registre et convient aussi bien à l\'écrit qu\'à l\'oral ; la politesse repose sur le verbe final (나았어요 / 나았습니다), pas sur ce connecteur. L\'erreur la plus fréquente chez l\'apprenant est de forcer un résultat futur ou souhaité après : 고서야 rapporte une prise de conscience réelle, achevée et tardive, donc 알았다/깨달았다 (passé) est naturel, pas 알 거예요. Évite aussi d\'empiler le temps sur la partie en 고 (✗먹었고서야) ; garde-le nu, 먹고서야.',
      'Expressa que algo acontece ou se torna possível "só depois / não antes de" uma condição prévia necessária ser cumprida, e geralmente com a nuance de que aconteceu tardiamente, mais tarde do que deveria. Liga-se diretamente ao radical do verbo sem mudança de alomorfe, já que 고 já começa com consoante: radical em vogal/ㄹ 가다 → 가고서야, 알다 → 알고서야 (sem queda do ㄹ); radical em consoante 먹다 → 먹고서야, 듣다 → 듣고서야. Não leva tempo na oração com 고: o passado/presente é carregado pelo verbo final (그가 떠나고서야 진실을 알았다 "só depois que ele saiu é que eu soube a verdade"). É essencialmente o 고서 enfático + 야 ("só/justamente"), então destaca aquela ação como o gatilho indispensável para a seguinte.\n\nCompare com 아/어서야, que faz o mesmo ponto de "só depois" mas se constrói sobre o conector 아/어서 (도착해서야 "só depois de chegar"). A diferença está na ligação entre as orações: 고서야 encadeia duas ações sequenciais ("tendo feito X, só então Y"), enquanto 아/어서야 tende para causa/meio ou momento de chegada. Par mínimo: 약을 먹고서야 나았다 "só melhorei depois de tomar o remédio" (tomou, depois se recuperou) vs. 병원에 가서야 알았다 "só descobri quando fui ao hospital" (ir lá causou/possibilitou a descoberta). 고서야 é neutro em registro e funciona bem tanto na escrita quanto na fala; a polidez fica no verbo final (나았어요 / 나았습니다), não neste conector. O erro mais comum de quem aprende é forçar um resultado futuro ou desejado depois dele: 고서야 relata uma constatação real, concluída e tardia, então 알았다/깨달았다 (passado) é natural, não 알 거예요. Evite também empilhar tempo na parte do 고 (✗먹었고서야); mantenha-o cru, 먹고서야.',
      'บ่งบอกว่าบางสิ่งเกิดขึ้นหรือเป็นไปได้ "ก็ต่อเมื่อ / ไม่ก่อนที่" เงื่อนไขที่จำเป็นจะถูกเติมเต็มเท่านั้น และมักมีนัยว่ามันเกิดขึ้นช้าเกินไป ช้ากว่าที่ควรจะเป็น มันเกาะติดกับรากศัพท์ของกริยาโดยตรงโดยไม่มีการเปลี่ยนรูปแปร เพราะ 고 ขึ้นต้นด้วยพยัญชนะอยู่แล้ว: รากที่ลงท้ายด้วยสระ/ㄹ 가다 → 가고서야, 알다 → 알고서야 (ㄹ ไม่หลุด); รากที่ลงท้ายด้วยพยัญชนะ 먹다 → 먹고서야, 듣다 → 듣고서야 มันไม่รับกาลที่อนุประโยค 고 เอง อดีต/ปัจจุบันจะถูกแบกไว้ที่กริยาท้ายประโยค (그가 떠나고서야 진실을 알았다 "ก็ต่อเมื่อเขาจากไปฉันถึงได้รู้ความจริง") โดยพื้นฐานแล้วมันคือ 고서 ที่เน้นย้ำ + 야 ("เพียง/ตรงนั้นพอดี") จึงเป็นการสปอตไลต์การกระทำนั้นในฐานะตัวกระตุ้นที่ขาดไม่ได้สำหรับสิ่งที่ตามมา\n\nเปรียบเทียบกับ 아/어서야 ที่สื่อความหมาย "ก็ต่อเมื่อ" แบบเดียวกัน แต่สร้างขึ้นบนตัวเชื่อม 아/어서 (도착해서야 "ก็ต่อเมื่อมาถึงแล้วเท่านั้น") ความต่างอยู่ที่การเชื่อมระหว่างอนุประโยค: 고서야 ร้อยการกระทำที่เป็นลำดับสองอย่างเข้าด้วยกัน ("เมื่อทำ X แล้วถึงจะ Y") ส่วน 아/어서야 จะเอนไปทางสาเหตุ/วิธีการ หรือช่วงเวลาที่มาถึง คู่ที่ต่างกันเพียงจุดเดียว: 약을 먹고서야 나았다 "ฉันหายดีก็ต่อเมื่อกินยาแล้วเท่านั้น" (กินยา แล้วจึงหาย) เทียบกับ 병원에 가서야 알았다 "ฉันเพิ่งรู้ตอนที่ไปโรงพยาบาลแล้ว" (การไปที่นั่นทำให้/เอื้อให้เกิดการค้นพบ) 고서야 เป็นกลางในด้านระดับภาษาและใช้ได้ดีทั้งในงานเขียนและการพูด ความสุภาพอยู่ที่กริยาท้ายประโยค (나았어요 / 나았습니다) ไม่ใช่ที่ตัวเชื่อมนี้ ข้อผิดพลาดที่พบบ่อยที่สุดของผู้เรียนคือการฝืนใส่ผลลัพธ์ที่เป็นอนาคตหรือที่ปรารถนาตามหลังมัน: 고서야 รายงานการตระหนักรู้ที่เกิดขึ้นจริง เสร็จสิ้นแล้ว และล่าช้า ดังนั้น 알았다/깨달았다 (อดีต) จึงเป็นธรรมชาติ ไม่ใช่ 알 거예요 และอย่าซ้อนกาลลงในส่วนของ 고 (✗먹었고서야) ให้คงรูปเปล่าไว้ 먹고서야',
      'Menyatakan bahwa sesuatu terjadi atau menjadi mungkin "hanya setelah / baru ketika" sebuah prasyarat yang diperlukan terpenuhi, dan biasanya dengan nuansa bahwa itu terjadi terlambat, lebih lambat daripada seharusnya. Ia menempel langsung pada akar kata kerja tanpa perubahan alomorf, karena 고 sudah diawali konsonan: akar berakhiran vokal/ㄹ 가다 → 가고서야, 알다 → 알고서야 (tanpa pelesapan ㄹ); akar berakhiran konsonan 먹다 → 먹고서야, 듣다 → 듣고서야. Ia tidak membawa kala pada klausa 고 itu sendiri: lampau/kini dibawa oleh kata kerja akhir (그가 떠나고서야 진실을 알았다 "baru setelah dia pergi aku mengetahui kebenarannya"). Pada dasarnya ini adalah 고서 yang ditegaskan + 야 ("hanya/tepatnya"), jadi ia menyorot satu tindakan itu sebagai pemicu yang tak terhindarkan bagi tindakan berikutnya.\n\nBandingkan dengan 아/어서야, yang menyampaikan poin "hanya setelah" yang sama tetapi dibangun di atas penghubung 아/어서 (도착해서야 "baru setelah tiba"). Perbedaannya ada pada penghubung antarklausa: 고서야 merangkai dua tindakan berurutan ("setelah melakukan X, barulah Y"), sedangkan 아/어서야 condong ke sebab/cara atau saat tiba. Pasangan minimal: 약을 먹고서야 나았다 "aku sembuh baru setelah minum obat" (minum dulu, lalu pulih) vs. 병원에 가서야 알았다 "aku baru tahu ketika pergi ke rumah sakit" (pergi ke sana menyebabkan/memungkinkan penemuan itu). 고서야 netral dalam ragam bahasa dan cocok baik untuk tulisan maupun ucapan; kesopanan terletak pada kata kerja akhir (나았어요 / 나았습니다), bukan pada penghubung ini. Kesalahan pembelajar yang paling umum adalah memaksakan hasil masa depan atau yang diharapkan setelahnya: 고서야 melaporkan kesadaran nyata yang sudah tuntas dan terlambat, jadi 알았다/깨달았다 (lampau) terdengar wajar, bukan 알 거예요. Hindari juga menumpuk kala pada bagian 고 (✗먹었고서야); biarkan polos, 먹고서야.',
      'Diễn đạt rằng điều gì đó xảy ra hoặc trở nên khả thi "chỉ sau khi / mãi đến khi" một điều kiện tiên quyết cần thiết được đáp ứng, và thường mang sắc thái rằng việc đó xảy ra muộn màng, trễ hơn lẽ ra phải có. Nó gắn trực tiếp vào gốc động từ mà không đổi biến thể, vì 고 vốn đã bắt đầu bằng phụ âm: gốc kết thúc bằng nguyên âm/ㄹ 가다 → 가고서야, 알다 → 알고서야 (không rụng ㄹ); gốc kết thúc bằng phụ âm 먹다 → 먹고서야, 듣다 → 듣고서야. Nó không mang thì ở mệnh đề 고: quá khứ/hiện tại do động từ cuối câu gánh (그가 떠나고서야 진실을 알았다 "mãi đến khi anh ấy rời đi tôi mới biết sự thật"). Về cơ bản nó là 고서 được nhấn mạnh + 야 ("chỉ/đúng là"), nên nó làm nổi bật hành động đó như tác nhân kích hoạt không thể thiếu cho hành động kế tiếp.\n\nSo sánh với 아/어서야, vốn cũng nêu cùng ý "chỉ sau khi" nhưng được dựng trên liên kết 아/어서 (도착해서야 "chỉ sau khi đến"). Khác biệt nằm ở mối nối giữa các mệnh đề: 고서야 nối hai hành động tuần tự ("đã làm X xong, lúc đó mới Y"), trong khi 아/어서야 nghiêng về nguyên nhân/phương tiện hoặc thời điểm đến. Cặp tối thiểu: 약을 먹고서야 나았다 "tôi khỏi bệnh chỉ sau khi uống thuốc" (uống thuốc, rồi mới hồi phục) so với 병원에 가서야 알았다 "tôi chỉ biết được khi đã đến bệnh viện" (việc đến đó gây ra/cho phép sự phát hiện). 고서야 trung tính về ngữ vực và dùng tốt cả trong văn viết lẫn lời nói; sự lịch sự nằm ở động từ cuối câu (나았어요 / 나았습니다), không phải ở liên kết này. Lỗi phổ biến nhất của người học là cố ép một kết quả tương lai hay mong muốn theo sau nó: 고서야 thuật lại một sự nhận ra có thật, đã hoàn tất và muộn màng, nên 알았다/깨달았다 (quá khứ) là tự nhiên, chứ không phải 알 거예요. Cũng tránh chồng thì vào phần 고 (✗먹었고서야); hãy giữ nó trơn, 먹고서야.',
      '必要な前提条件が満たされて「初めて／〜してようやく」何かが起こる、または可能になることを表します。たいていは、本来よりも遅れて、遅まきながら起きたというニュアンスを伴います。고 はすでに子音で始まるため異形態の変化はなく、動詞語幹に直接付きます。母音/ㄹ語幹 가다 → 가고서야、알다 → 알고서야（ㄹ脱落なし）、子音語幹 먹다 → 먹고서야、듣다 → 듣고서야。고 の節そのものには時制を付けず、過去/現在は文末の動詞が担います（그가 떠나고서야 진실을 알았다「彼が去って初めて真実を知った」）。本質的には強調の 고서 + 야（「〜こそ／まさに」）であり、その一つの動作を次の動作に不可欠な引き金として際立たせます。\n\n아/어서야 と比べてみましょう。これも同じ「〜して初めて」を表しますが、接続語 아/어서 の上に成り立ちます（도착해서야「到着して初めて」）。違いは節と節のつなぎ方にあります。고서야 は二つの連続する動作をつなぎます（「Xをして、そこでようやくY」）。一方、아/어서야 は原因・手段や到達の時点に傾きます。ミニマルペア：약을 먹고서야 나았다「薬を飲んで初めて治った」（飲んでから回復した）に対し、병원에 가서야 알았다「病院に行って初めて分かった」（行ったことが発見を引き起こした／可能にした）。고서야 は語調的に中立で、書き言葉でも話し言葉でも問題なく使えます。丁寧さはこの接続語ではなく文末の動詞（나았어요 / 나았습니다）に乗ります。学習者の最も多い間違いは、その後に未来や願望の結果を無理に置くことです。고서야 は実際に完了した遅い気づきを述べるので、自然なのは 알았다/깨달았다（過去）であって、알 거예요 ではありません。また、고 の部分に時制を重ねないこと（✗먹었고서야）。素のまま 먹고서야 にしてください。',
    ),
  '-아/어 빠지다': L(
      'Adds the meaning "utterly / completely / hopelessly" to a small set of negative descriptive adjectives, turning, say, 게으르다 ("lazy") into 게을러 빠지다 ("utterly, disgustingly lazy"). It attaches the connective -아/어 to the adjective stem and adds 빠지다, following the same vowel-harmony rule as -아/어요: a bright stem (ㅏ/ㅗ) takes -아 (낡다 → 낡아 빠지다 "all worn out, decrepit"; 약다 → 약아 빠지다 "cunning to the bone"), and other stems take -어 (게으르다 → 게을러 빠지다, with 게으르- following the 르 pattern → 게을러). It only works with negative-quality adjectives — you would never say *좋아 빠지다 — and once formed it conjugates as a regular 지다 verb: 게을러 빠졌어요, 낡아 빠진 신발 ("worn-out shoes"). It is heavily evaluative and almost always pejorative.\n\nCompare it with the intensifier 너무, which simply scales degree: 너무 게을러요 just means "(s)he is too/very lazy," a neutral observation, whereas 게을러 빠졌어요 drips with disgust and contempt — "(s)he\'s rotten-to-the-core lazy." So 이 옷은 너무 낡았어요 ("these clothes are very old") versus 이 옷은 낡아 빠졌어요 ("these clothes are utterly threadbare/junk"). Register: this is colloquial and harsh, fine in casual speech (반말/해요체) but too blunt for polite or formal writing. The most common learner mistake is overgeneralizing it to positive or action words (the *좋아 빠지다 / *먹어 빠지다 error) — keep it to negative adjectives only. Note 빠지다 here is a bound auxiliary, unrelated to the main verb 빠지다 "to fall into / be missing."',
      'Le agrega el matiz de "totalmente / completamente / sin remedio" a un grupo reducido de adjetivos descriptivos negativos, convirtiendo, por ejemplo, 게으르다 ("perezoso") en 게을러 빠지다 ("perezoso hasta decir basta, asquerosamente perezoso"). Se une el conector -아/어 a la raíz del adjetivo y se le suma 빠지다, siguiendo la misma regla de armonía vocálica que -아/어요: una raíz "clara" (ㅏ/ㅗ) toma -아 (낡다 → 낡아 빠지다 "todo gastado, decrépito"; 약다 → 약아 빠지다 "astuto hasta la médula"), y las demás raíces toman -어 (게으르다 → 게을러 빠지다, donde 게으르- sigue el patrón 르 → 게을러). Solo funciona con adjetivos de cualidad negativa —nunca dirías *좋아 빠지다— y una vez formado se conjuga como un verbo 지다 normal: 게을러 빠졌어요, 낡아 빠진 신발 ("zapatos gastadísimos"). Es fuertemente valorativo y casi siempre peyorativo.\n\nComparalo con el intensificador 너무, que simplemente gradúa el grado: 너무 게을러요 solo significa "es demasiado/muy perezoso/a", una observación neutra, mientras que 게을러 빠졌어요 chorrea asco y desprecio: "es perezoso/a hasta la médula". Así, 이 옷은 너무 낡았어요 ("esta ropa está muy vieja") frente a 이 옷은 낡아 빠졌어요 ("esta ropa está totalmente raída/hecha un trapo"). Registro: es coloquial y duro, está bien en el habla casual (반말/해요체) pero resulta demasiado brusco para la escritura cortés o formal. El error más común del estudiante es sobregeneralizarlo a palabras positivas o de acción (el error *좋아 빠지다 / *먹어 빠지다); usalo solo con adjetivos negativos. Ojo: acá 빠지다 es un auxiliar ligado, sin relación con el verbo principal 빠지다 "caer en / faltar".',
      'Cela ajoute le sens « totalement / complètement / désespérément » à un petit ensemble d\'adjectifs descriptifs négatifs, transformant par exemple 게으르다 (« paresseux ») en 게을러 빠지다 (« paresseux à un point écœurant »). On rattache le connecteur -아/어 au radical de l\'adjectif puis on ajoute 빠지다, en suivant la même règle d\'harmonie vocalique que -아/어요 : un radical clair (ㅏ/ㅗ) prend -아 (낡다 → 낡아 빠지다 « complètement usé, décrépit » ; 약다 → 약아 빠지다 « rusé jusqu\'à l\'os »), et les autres radicaux prennent -어 (게으르다 → 게을러 빠지다, où 게으르- suit le schéma 르 → 게을러). Cela ne marche qu\'avec des adjectifs de qualité négative — tu ne dirais jamais *좋아 빠지다 — et une fois formé, l\'ensemble se conjugue comme un verbe 지다 ordinaire : 게을러 빠졌어요, 낡아 빠진 신발 (« des chaussures complètement usées »). C\'est fortement évaluatif et presque toujours péjoratif.\n\nCompare-le avec l\'intensificateur 너무, qui ne fait que graduer le degré : 너무 게을러요 signifie simplement « il/elle est trop/très paresseux(se) », une observation neutre, alors que 게을러 빠졌어요 dégouline de dégoût et de mépris — « il/elle est paresseux(se) jusqu\'à la moelle ». Ainsi 이 옷은 너무 낡았어요 (« ces vêtements sont très vieux ») contre 이 옷은 낡아 빠졌어요 (« ces vêtements sont complètement râpés/bons à jeter »). Registre : c\'est familier et dur, acceptable à l\'oral décontracté (반말/해요체) mais trop brutal pour l\'écrit poli ou formel. L\'erreur la plus courante chez les apprenants est de le surgénéraliser à des mots positifs ou d\'action (l\'erreur *좋아 빠지다 / *먹어 빠지다) — réserve-le aux seuls adjectifs négatifs. À noter : 빠지다 est ici un auxiliaire lié, sans rapport avec le verbe principal 빠지다 « tomber dans / manquer ».',
      'Acrescenta o sentido de "totalmente / completamente / sem remédio" a um pequeno conjunto de adjetivos descritivos negativos, transformando, por exemplo, 게으르다 ("preguiçoso") em 게을러 빠지다 ("preguiçoso de doer, repugnantemente preguiçoso"). Liga-se o conector -아/어 à raiz do adjetivo e acrescenta-se 빠지다, seguindo a mesma regra de harmonia vocálica de -아/어요: uma raiz clara (ㅏ/ㅗ) leva -아 (낡다 → 낡아 빠지다 "todo gasto, decadente"; 약다 → 약아 빠지다 "astuto até a medula"), e as demais raízes levam -어 (게으르다 → 게을러 빠지다, em que 게으르- segue o padrão 르 → 게을러). Só funciona com adjetivos de qualidade negativa — você nunca diria *좋아 빠지다 — e, uma vez formado, conjuga-se como um verbo 지다 normal: 게을러 빠졌어요, 낡아 빠진 신발 ("sapatos surrados"). É fortemente avaliativo e quase sempre pejorativo.\n\nCompare com o intensificador 너무, que apenas gradua a intensidade: 너무 게을러요 significa só "ele(a) é preguiçoso(a) demais/muito", uma observação neutra, ao passo que 게을러 빠졌어요 escorre nojo e desprezo — "ele(a) é podre de preguiçoso(a)". Assim, 이 옷은 너무 낡았어요 ("esta roupa está muito velha") versus 이 옷은 낡아 빠졌어요 ("esta roupa está completamente puída/é um trapo"). Registro: é coloquial e ríspido, tudo bem na fala casual (반말/해요체), mas brusco demais para a escrita polida ou formal. O erro mais comum dos estudantes é generalizá-lo demais para palavras positivas ou de ação (o erro *좋아 빠지다 / *먹어 빠지다) — use apenas com adjetivos negativos. Note que 빠지다 aqui é um auxiliar preso, sem relação com o verbo principal 빠지다 "cair em / estar faltando".',
      'เพิ่มความหมาย "อย่างถึงที่สุด / อย่างสิ้นเชิง / อย่างหมดทาง" ให้กับคำคุณศัพท์เชิงพรรณนาในแง่ลบจำนวนไม่มากนัก เช่น เปลี่ยน 게으르다 ("ขี้เกียจ") ให้กลายเป็น 게을러 빠지다 ("ขี้เกียจสุด ๆ ขี้เกียจจนน่ารังเกียจ") โดยเติมตัวเชื่อม -아/어 เข้ากับรากคำคุณศัพท์แล้วต่อด้วย 빠지다 ตามกฎความกลมกลืนของสระแบบเดียวกับ -아/어요: รากเสียงสว่าง (ㅏ/ㅗ) ใช้ -아 (낡다 → 낡아 빠지다 "เก่าโทรมไปหมด ทรุดโทรม"; 약다 → 약아 빠지다 "เจ้าเล่ห์เข้ากระดูกดำ") ส่วนรากอื่น ๆ ใช้ -어 (게으르다 → 게을러 빠지다 โดย 게으르- เป็นไปตามรูป 르 → 게을러) ใช้ได้เฉพาะกับคำคุณศัพท์ที่มีคุณสมบัติในแง่ลบเท่านั้น — คุณจะไม่มีวันพูดว่า *좋아 빠지다 — และเมื่อสร้างรูปแล้วก็ผันเหมือนคำกริยา 지다 ทั่วไป: 게을러 빠졌어요, 낡아 빠진 신발 ("รองเท้าที่เก่าจนเปื่อย") เป็นคำที่ประเมินค่าอย่างหนักและเกือบทุกครั้งมีความหมายในเชิงดูถูก\n\nลองเทียบกับคำขยายความเข้ม 너무 ซึ่งเพียงแค่บอกระดับมากน้อย: 너무 게을러요 หมายความแค่ว่า "เขาขี้เกียจเกินไป/มาก" เป็นการสังเกตอย่างเป็นกลาง ในขณะที่ 게을러 빠졌어요 เต็มไปด้วยความรังเกียจและดูแคลน — "เขาขี้เกียจเน่าเข้ากระดูก" ดังนั้น 이 옷은 너무 낡았어요 ("เสื้อผ้าชุดนี้เก่ามาก") เทียบกับ 이 옷은 낡아 빠졌어요 ("เสื้อผ้าชุดนี้เก่าจนขาดรุ่งริ่ง/เป็นเศษผ้า") ระดับภาษา: เป็นภาษาพูดและรุนแรง ใช้ได้ในบทสนทนาแบบไม่เป็นทางการ (반말/해요체) แต่ห้วนเกินไปสำหรับการเขียนแบบสุภาพหรือทางการ ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือนำไปใช้กว้างเกินไปกับคำเชิงบวกหรือคำกริยาแสดงการกระทำ (ความผิดพลาดแบบ *좋아 빠지다 / *먹어 빠지다) — ให้ใช้กับคำคุณศัพท์เชิงลบเท่านั้น โปรดสังเกตว่า 빠지다 ในที่นี้เป็นคำช่วยที่ผูกติดกับรูป ไม่เกี่ยวข้องกับคำกริยาหลัก 빠지다 ที่แปลว่า "ตกลงไปใน / ขาดหายไป"',
      'Menambahkan makna "benar-benar / sepenuhnya / parah tak tertolong" pada sekelompok kecil kata sifat deskriptif bermakna negatif, misalnya mengubah 게으르다 ("malas") menjadi 게을러 빠지다 ("malas luar biasa, malas sampai menjijikkan"). Konektor -아/어 dilekatkan pada akar kata sifat lalu ditambah 빠지다, mengikuti aturan harmoni vokal yang sama seperti -아/어요: akar terang (ㅏ/ㅗ) memakai -아 (낡다 → 낡아 빠지다 "usang sekali, lapuk"; 약다 → 약아 빠지다 "licik sampai ke tulang"), dan akar lainnya memakai -어 (게으르다 → 게을러 빠지다, dengan 게으르- mengikuti pola 르 → 게을러). Bentuk ini hanya berlaku untuk kata sifat berkualitas negatif — kamu tidak akan pernah mengatakan *좋아 빠지다 — dan setelah terbentuk, ia dikonjugasikan seperti verba 지다 biasa: 게을러 빠졌어요, 낡아 빠진 신발 ("sepatu yang usang"). Bentuk ini sangat menilai dan hampir selalu bernada merendahkan.\n\nBandingkan dengan penguat 너무, yang sekadar menunjukkan derajat: 너무 게을러요 hanya berarti "dia terlalu/sangat malas", sebuah pengamatan netral, sedangkan 게을러 빠졌어요 meneteskan rasa jijik dan hina — "dia malas sampai ke sumsumnya". Jadi 이 옷은 너무 낡았어요 ("baju ini sangat tua") berbeda dengan 이 옷은 낡아 빠졌어요 ("baju ini sudah lusuh banget/jadi rongsokan"). Ragam: bahasa ini kasual dan kasar, cocok dalam percakapan santai (반말/해요체) tetapi terlalu blak-blakan untuk tulisan sopan atau formal. Kesalahan paling umum di kalangan pemelajar adalah menggeneralisasikannya ke kata positif atau kata kerja aksi (kesalahan *좋아 빠지다 / *먹어 빠지다) — gunakan hanya untuk kata sifat negatif. Perhatikan bahwa 빠지다 di sini adalah verba bantu terikat, tidak berkaitan dengan verba utama 빠지다 "jatuh ke dalam / tidak ada".',
      'Thêm nghĩa "hết sức / hoàn toàn / vô phương cứu chữa" vào một nhóm nhỏ các tính từ miêu tả mang nghĩa tiêu cực, chẳng hạn biến 게으르다 ("lười") thành 게을러 빠지다 ("lười hết chỗ nói, lười đến phát ghê"). Ta gắn liên kết -아/어 vào thân tính từ rồi thêm 빠지다, theo đúng quy tắc hòa hợp nguyên âm như -아/어요: thân sáng (ㅏ/ㅗ) lấy -아 (낡다 → 낡아 빠지다 "cũ mòn, tồi tàn"; 약다 → 약아 빠지다 "ranh ma đến tận xương tủy"), còn các thân khác lấy -어 (게으르다 → 게을러 빠지다, trong đó 게으르- theo mẫu 르 → 게을러). Nó chỉ dùng được với tính từ chỉ phẩm chất tiêu cực — bạn sẽ không bao giờ nói *좋아 빠지다 — và một khi đã tạo thành thì chia như một động từ 지다 bình thường: 게을러 빠졌어요, 낡아 빠진 신발 ("đôi giày cũ mòn"). Đây là cách nói mang tính đánh giá mạnh và gần như luôn miệt thị.\n\nHãy so sánh nó với từ tăng cường 너무, vốn chỉ đơn thuần đo mức độ: 너무 게을러요 chỉ có nghĩa "anh/cô ấy quá/rất lười", một nhận xét trung tính, trong khi 게을러 빠졌어요 nhỏ giọt sự ghê tởm và khinh miệt — "anh/cô ấy lười đến thối ruột". Vậy nên 이 옷은 너무 낡았어요 ("bộ quần áo này rất cũ") đối lập với 이 옷은 낡아 빠졌어요 ("bộ quần áo này sờn rách hoàn toàn / chỉ là đồ vứt đi"). Ngữ vực: cách nói này thông tục và gay gắt, ổn trong lời nói thân mật (반말/해요체) nhưng quá thẳng thừng đối với văn viết lịch sự hay trang trọng. Lỗi phổ biến nhất của người học là khái quát hóa nó sang từ tích cực hoặc từ chỉ hành động (lỗi *좋아 빠지다 / *먹어 빠지다) — chỉ dùng cho tính từ tiêu cực thôi. Lưu ý 빠지다 ở đây là một trợ động từ phụ thuộc, không liên quan đến động từ chính 빠지다 "rơi vào / bị thiếu".',
      'ごく一部の否定的な性質を表す形容詞に「とことん／すっかり／救いようがないほど」という意味を加え、たとえば 게으르다（「怠けている」）を 게을러 빠지다（「とことん怠けている、嫌になるほど怠惰だ」）に変えます。形容詞の語幹に接続形 -아/어 を付け、そこに 빠지다 を加えますが、-아/어요 と同じ母音調和の規則に従います。明るい語幹（ㅏ/ㅗ）には -아 が付き（낡다 → 낡아 빠지다「すっかり古びてぼろぼろだ」、약다 → 약아 빠지다「骨の髄まで抜け目ない」）、それ以外の語幹には -어 が付きます（게으르다 → 게을러 빠지다。ここで 게으르- は 르 不規則に従い → 게을러 となる）。これは否定的な性質の形容詞にしか使えず、*좋아 빠지다 とは決して言いません。いったん形ができれば、ふつうの 지다 動詞として活用します：게을러 빠졌어요、낡아 빠진 신발（「履き古した靴」）。きわめて評価的で、ほぼ常に軽蔑的なニュアンスを帯びます。\n\n強調語の 너무 と比べてみましょう。너무 は単に程度を測るだけで、너무 게을러요 は「彼／彼女はとても／怠けすぎだ」という中立的な観察にすぎません。一方 게을러 빠졌어요 は嫌悪と侮蔑がにじみ出ていて、「根っから怠け腐っている」という感じです。だから 이 옷은 너무 낡았어요（「この服はとても古い」）に対して、이 옷은 낡아 빠졌어요（「この服はすっかりすり切れていてぼろくずだ」）となります。語調について：これは口語的できつい表現で、くだけた話し言葉（반말/해요체）では問題ありませんが、丁寧・改まった文章には率直すぎます。学習者に最も多い間違いは、肯定的な語や動作を表す語に過度に一般化してしまうこと（*좋아 빠지다 / *먹어 빠지다 という誤り）で、否定的な形容詞だけに使ってください。なお、ここでの 빠지다 は拘束的な補助用言であり、「落ちる／抜け落ちる」という意味の本動詞 빠지다 とは無関係です。',
    ),
  '-아/어 치우다': L(
      '-아/어 치우다 attaches to a verb stem and means to finish something off briskly and decisively, often a chore or unpleasant task you want out of the way — "get it over with / dispatch it quickly." It follows the regular 아/어 vowel-harmony rule: a stem whose last vowel is ㅏ/ㅗ takes -아 치우다 (닦다 → 닦아 치우다 "scrub it all off and be done," 막다 → 막아 치우다), and any other stem takes -어 치우다 (먹다 → 먹어 치우다 "polish it off," 읽다 → 읽어 치우다 "knock the reading out"; 끝내다 → 끝내어 치우다, contracted to 끝내 치우다). 하다 verbs become 해 치우다 (숙제를 해 치우다 "bang out the homework"). It conjugates on 치우다 itself, so tense and politeness ride on the auxiliary: 다 먹어 치웠어요 "I scarfed it all down," 일을 해 치울게요 "I\'ll just knock the work out."\n\nThe close neighbour to watch is -아/어 버리다, which also marks completion but colours it with regret, relief, or finality rather than brisk efficiency. Compare 케이크를 다 먹어 치웠다 ("I polished off the whole cake — got it dealt with") versus 케이크를 다 먹어 버렸다 ("I went and ate the whole cake," tinged with oops/regret): 치우다 stresses clearing a task away, 버리다 stresses the irreversible aftermath. Register is casual-to-neutral and very common in speech, so it pairs naturally with 해요/했어요 endings but feels too colloquial for formal writing. Note on spelling: because 치우다 here is a 보조 용언 (auxiliary verb), 한글 맞춤법 permits BOTH the spaced form 먹어 치우다 (the standard/principle) and the joined form 먹어치우다 — so writing it solid is allowed, not an error. The real learner trap is confusing this auxiliary 치우다 with the literal main verb 치우다 ("to tidy up, clear away"): as an auxiliary it must follow a preceding -아/어 verb, not take a noun object directly.',
      '-아/어 치우다 se adjunta a la raíz de un verbo y significa terminar algo de golpe y con decisión, muchas veces una tarea o un pendiente molesto que querés sacarte de encima: "despachalo / terminá con eso rápido". Sigue la regla normal de armonía vocálica 아/어: una raíz cuya última vocal es ㅏ/ㅗ toma -아 치우다 (닦다 → 닦아 치우다 "fregalo todo y listo", 막다 → 막아 치우다), y cualquier otra raíz toma -어 치우다 (먹다 → 먹어 치우다 "engullilo de una", 읽다 → 읽어 치우다 "sacate de encima la lectura"; 끝내다 → 끝내어 치우다, contraído a 끝내 치우다). Los verbos con 하다 se vuelven 해 치우다 (숙제를 해 치우다 "despachá la tarea de un saque"). Se conjuga sobre el propio 치우다, así que el tiempo y la cortesía van en el auxiliar: 다 먹어 치웠어요 "me lo zampé todo", 일을 해 치울게요 "voy a despachar el laburo y listo".\n\nEl vecino cercano que tenés que vigilar es -아/어 버리다, que también marca finalización pero la tiñe de arrepentimiento, alivio o carácter definitivo, en vez de eficiencia rápida. Compará 케이크를 다 먹어 치웠다 ("me liquidé todo el pastel, lo dejé resuelto") con 케이크를 다 먹어 버렸다 ("me fui y me comí todo el pastel", con un dejo de uy/arrepentimiento): 치우다 enfatiza sacar de en medio una tarea, 버리다 enfatiza la consecuencia irreversible. El registro es de casual a neutro y muy común al hablar, así que combina natural con terminaciones 해요/했어요, pero resulta demasiado coloquial para la escritura formal. Nota de ortografía: como 치우다 acá es un 보조 용언 (verbo auxiliar), la 한글 맞춤법 permite TANTO la forma separada 먹어 치우다 (lo estándar/el principio) COMO la forma unida 먹어치우다, así que escribirlo pegado está permitido, no es un error. La verdadera trampa para quien aprende es confundir este 치우다 auxiliar con el verbo principal literal 치우다 ("ordenar, despejar"): como auxiliar tiene que ir después de un verbo en -아/어, no llevar directamente un objeto sustantivo.',
      '-아/어 치우다 s\'attache au radical d\'un verbe et signifie achever quelque chose vivement et de façon décisive, souvent une corvée ou une tâche pénible dont tu veux te débarrasser : « en finir avec / l\'expédier vite fait ». Il suit la règle normale d\'harmonie vocalique 아/어 : un radical dont la dernière voyelle est ㅏ/ㅗ prend -아 치우다 (닦다 → 닦아 치우다 « tout récurer et en finir », 막다 → 막아 치우다), et tout autre radical prend -어 치우다 (먹다 → 먹어 치우다 « tout engloutir », 읽다 → 읽어 치우다 « expédier la lecture » ; 끝내다 → 끝내어 치우다, contracté en 끝내 치우다). Les verbes en 하다 deviennent 해 치우다 (숙제를 해 치우다 « torcher les devoirs »). Il se conjugue sur 치우다 lui-même, donc le temps et la politesse reposent sur l\'auxiliaire : 다 먹어 치웠어요 « j\'ai tout englouti », 일을 해 치울게요 « je vais expédier le boulot ».\n\nLe voisin proche à surveiller est -아/어 버리다, qui marque aussi l\'achèvement mais le teinte de regret, de soulagement ou de finalité plutôt que d\'efficacité expéditive. Compare 케이크를 다 먹어 치웠다 (« j\'ai liquidé tout le gâteau, c\'est réglé ») et 케이크를 다 먹어 버렸다 (« je suis allé manger tout le gâteau », avec une nuance de oups/regret) : 치우다 insiste sur le fait d\'évacuer une tâche, 버리다 insiste sur la conséquence irréversible. Le registre va de familier à neutre et est très courant à l\'oral, donc il s\'accorde naturellement avec les terminaisons 해요/했어요, mais paraît trop familier pour l\'écrit formel. Note d\'orthographe : comme 치우다 est ici un 보조 용언 (verbe auxiliaire), la 한글 맞춤법 autorise À LA FOIS la forme séparée 먹어 치우다 (la norme/le principe) ET la forme soudée 먹어치우다, donc l\'écrire collé est permis, ce n\'est pas une faute. Le vrai piège pour l\'apprenant est de confondre ce 치우다 auxiliaire avec le verbe principal littéral 치우다 (« ranger, débarrasser ») : en tant qu\'auxiliaire, il doit suivre un verbe en -아/어 et non prendre directement un complément d\'objet nominal.',
      '-아/어 치우다 se liga ao radical de um verbo e significa concluir algo de forma rápida e decidida, muitas vezes uma tarefa chata ou um afazer do qual você quer se livrar: "dar conta de uma vez / despachar logo". Segue a regra normal de harmonia vocálica 아/어: um radical cuja última vogal é ㅏ/ㅗ recebe -아 치우다 (닦다 → 닦아 치우다 "esfregar tudo e pronto", 막다 → 막아 치우다), e qualquer outro radical recebe -어 치우다 (먹다 → 먹어 치우다 "devorar tudo", 읽다 → 읽어 치우다 "dar conta da leitura"; 끝내다 → 끝내어 치우다, contraído para 끝내 치우다). Verbos com 하다 viram 해 치우다 (숙제를 해 치우다 "despachar a lição de uma vez"). Conjuga-se no próprio 치우다, então tempo e cortesia ficam no auxiliar: 다 먹어 치웠어요 "comi tudo num instante", 일을 해 치울게요 "vou despachar o trabalho logo".\n\nO vizinho próximo a observar é -아/어 버리다, que também marca conclusão, mas a tinge de arrependimento, alívio ou caráter definitivo, em vez de eficiência rápida. Compare 케이크를 다 먹어 치웠다 ("liquidei o bolo inteiro, resolvi isso") com 케이크를 다 먹어 버렸다 ("acabei comendo o bolo inteiro", com um quê de ops/arrependimento): 치우다 enfatiza tirar uma tarefa do caminho, 버리다 enfatiza a consequência irreversível. O registro vai de casual a neutro e é muito comum na fala, então combina naturalmente com terminações 해요/했어요, mas soa coloquial demais para a escrita formal. Nota sobre a grafia: como 치우다 aqui é um 보조 용언 (verbo auxiliar), a 한글 맞춤법 permite TANTO a forma separada 먹어 치우다 (o padrão/o princípio) QUANTO a forma unida 먹어치우다, então escrevê-lo junto é permitido, não é erro. A verdadeira armadilha para quem aprende é confundir esse 치우다 auxiliar com o verbo principal literal 치우다 ("arrumar, dar uma limpada"): como auxiliar, ele precisa vir depois de um verbo em -아/어, e não receber diretamente um objeto substantivo.',
      '-아/어 치우다 เติมท้ายรากศัพท์ของกริยา และหมายถึงการทำอะไรบางอย่างให้เสร็จไปอย่างฉับไวและเด็ดขาด มักเป็นงานบ้านหรืองานน่าเบื่อที่อยากสะสางให้พ้นๆ ไป — "จัดการให้จบ / ทำให้เสร็จไปเร็วๆ" มันตามกฎความกลมกลืนของสระ 아/어 ตามปกติ: รากศัพท์ที่สระตัวสุดท้ายเป็น ㅏ/ㅗ จะใช้ -아 치우다 (닦다 → 닦아 치우다 "ขัดให้สะอาดหมดแล้วจบ", 막다 → 막아 치우다) ส่วนรากศัพท์อื่นๆ จะใช้ -어 치우다 (먹다 → 먹어 치우다 "เขมือบให้หมด", 읽다 → 읽어 치우다 "อ่านให้จบไปซะ"; 끝내다 → 끝내어 치우다 ย่อเป็น 끝내 치우다) กริยา 하다 จะกลายเป็น 해 치우다 (숙제를 해 치우다 "จัดการการบ้านให้เสร็จรวดเดียว") มันผันที่ตัว 치우다 เอง ดังนั้นกาลและความสุภาพจึงอยู่ที่กริยาช่วย: 다 먹어 치웠어요 "กินหมดเกลี้ยงเลย", 일을 해 치울게요 "จะจัดการงานให้เสร็จไปเลยนะ"\n\nตัวที่ใกล้เคียงและต้องระวังคือ -아/어 버리다 ซึ่งก็บอกความเสร็จสิ้นเหมือนกัน แต่ให้สีของความเสียดาย โล่งอก หรือความถาวร มากกว่าความฉับไวมีประสิทธิภาพ ลองเทียบ 케이크를 다 먹어 치웠다 ("กินเค้กหมดทั้งก้อน — จัดการมันเรียบร้อย") กับ 케이크를 다 먹어 버렸다 ("เผลอกินเค้กหมดทั้งก้อนเลย" มีกลิ่นอายของอุ๊ย/เสียดาย): 치우다 เน้นการสะสางงานให้พ้นไป ส่วน 버리다 เน้นผลที่ตามมาซึ่งย้อนคืนไม่ได้ ระดับภาษาอยู่ในช่วงไม่เป็นทางการถึงกลางๆ และพบบ่อยมากในการพูด จึงเข้ากันได้ดีกับลงท้าย 해요/했어요 แต่จะดูเป็นภาษาพูดเกินไปสำหรับงานเขียนที่เป็นทางการ หมายเหตุเรื่องการสะกด: เพราะ 치우다 ในที่นี้เป็น 보조 용언 (กริยาช่วย) 한글 맞춤법 จึงอนุญาตทั้งรูปแยก 먹어 치우다 (รูปมาตรฐาน/หลักการ) และรูปติดกัน 먹어치우다 — ดังนั้นการเขียนติดกันก็อนุญาต ไม่ใช่ความผิด กับดักที่แท้จริงของผู้เรียนคือการสับสนระหว่าง 치우다 ที่เป็นกริยาช่วยนี้ กับกริยาหลักตามตัวอักษร 치우다 ("เก็บกวาด, จัดให้เป็นระเบียบ"): ในฐานะกริยาช่วยมันต้องตามหลังกริยารูป -아/어 ไม่ใช่รับกรรมที่เป็นคำนามโดยตรง',
      '-아/어 치우다 melekat pada akar kata kerja dan berarti menyelesaikan sesuatu dengan cepat dan tegas, sering kali pekerjaan rumah atau tugas menyebalkan yang ingin kamu beresi: "selesaikan sekalian / kelarkan cepat-cepat". Bentuk ini mengikuti aturan harmoni vokal 아/어 yang biasa: akar yang vokal terakhirnya ㅏ/ㅗ memakai -아 치우다 (닦다 → 닦아 치우다 "gosok bersih semua dan beres", 막다 → 막아 치우다), dan akar lainnya memakai -어 치우다 (먹다 → 먹어 치우다 "lahap habis", 읽다 → 읽어 치우다 "selesaikan bacaannya"; 끝내다 → 끝내어 치우다, disingkat menjadi 끝내 치우다). Kata kerja 하다 menjadi 해 치우다 (숙제를 해 치우다 "kebut tugasnya sampai selesai"). Konjugasinya jatuh pada 치우다 itu sendiri, jadi kala dan kesopanan menumpang pada verba bantu: 다 먹어 치웠어요 "kulahap habis semuanya", 일을 해 치울게요 "kukelarkan saja pekerjaannya".\n\nTetangga dekat yang perlu diwaspadai adalah -아/어 버리다, yang juga menandai penyelesaian tetapi memberinya nuansa penyesalan, kelegaan, atau finalitas, bukan efisiensi yang sat-set. Bandingkan 케이크를 다 먹어 치웠다 ("kuhabiskan seluruh kuenya — beres sudah") dengan 케이크를 다 먹어 버렸다 ("aku malah menghabiskan seluruh kuenya", berbumbu rasa ups/menyesal): 치우다 menekankan menyingkirkan sebuah tugas, 버리다 menekankan akibat yang tak bisa ditarik kembali. Ragamnya santai sampai netral dan sangat lazim dalam percakapan, jadi cocok secara alami dengan akhiran 해요/했어요, tetapi terasa terlalu informal untuk tulisan resmi. Catatan ejaan: karena 치우다 di sini adalah 보조 용언 (verba bantu), 한글 맞춤법 mengizinkan KEDUA bentuk terpisah 먹어 치우다 (yang baku/prinsipnya) MAUPUN bentuk menyatu 먹어치우다 — jadi menuliskannya menyatu diperbolehkan, bukan kesalahan. Jebakan sebenarnya bagi pembelajar adalah mengacaukan 치우다 bantu ini dengan kata kerja utama harfiah 치우다 ("merapikan, membereskan"): sebagai verba bantu ia harus mengikuti kata kerja -아/어 sebelumnya, bukan langsung mengambil objek berupa nomina.',
      '-아/어 치우다 gắn vào gốc động từ và mang nghĩa hoàn tất một việc gì đó một cách dứt khoát và nhanh gọn, thường là việc nhà hay việc khó chịu mà bạn muốn giải quyết cho xong — "làm cho xong / xử lý nhanh gọn". Nó tuân theo quy tắc hài hòa nguyên âm 아/어 thông thường: gốc có nguyên âm cuối là ㅏ/ㅗ thì lấy -아 치우다 (닦다 → 닦아 치우다 "chùi sạch hết cho xong", 막다 → 막아 치우다), còn các gốc khác lấy -어 치우다 (먹다 → 먹어 치우다 "chén sạch", 읽다 → 읽어 치우다 "đọc cho xong phần này"; 끝내다 → 끝내어 치우다, rút gọn thành 끝내 치우다). Động từ 하다 trở thành 해 치우다 (숙제를 해 치우다 "làm bài tập một mạch cho xong"). Nó chia ngay trên chính 치우다, nên thì và mức độ lịch sự nằm ở trợ động từ: 다 먹어 치웠어요 "tôi đã chén sạch hết", 일을 해 치울게요 "tôi sẽ làm cho xong việc luôn".\n\nNgười hàng xóm gần gũi cần để ý là -아/어 버리다, cũng đánh dấu sự hoàn tất nhưng tô thêm sắc thái tiếc nuối, nhẹ nhõm hoặc tính dứt điểm thay vì sự nhanh gọn hiệu quả. Hãy so sánh 케이크를 다 먹어 치웠다 ("tôi đã xử lý hết cả cái bánh — giải quyết xong") với 케이크를 다 먹어 버렸다 ("tôi lỡ ăn hết cả cái bánh", pha chút ôi thôi/tiếc nuối): 치우다 nhấn mạnh việc dọn dẹp một nhiệm vụ cho gọn, còn 버리다 nhấn mạnh hậu quả không thể đảo ngược. Văn phong từ thân mật đến trung tính và rất phổ biến trong lời nói, nên nó kết hợp tự nhiên với các đuôi 해요/했어요, nhưng nghe quá khẩu ngữ đối với văn viết trang trọng. Lưu ý về chính tả: vì 치우다 ở đây là 보조 용언 (trợ động từ), 한글 맞춤법 cho phép CẢ dạng viết tách 먹어 치우다 (dạng chuẩn/nguyên tắc) LẪN dạng viết liền 먹어치우다 — nên viết liền là được phép, không phải lỗi. Cái bẫy thực sự với người học là nhầm 치우다 trợ động từ này với động từ chính theo nghĩa đen 치우다 ("dọn dẹp, thu dọn"): với tư cách trợ động từ, nó phải đi sau một động từ ở dạng -아/어, chứ không trực tiếp nhận tân ngữ là danh từ.',
      '-아/어 치우다 は動詞の語幹に付き、何かをてきぱきと一気に片づける、しばしば面倒な雑用や厄介な仕事をさっさと終わらせてしまう、という意味です——「やってしまう/手早く済ませる」。通常の 아/어 母音調和の規則に従います。最後の母音が ㅏ/ㅗ の語幹は -아 치우다 をとり(닦다 → 닦아 치우다「すっかり磨き上げて終わらせる」、막다 → 막아 치우다)、それ以外の語幹は -어 치우다 をとります(먹다 → 먹어 치우다「平らげてしまう」、읽다 → 읽어 치우다「読書をさっと片づける」、끝내다 → 끝내어 치우다 は縮約して 끝내 치우다)。하다 動詞は 해 치우다 になります(숙제를 해 치우다「宿題を一気に片づける」)。活用するのは 치우다 自身なので、時制や丁寧さは補助動詞の側に乗ります。다 먹어 치웠어요「全部平らげちゃった」、일을 해 치울게요「仕事をさっと片づけちゃいますね」。\n\n注意すべき近い隣人は -아/어 버리다 で、これも完了を表しますが、てきぱきとした効率というより、後悔・安堵・取り返しのつかなさといった色合いを帯びます。케이크를 다 먹어 치웠다(「ケーキを全部平らげた——片づけた」)と 케이크를 다 먹어 버렸다(「ケーキを全部食べちゃった」、しまった/後悔のニュアンス)を比べてみてください。치우다 は仕事を片づけることを強調し、버리다 は取り返しのつかない結末を強調します。語調はくだけた〜中立で会話で非常によく使われるため、해요/했어요 の語尾と自然になじみますが、改まった文章には口語的すぎる感じになります。表記の注意:ここでの 치우다 は 보조 용언(補助用言)なので、한글 맞춤법 では分かち書きの 먹어 치우다(標準・原則)も、くっつけた 먹어치우다 もどちらも認められています——つまりつなげて書いても許容され、誤りではありません。学習者の本当の落とし穴は、この補助動詞の 치우다 を、文字どおりの本動詞 치우다(「片づける、整理する」)と混同することです。補助動詞としては、前の -아/어 形の動詞に続かなければならず、名詞の目的語を直接とることはできません。',
    ),
  '-아/어 봤자 / 봐야': L(
      'Expresses that an effort is futile — "even if (you) try/do ..., it won\'t help / it\'s pointless / no use." It attaches to a verb stem just like the -아/어 connective: bright vowels (ㅏ/ㅗ) take -아 봤자, other vowels take -어 봤자, and 하- becomes 해 봤자. So 가다 → 가 봤자 ("even if you go"), 먹다 → 먹어 봤자 ("even if you eat"), 노력하다 → 노력해 봤자 ("even if you try hard"): 지금 가 봤자 차가 막혀서 못 가요 ("even if you leave now, the traffic will block you"). The clause that follows states the disappointing, no-better-anyway result. 봤자 (past form of 보다) is the everyday spoken/written shape; 봐야 is a slightly more colloquial variant with the same meaning (가 봐야 소용없어).\n\nDon\'t confuse it with -아/어도 ("even if / even though"), which is neutral concession: -아/어도 just grants the condition, while -아/어 봤자 adds the judgment that the attempt is useless or amounts to little. Compare 울어도 소용없어 ("crying won\'t help" — plain concession) with 울어 봤자 소용없어 ("no point even crying" — the effort is explicitly belittled as futile). Because 봤자 carries this dismissive, "it\'s not worth it" tone, it sounds casual and is common in 반말 or informal 해요 speech (가 봤자죠), and is usually avoided in stiff formal writing. The most common learner mistake is treating it as a true past tense — 봤자 looks like 봤 (past), but the meaning is hypothetical/future ("even if you were to ..."), so pair it with a present or future result clause, not a past one.',
      'Expresa que un esfuerzo es inútil: "aunque (lo) intentes/hagas..., no servirá / no tiene sentido / es en vano". Se une a la raíz de un verbo igual que el conector -아/어: las vocales claras (ㅏ/ㅗ) toman -아 봤자, las demás vocales toman -어 봤자, y 하- se vuelve 해 봤자. Así 가다 → 가 봤자 ("aunque vayás"), 먹다 → 먹어 봤자 ("aunque comás"), 노력하다 → 노력해 봤자 ("aunque te esfuerces mucho"): 지금 가 봤자 차가 막혀서 못 가요 ("aunque salgás ahora, el tráfico te va a frenar"). La cláusula que sigue indica el resultado decepcionante, que de todos modos no mejora. 봤자 (forma pasada de 보다) es la forma cotidiana hablada y escrita; 봐야 es una variante un poco más coloquial con el mismo significado (가 봐야 소용없어).\n\nNo lo confundás con -아/어도 ("aunque / aun si"), que es una concesión neutral: -아/어도 solo admite la condición, mientras que -아/어 봤자 agrega el juicio de que el intento es inútil o vale poco. Compará 울어도 소용없어 ("llorar no sirve" — concesión simple) con 울어 봤자 소용없어 ("no tiene sentido ni llorar" — el esfuerzo se desestima explícitamente como inútil). Como 봤자 lleva ese tono desdeñoso de "no vale la pena", suena casual y es común en 반말 o en el habla informal con 해요 (가 봤자죠), y normalmente se evita en la escritura formal rígida. El error más común del estudiante es tratarlo como un pasado real: 봤자 parece 봤 (pasado), pero el significado es hipotético/futuro ("aun si fueras a..."), así que combinalo con una cláusula de resultado en presente o futuro, no en pasado.',
      'Exprime qu\'un effort est vain : « même si (tu) essaies/fais..., ça ne servira à rien / c\'est inutile / ça ne sert à rien ». Cela s\'attache au radical d\'un verbe exactement comme le connecteur -아/어 : les voyelles claires (ㅏ/ㅗ) prennent -아 봤자, les autres voyelles prennent -어 봤자, et 하- devient 해 봤자. Ainsi 가다 → 가 봤자 (« même si tu y vas »), 먹다 → 먹어 봤자 (« même si tu manges »), 노력하다 → 노력해 봤자 (« même si tu fais beaucoup d\'efforts ») : 지금 가 봤자 차가 막혀서 못 가요 (« même si tu pars maintenant, les embouteillages t\'empêcheront de passer »). La proposition qui suit indique le résultat décevant, qui de toute façon ne s\'améliore pas. 봤자 (forme passée de 보다) est la forme courante à l\'oral comme à l\'écrit ; 봐야 est une variante un peu plus familière de même sens (가 봐야 소용없어).\n\nNe le confonds pas avec -아/어도 (« même si »), qui est une concession neutre : -아/어도 accorde simplement la condition, tandis que -아/어 봤자 ajoute le jugement que la tentative est inutile ou revient à peu de chose. Compare 울어도 소용없어 (« pleurer ne sert à rien » — simple concession) avec 울어 봤자 소용없어 (« ça ne sert à rien de pleurer » — l\'effort est explicitement rabaissé comme vain). Comme 봤자 porte ce ton dédaigneux de « ça n\'en vaut pas la peine », il sonne familier et est courant en 반말 ou dans le langage informel en 해요 (가 봤자죠), et on l\'évite généralement dans l\'écrit formel rigide. L\'erreur la plus fréquente des apprenants est de le traiter comme un vrai passé : 봤자 ressemble à 봤 (passé), mais le sens est hypothétique/futur (« même si tu devais... »), donc associe-le à une proposition de résultat au présent ou au futur, pas au passé.',
      'Expressa que um esforço é inútil: "mesmo que (você) tente/faça..., não vai adiantar / não tem sentido / não vale a pena". Liga-se ao radical de um verbo exatamente como o conectivo -아/어: vogais claras (ㅏ/ㅗ) recebem -아 봤자, as demais vogais recebem -어 봤자, e 하- vira 해 봤자. Assim 가다 → 가 봤자 ("mesmo que você vá"), 먹다 → 먹어 봤자 ("mesmo que você coma"), 노력하다 → 노력해 봤자 ("mesmo que você se esforce muito"): 지금 가 봤자 차가 막혀서 못 가요 ("mesmo que você saia agora, o trânsito vai te impedir"). A oração que vem em seguida indica o resultado decepcionante, que de qualquer forma não melhora. 봤자 (forma passada de 보다) é a forma cotidiana, falada e escrita; 봐야 é uma variante um pouco mais coloquial com o mesmo sentido (가 봐야 소용없어).\n\nNão confunda com -아/어도 ("mesmo que / ainda que"), que é uma concessão neutra: -아/어도 apenas admite a condição, enquanto -아/어 봤자 acrescenta o juízo de que a tentativa é inútil ou rende pouco. Compare 울어도 소용없어 ("chorar não adianta" — concessão simples) com 울어 봤자 소용없어 ("não tem sentido nem chorar" — o esforço é explicitamente desvalorizado como inútil). Como 봤자 carrega esse tom desdenhoso de "não vale a pena", soa casual e é comum em 반말 ou na fala informal em 해요 (가 봤자죠), e costuma ser evitado na escrita formal rígida. O erro mais comum de quem aprende é tratá-lo como um passado de verdade: 봤자 parece 봤 (passado), mas o sentido é hipotético/futuro ("ainda que você fosse..."), então combine-o com uma oração de resultado no presente ou futuro, não no passado.',
      'แสดงว่าความพยายามนั้นไร้ผล — "ต่อให้ (คุณ) ลอง/ทำ... ก็ไม่ช่วยอะไร / ไม่มีประโยชน์ / เปล่าประโยชน์" มันเติมเข้ากับก้านคำกริยาเหมือนกับตัวเชื่อม -아/어 ทุกประการ: สระเสียงสว่าง (ㅏ/ㅗ) ใช้ -아 봤자, สระอื่น ๆ ใช้ -어 봤자, และ 하- กลายเป็น 해 봤자 ดังนั้น 가다 → 가 봤자 ("ต่อให้ไปก็เถอะ"), 먹다 → 먹어 봤자 ("ต่อให้กินก็เถอะ"), 노력하다 → 노력해 봤자 ("ต่อให้พยายามหนักก็เถอะ"): 지금 가 봤자 차가 막혀서 못 가요 ("ต่อให้ออกตอนนี้ รถก็ติดจนไปไม่ได้") อนุประโยคที่ตามมาบอกผลลัพธ์ที่น่าผิดหวัง ซึ่งยังไงก็ไม่ดีขึ้น 봤자 (รูปอดีตของ 보다) เป็นรูปที่ใช้ในชีวิตประจำวันทั้งพูดและเขียน ส่วน 봐야 เป็นรูปที่ลำลองขึ้นเล็กน้อยแต่ความหมายเหมือนกัน (가 봐야 소용없어)\n\nอย่าสับสนกับ -아/어도 ("ถึงแม้ว่า / แม้ว่า") ซึ่งเป็นการยอมรับเงื่อนไขแบบกลาง ๆ: -아/어도 แค่ยอมรับเงื่อนไข ในขณะที่ -아/어 봤자 เพิ่มการตัดสินว่าความพยายามนั้นไร้ประโยชน์หรือแทบไม่ได้อะไร ลองเทียบ 울어도 소용없어 ("ร้องไห้ก็ไม่ช่วยอะไร" — การยอมรับธรรมดา) กับ 울어 봤자 소용없어 ("ต่อให้ร้องไห้ก็ไม่มีประโยชน์" — ความพยายามถูกลดค่าอย่างชัดเจนว่าไร้ผล) เพราะ 봤자 มีน้ำเสียงดูแคลนแบบ "ไม่คุ้มที่จะทำ" จึงฟังดูลำลองและพบบ่อยใน 반말 หรือคำพูดแบบไม่เป็นทางการที่ใช้ 해요 (가 봤자죠) และมักเลี่ยงในงานเขียนทางการที่เคร่งครัด ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือการมองว่ามันเป็นอดีตกาลจริง ๆ: 봤자 ดูเหมือน 봤 (อดีต) แต่ความหมายเป็นการสมมติ/อนาคต ("ต่อให้คุณจะ...") ดังนั้นจึงต้องจับคู่กับอนุประโยคผลลัพธ์ที่เป็นปัจจุบันหรืออนาคต ไม่ใช่อดีต',
      'Menyatakan bahwa suatu usaha itu sia-sia — "meskipun (kamu) mencoba/melakukan..., tidak akan berguna / percuma / tidak ada gunanya". Pola ini menempel pada akar kata kerja persis seperti penghubung -아/어: vokal terang (ㅏ/ㅗ) memakai -아 봤자, vokal lain memakai -어 봤자, dan 하- menjadi 해 봤자. Jadi 가다 → 가 봤자 ("meskipun kamu pergi"), 먹다 → 먹어 봤자 ("meskipun kamu makan"), 노력하다 → 노력해 봤자 ("meskipun kamu berusaha keras"): 지금 가 봤자 차가 막혀서 못 가요 ("meskipun kamu berangkat sekarang, kemacetan akan menghalangimu"). Klausa yang menyusul menyatakan hasil yang mengecewakan, yang toh tetap tidak lebih baik. 봤자 (bentuk lampau dari 보다) adalah bentuk sehari-hari dalam ujaran maupun tulisan; 봐야 adalah varian yang sedikit lebih santai dengan makna yang sama (가 봐야 소용없어).\n\nJangan mencampuradukkannya dengan -아/어도 ("meskipun / walaupun"), yang merupakan konsesi netral: -아/어도 hanya mengakui kondisinya, sedangkan -아/어 봤자 menambahkan penilaian bahwa upaya itu sia-sia atau tidak berarti banyak. Bandingkan 울어도 소용없어 ("menangis tidak ada gunanya" — konsesi biasa) dengan 울어 봤자 소용없어 ("percuma saja menangis" — usahanya secara eksplisit diremehkan sebagai sia-sia). Karena 봤자 membawa nada meremehkan "tidak sepadan" ini, pola ini terdengar santai dan umum dalam 반말 atau tuturan 해요 yang tidak formal (가 봤자죠), serta biasanya dihindari dalam tulisan formal yang kaku. Kesalahan paling umum yang dilakukan pelajar adalah memperlakukannya sebagai bentuk lampau sungguhan: 봤자 terlihat seperti 봤 (lampau), tetapi maknanya bersifat hipotetis/masa depan ("seandainya kamu..."), jadi pasangkanlah dengan klausa hasil berbentuk sekarang atau masa depan, bukan lampau.',
      'Diễn tả rằng một nỗ lực là vô ích — "dù (bạn) có thử/làm... cũng chẳng ích gì / vô nghĩa / vô ích". Nó gắn vào thân động từ giống hệt như liên kết -아/어: nguyên âm sáng (ㅏ/ㅗ) lấy -아 봤자, các nguyên âm khác lấy -어 봤자, và 하- trở thành 해 봤자. Vậy nên 가다 → 가 봤자 ("dù bạn có đi"), 먹다 → 먹어 봤자 ("dù bạn có ăn"), 노력하다 → 노력해 봤자 ("dù bạn có cố gắng hết sức"): 지금 가 봤자 차가 막혀서 못 가요 ("dù bạn có đi bây giờ, kẹt xe cũng khiến bạn không đi được"). Mệnh đề theo sau nêu ra kết quả đáng thất vọng, mà dù sao cũng chẳng khá hơn. 봤자 (dạng quá khứ của 보다) là dạng thường dùng cả khi nói lẫn khi viết; 봐야 là một biến thể hơi đời thường hơn nhưng cùng nghĩa (가 봐야 소용없어).\n\nĐừng nhầm nó với -아/어도 ("dù / cho dù"), vốn là sự nhượng bộ trung tính: -아/어도 chỉ chấp nhận điều kiện, trong khi -아/어 봤자 thêm vào phán đoán rằng nỗ lực đó là vô ích hoặc chẳng đáng là bao. Hãy so sánh 울어도 소용없어 ("khóc cũng chẳng ích gì" — nhượng bộ thuần túy) với 울어 봤자 소용없어 ("có khóc cũng vô ích" — nỗ lực bị xem nhẹ một cách rõ ràng là vô vọng). Vì 봤자 mang sắc thái khinh thường, "không đáng" này, nên nó nghe có vẻ suồng sã và phổ biến trong 반말 hoặc lối nói 해요 không trang trọng (가 봤자죠), và thường bị tránh trong văn viết trang trọng cứng nhắc. Lỗi phổ biến nhất của người học là coi nó như thì quá khứ thực sự: 봤자 trông giống 봤 (quá khứ), nhưng nghĩa lại mang tính giả định/tương lai ("dù bạn có định..."), nên hãy ghép nó với mệnh đề kết quả ở hiện tại hoặc tương lai, chứ không phải quá khứ.',
      '努力が無駄であること——「(～しても無駄だ／意味がない／やっても仕方がない」を表します。-아/어の接続とまったく同じように動詞語幹に付きます。陽母音(ㅏ/ㅗ)は -아 봤자、それ以外の母音は -어 봤자、そして 하- は 해 봤자 になります。つまり 가다 → 가 봤자(「行っても」)、먹다 → 먹어 봤자(「食べても」)、노력하다 → 노력해 봤자(「頑張っても」):지금 가 봤자 차가 막혀서 못 가요(「今出発しても渋滞で行けませんよ」)。後ろに続く節は、どうせ良くならない期待外れの結果を述べます。봤자(보다 の過去形)は話し言葉でも書き言葉でも使う日常的な形で、봐야 はやや口語的な変種ですが意味は同じです(가 봐야 소용없어)。\n\n-아/어도(「～しても／～でも」)と混同しないでください。これは中立的な譲歩で、-아/어도 は単に条件を認めるだけですが、-아/어 봤자 は「試みが無駄だ／たいしたことにならない」という判断を加えます。울어도 소용없어(「泣いても無駄だ」——単なる譲歩)と 울어 봤자 소용없어(「泣いたところで無駄だ」——努力をはっきり無意味だと見下す)を比べてみてください。봤자 はこの「やる価値がない」という見下した語感を持つため、カジュアルに響き、반말 やくだけた 해요 体でよく使われ(가 봤자죠)、堅い改まった書き言葉では普通避けられます。学習者が最もよくする間違いは、これを本当の過去時制として扱うことです。봤자 は 봤(過去)のように見えますが、意味は仮定・未来(「仮に～しても」)なので、過去ではなく現在か未来の結果節と組み合わせてください。',
    ),
  '-고 보다 / -고 보니(까)': L(
      'Marks a retrospective discovery: you do an action, and only afterward come to realize, notice, or find out something — "after doing X, I realized / it turned out that ...". The full pattern is -고 보니(까), formed by adding the connective -고 directly to a verb stem (no allomorph choice — -고 attaches identically after both vowel and consonant stems): 가다 → 가고 보니까 ("after going, I realized..."), 먹다 → 먹고 보니까 ("after eating, I found out..."), 듣다 → 듣고 보니까. The 보다 here literally means "look," but bleaches into "and then I came to see/realize," and 보니(까) carries the discovery. The -까 is optional and freely droppable: 살고 보니 and 살고 보니까 are the same. The realized fact usually goes in past tense in the main clause: 사고 보니 너무 비쌌어요 ("after buying it, I realized it was too expensive").\n\nThe closest confusable neighbor is -다 보니(까), the in-the-middle version. -고 보니 means the action is finished first, then the realization follows (one-off sequence); -다 보니 means the realization emerges while/through repeatedly doing it (process). Minimal pair: 먹고 보니 매웠어요 ("after eating it, I realized it was spicy" — discovered post-fact) vs. 먹다 보니 매운 게 좋아졌어요 ("through eating [over time], I came to like spicy food" — gradual). Register is neutral; it works in 해요체 and formal speech alike. The most common learner mistake is confusing these two — using -고 보니 for a gradual process — and over-using 보니까 where plain 보니 is more natural in writing. In speech 보니까 is the everyday default.',
      'Marca un descubrimiento retrospectivo: hacés una acción y solo después llegás a darte cuenta, notar o averiguar algo — "después de hacer X, me di cuenta / resultó que...". El patrón completo es -고 보니(까), que se forma agregando el conectivo -고 directamente a la raíz de un verbo (no hay que elegir alomorfo — -고 se pega igual después de raíces que terminan en vocal o en consonante): 가다 → 가고 보니까 ("después de ir, me di cuenta..."), 먹다 → 먹고 보니까 ("después de comer, averigüé..."), 듣다 → 듣고 보니까. Acá 보다 literalmente significa "mirar", pero se descolora hasta volverse "y entonces llegué a ver/darme cuenta", y 보니(까) carga el descubrimiento. El -까 es opcional y se puede dejar caer libremente: 살고 보니 y 살고 보니까 son lo mismo. El hecho descubierto suele ir en pasado en la cláusula principal: 사고 보니 너무 비쌌어요 ("después de comprarlo, me di cuenta de que era demasiado caro").\n\nEl vecino más fácil de confundir es -다 보니(까), la versión "en plena acción". -고 보니 significa que la acción se termina primero y luego sigue la realización (secuencia puntual); -다 보니 significa que la realización surge mientras/a través de hacerlo repetidamente (proceso). Par mínimo: 먹고 보니 매웠어요 ("después de comerlo, me di cuenta de que picaba" — descubierto después del hecho) frente a 먹다 보니 매운 게 좋아졌어요 ("a fuerza de comer [con el tiempo], me empezó a gustar la comida picante" — gradual). El registro es neutro; funciona tanto en 해요체 como en habla formal. El error más común de quien aprende es confundir estos dos — usar -고 보니 para un proceso gradual — y abusar de 보니까 donde 보니 a secas es más natural por escrito. Al hablar, 보니까 es lo normal del día a día.',
      'Marque une découverte rétrospective : tu fais une action, et c\'est seulement après que tu en viens à réaliser, remarquer ou apprendre quelque chose — « après avoir fait X, j\'ai réalisé / il s\'est avéré que... ». Le schéma complet est -고 보니(까), formé en ajoutant le connecteur -고 directement à la base verbale (pas de choix d\'allomorphe — -고 s\'attache de façon identique après une base en voyelle ou en consonne) : 가다 → 가고 보니까 (« après être allé, j\'ai réalisé... »), 먹다 → 먹고 보니까 (« après avoir mangé, j\'ai découvert... »), 듣다 → 듣고 보니까. Ici 보다 signifie littéralement « regarder », mais se délave en « et alors j\'en suis venu à voir/réaliser », et 보니(까) porte la découverte. Le -까 est facultatif et peut tomber librement : 살고 보니 et 살고 보니까 sont identiques. Le fait découvert se met d\'ordinaire au passé dans la proposition principale : 사고 보니 너무 비쌌어요 (« après l\'avoir acheté, j\'ai réalisé que c\'était trop cher »).\n\nLe voisin le plus facile à confondre est -다 보니(까), la version « en cours d\'action ». -고 보니 signifie que l\'action s\'achève d\'abord, puis la prise de conscience suit (séquence ponctuelle) ; -다 보니 signifie que la prise de conscience émerge pendant/à travers une action répétée (processus). Paire minimale : 먹고 보니 매웠어요 (« après l\'avoir mangé, j\'ai réalisé que c\'était épicé » — découvert après coup) contre 먹다 보니 매운 게 좋아졌어요 (« à force de manger [au fil du temps], je me suis mis à aimer la nourriture épicée » — graduel). Le registre est neutre ; ça marche aussi bien en 해요체 qu\'en langage formel. L\'erreur la plus fréquente des apprenants est de confondre ces deux formes — utiliser -고 보니 pour un processus graduel — et de surutiliser 보니까 là où le simple 보니 est plus naturel à l\'écrit. À l\'oral, 보니까 est la valeur par défaut du quotidien.',
      'Marca uma descoberta retrospectiva: você realiza uma ação e só depois chega a perceber, notar ou descobrir algo — "depois de fazer X, percebi / no fim das contas...". O padrão completo é -고 보니(까), formado adicionando o conectivo -고 diretamente ao radical do verbo (não há escolha de alomorfe — -고 se prende de forma idêntica após radicais terminados em vogal ou em consoante): 가다 → 가고 보니까 ("depois de ir, percebi..."), 먹다 → 먹고 보니까 ("depois de comer, descobri..."), 듣다 → 듣고 보니까. Aqui 보다 significa literalmente "olhar", mas se desbota em "e então cheguei a ver/perceber", e 보니(까) carrega a descoberta. O -까 é opcional e pode ser omitido livremente: 살고 보니 e 살고 보니까 são a mesma coisa. O fato descoberto costuma ir no passado na oração principal: 사고 보니 너무 비쌌어요 ("depois de comprar, percebi que estava caro demais").\n\nO vizinho mais fácil de confundir é -다 보니(까), a versão "em meio à ação". -고 보니 significa que a ação termina primeiro e então vem a constatação (sequência pontual); -다 보니 significa que a constatação surge enquanto/por meio de fazê-la repetidamente (processo). Par mínimo: 먹고 보니 매웠어요 ("depois de comer, percebi que era apimentado" — descoberto após o fato) versus 먹다 보니 매운 게 좋아졌어요 ("de tanto comer [ao longo do tempo], passei a gostar de comida apimentada" — gradual). O registro é neutro; funciona tanto no 해요체 quanto na fala formal. O erro mais comum de quem aprende é confundir esses dois — usar -고 보니 para um processo gradual — e abusar de 보니까 onde o simples 보니 é mais natural na escrita. Na fala, 보니까 é o padrão do dia a dia.',
      'บ่งบอกการค้นพบย้อนหลัง คือคุณทำสิ่งหนึ่งก่อน แล้วหลังจากนั้นจึงค่อยตระหนัก สังเกตเห็น หรือรู้บางอย่าง — "หลังจากทำ X แล้ว ฉันก็เพิ่งรู้ / กลายเป็นว่า...". รูปเต็มคือ -고 보니(까) เกิดจากการเติมตัวเชื่อม -고 เข้ากับรากคำกริยาโดยตรง (ไม่มีการเลือกรูปแปร — -고 ต่อท้ายเหมือนกันทั้งหลังรากที่ลงท้ายด้วยสระและพยัญชนะ): 가다 → 가고 보니까 ("หลังจากไปแล้ว ฉันก็เพิ่งรู้..."), 먹다 → 먹고 보니까 ("หลังจากกินแล้ว ฉันก็เพิ่งรู้..."), 듣다 → 듣고 보니까. ในที่นี้ 보다 แปลตรงตัวว่า "มอง" แต่จางความหมายลงกลายเป็น "แล้วฉันก็มาเห็น/มาตระหนัก" และ 보니(까) คือส่วนที่แบกความหมายของการค้นพบไว้ ส่วน -까 ใส่หรือไม่ใส่ก็ได้ ตัดทิ้งได้อย่างอิสระ: 살고 보니 กับ 살고 보니까 มีความหมายเหมือนกัน สิ่งที่ค้นพบมักอยู่ในรูปอดีตในประโยคหลัก: 사고 보니 너무 비쌌어요 ("หลังจากซื้อมาแล้ว ฉันก็เพิ่งรู้ว่ามันแพงเกินไป").\n\nเพื่อนบ้านที่สับสนง่ายที่สุดคือ -다 보니(까) ซึ่งเป็นรูป "ระหว่างที่กำลังทำ" -고 보니 หมายความว่าการกระทำจบลงก่อน แล้วการตระหนักจึงตามมา (ลำดับเหตุการณ์ครั้งเดียวจบ); -다 보니 หมายความว่าการตระหนักค่อย ๆ ผุดขึ้นในระหว่าง/ผ่านการทำซ้ำ ๆ (กระบวนการ) คู่เปรียบเทียบ: 먹고 보니 매웠어요 ("หลังจากกินแล้ว ฉันก็เพิ่งรู้ว่ามันเผ็ด" — ค้นพบหลังจากเกิดเหตุ) เทียบกับ 먹다 보니 매운 게 좋아졌어요 ("พอกินไปเรื่อย ๆ [เมื่อเวลาผ่านไป] ฉันก็เริ่มชอบอาหารเผ็ด" — แบบค่อยเป็นค่อยไป) ระดับภาษาเป็นกลาง ใช้ได้ทั้งใน 해요체 และในภาษาทางการ ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือสับสนสองรูปนี้ — ใช้ -고 보니 กับกระบวนการที่ค่อยเป็นค่อยไป — และใช้ 보니까 มากเกินไปในที่ที่ 보니 เฉย ๆ เป็นธรรมชาติกว่าในงานเขียน ส่วนในการพูด 보니까 เป็นรูปที่ใช้กันทั่วไปในชีวิตประจำวัน',
      'Menandai sebuah penemuan retrospektif: kamu melakukan suatu tindakan, dan baru sesudahnya kamu menyadari, memperhatikan, atau mengetahui sesuatu — "setelah melakukan X, aku menyadari / ternyata...". Pola lengkapnya adalah -고 보니(까), dibentuk dengan menambahkan penghubung -고 langsung pada akar kata kerja (tanpa pilihan alomorf — -고 menempel secara identik baik setelah akar berakhiran vokal maupun konsonan): 가다 → 가고 보니까 ("setelah pergi, aku menyadari..."), 먹다 → 먹고 보니까 ("setelah makan, aku mengetahui..."), 듣다 → 듣고 보니까. Di sini 보다 secara harfiah berarti "melihat", tetapi maknanya memudar menjadi "dan kemudian aku jadi melihat/menyadari", dan 보니(까) yang membawa makna penemuan itu. Bagian -까 bersifat opsional dan bisa dilesapkan dengan bebas: 살고 보니 dan 살고 보니까 sama saja. Fakta yang disadari biasanya muncul dalam bentuk lampau pada klausa utama: 사고 보니 너무 비쌌어요 ("setelah membelinya, aku menyadari bahwa harganya terlalu mahal").\n\nTetangga yang paling mudah dikelirukan adalah -다 보니(까), yaitu versi "di tengah tindakan". -고 보니 berarti tindakan selesai dulu, lalu kesadaran menyusul (urutan sekali jadi); -다 보니 berarti kesadaran itu muncul sewaktu/melalui melakukannya berulang-ulang (proses). Pasangan minimal: 먹고 보니 매웠어요 ("setelah memakannya, aku menyadari bahwa itu pedas" — diketahui setelah faktanya) versus 먹다 보니 매운 게 좋아졌어요 ("karena terus makan [seiring waktu], aku jadi menyukai makanan pedas" — bertahap). Registernya netral; ini berfungsi baik dalam 해요체 maupun dalam tutur formal. Kesalahan paling umum bagi pembelajar adalah mengelirukan keduanya — memakai -고 보니 untuk proses yang bertahap — serta terlalu sering memakai 보니까 di tempat yang lebih wajar memakai 보니 saja dalam tulisan. Dalam percakapan, 보니까 adalah pilihan sehari-hari yang lazim.',
      'Đánh dấu một sự phát hiện hồi cố: bạn làm một hành động, và chỉ sau đó mới đi đến chỗ nhận ra, để ý, hoặc biết được điều gì đó — "sau khi làm X, tôi nhận ra / hóa ra là...". Mẫu đầy đủ là -고 보니(까), được tạo bằng cách thêm liên kết -고 trực tiếp vào gốc động từ (không có lựa chọn biến thể — -고 gắn vào giống hệt nhau sau cả gốc kết thúc bằng nguyên âm lẫn phụ âm): 가다 → 가고 보니까 ("sau khi đi, tôi nhận ra..."), 먹다 → 먹고 보니까 ("sau khi ăn, tôi phát hiện ra..."), 듣다 → 듣고 보니까. Ở đây 보다 nghĩa đen là "nhìn", nhưng phai nghĩa đi thành "và rồi tôi đi đến chỗ thấy/nhận ra", còn 보니(까) mang ý phát hiện. Phần -까 là tùy chọn và có thể bỏ đi thoải mái: 살고 보니 và 살고 보니까 là như nhau. Sự việc được nhận ra thường ở thì quá khứ trong mệnh đề chính: 사고 보니 너무 비쌌어요 ("sau khi mua, tôi nhận ra nó quá đắt").\n\nNgười hàng xóm dễ nhầm lẫn nhất là -다 보니(까), phiên bản "đang trong lúc làm". -고 보니 nghĩa là hành động kết thúc trước, rồi sự nhận ra mới theo sau (chuỗi một lần dứt điểm); -다 보니 nghĩa là sự nhận ra nảy sinh trong khi/qua việc làm đi làm lại (quá trình). Cặp tối thiểu: 먹고 보니 매웠어요 ("sau khi ăn, tôi nhận ra nó cay" — phát hiện sau sự việc) so với 먹다 보니 매운 게 좋아졌어요 ("ăn riết [theo thời gian], tôi đâm ra thích đồ cay" — dần dần). Sắc thái trung tính; nó dùng được cả trong 해요체 lẫn trong lối nói trang trọng. Lỗi phổ biến nhất của người học là nhầm hai mẫu này — dùng -고 보니 cho một quá trình diễn ra dần dần — và lạm dụng 보니까 ở chỗ mà 보니 trơn lại tự nhiên hơn khi viết. Trong lời nói, 보니까 là lựa chọn mặc định hằng ngày.',
      '過去を振り返っての気づきを表します。ある動作をして、その後になって初めて何かに気づく・思い当たる・判明する、というニュアンスです——「Xをしてみたら、〜だと気づいた／〜だと分かった」。完全な形は -고 보니(까) で、接続語尾 -고 を動詞の語幹に直接つけて作ります（異形態の選択はなく、母音語幹でも子音語幹でも -고 は同じように付きます）：가다 → 가고 보니까（「行ってみたら気づいた…」）、먹다 → 먹고 보니까（「食べてみたら分かった…」）、듣다 → 듣고 보니까。ここでの 보다 は文字どおりには「見る」ですが、意味が薄れて「〜してみて、(その結果)気づく」となり、気づきのニュアンスは 보니(까) が担います。-까 は任意で、自由に省けます：살고 보니 と 살고 보니까 は同じです。気づいた事実は主節でふつう過去形になります：사고 보니 너무 비쌌어요（「買ってみたら高すぎたと気づいた」）。\n\nいちばん紛らわしい隣人は -다 보니(까)、つまり「動作の途中」バージョンです。-고 보니 は動作がまず完了し、その後に気づきが続く（一回きりの連続）ことを表し、-다 보니 は繰り返し行ううちに／行うことを通して気づきが立ち上がる（過程）ことを表します。ミニマルペア：먹고 보니 매웠어요（「食べてみたら辛いと気づいた」——事後に発見）に対し、먹다 보니 매운 게 좋아졌어요（「食べているうちに[次第に]辛いものが好きになった」——徐々に）。語調は中立で、해요체 でも改まった話し方でも使えます。学習者がいちばんよくする間違いは、この二つを混同すること——徐々に進む過程に -고 보니 を使ってしまうこと——と、書き言葉ではただの 보니 のほうが自然な場面で 보니까 を使いすぎることです。話し言葉では 보니까 が日常の標準です。',
    ),
  '-고 말겠다': L(
      '-고 말겠다 expresses strong personal determination to do something "no matter what" — it is the future-tense use of -고 말다, where the speaker vows to see an action through to the end. Attach -고 directly to a verb stem (no allomorph change, regardless of 받침), then add 말겠다: vowel stem 이기다 → 이기고 말겠다 ("I will win, whatever it takes"), consonant stem 찾다 → 찾고 말겠다 ("I will find it no matter what"). It is almost always first-person and forward-looking, since it announces a resolution; in writing or formal speech you may also see -고야 말겠다 with 야 added for extra emphasis (해내고야 말겠다 "I\'ll absolutely pull it off").\n\nThe close neighbour to watch is the past-tense -고 말았다, the completion/regret use of the same -고 말다. Compare 졸업하고 말겠다 ("I will graduate no matter what" — determination) with 졸업하고 말았다 ("I ended up graduating" / "I finally graduated," often with a nuance of inevitability or rueful surprise). So the tense flips the meaning: -겠다 = a vow about the future, -았다 = a result that has already landed, frequently regrettable. Register: -겠다 here sounds firm and declarative, common in 다짐 (pledges) and dramatic speech; soften it to -고 말겠어요/-고 말 거예요 in polite conversation. The most common learner mistake is using -고 말겠다 for plain future plans where simple -겠다 or -(으)ㄹ 거예요 would do — reserve -고 말다 for genuine, against-the-odds resolve, not everyday intentions.',
      '-고 말겠다 expresa una determinación personal fuerte de hacer algo "pase lo que pase" — es el uso en futuro de -고 말다, donde quien habla jura llevar una acción hasta el final. Pegá -고 directamente a la raíz de un verbo (sin cambio de alomorfo, sin importar el 받침) y después agregá 말겠다: raíz vocálica 이기다 → 이기고 말겠다 ("voy a ganar, cueste lo que cueste"), raíz consonántica 찾다 → 찾고 말겠다 ("lo voy a encontrar pase lo que pase"). Casi siempre va en primera persona y mira hacia el futuro, porque anuncia una resolución; en lengua escrita o en habla formal también podés ver -고야 말겠다 con 야 añadido para dar más énfasis (해내고야 말겠다 "lo voy a lograr sin falta").\n\nEl vecino cercano al que tenés que prestar atención es el pasado -고 말았다, el uso de finalización/lamento del mismo -고 말다. Compará 졸업하고 말겠다 ("me voy a graduar pase lo que pase" — determinación) con 졸업하고 말았다 ("terminé graduándome" / "al final me gradué", a menudo con un matiz de inevitabilidad o de sorpresa con cierto pesar). Así que el tiempo verbal invierte el significado: -겠다 = un juramento sobre el futuro, -았다 = un resultado que ya cayó, frecuentemente lamentable. Registro: acá -겠다 suena firme y declarativo, común en 다짐 (promesas) y en el habla dramática; suavizalo a -고 말겠어요/-고 말 거예요 en una conversación cortés. El error más común de quien aprende es usar -고 말겠다 para planes futuros comunes donde bastaría un simple -겠다 o -(으)ㄹ 거예요 — reservá -고 말다 para una resolución genuina y contra todo pronóstico, no para intenciones cotidianas.',
      '-고 말겠다 exprime une forte détermination personnelle à faire quelque chose « coûte que coûte » — c\'est l\'emploi au futur de -고 말다, par lequel le locuteur jure de mener une action jusqu\'au bout. Attache -고 directement au radical d\'un verbe (aucun changement d\'allomorphe, quel que soit le 받침), puis ajoute 말겠다 : radical vocalique 이기다 → 이기고 말겠다 (« je vais gagner, quoi qu\'il arrive »), radical consonantique 찾다 → 찾고 말겠다 (« je le trouverai coûte que coûte »). C\'est presque toujours à la première personne et tourné vers l\'avenir, puisqu\'il annonce une résolution ; à l\'écrit ou dans un langage formel, tu peux aussi rencontrer -고야 말겠다 avec 야 ajouté pour renforcer l\'emphase (해내고야 말겠다 « je vais absolument y arriver »).\n\nLe voisin proche à surveiller est le passé -고 말았다, l\'emploi d\'achèvement/regret du même -고 말다. Compare 졸업하고 말겠다 (« je vais obtenir mon diplôme coûte que coûte » — détermination) avec 졸업하고 말았다 (« j\'ai fini par obtenir mon diplôme » / « j\'ai finalement obtenu mon diplôme », souvent avec une nuance d\'inévitabilité ou de surprise teintée de regret). Le temps inverse donc le sens : -겠다 = un serment sur l\'avenir, -았다 = un résultat déjà advenu, souvent regrettable. Registre : ici -겠다 sonne ferme et déclaratif, courant dans les 다짐 (engagements) et le langage dramatique ; adoucis-le en -고 말겠어요/-고 말 거예요 dans une conversation polie. L\'erreur la plus fréquente des apprenants est d\'employer -고 말겠다 pour de simples projets futurs où un -겠다 ou -(으)ㄹ 거예요 suffirait — réserve -고 말다 à une résolution authentique, contre toute attente, et non aux intentions du quotidien.',
      '-고 말겠다 expressa uma forte determinação pessoal de fazer algo "custe o que custar" — é o uso no futuro de -고 말다, em que quem fala jura levar uma ação até o fim. Anexe -고 diretamente ao radical de um verbo (sem mudança de alomorfe, independentemente do 받침) e então adicione 말겠다: radical com vogal 이기다 → 이기고 말겠다 ("eu vou vencer, custe o que custar"), radical com consoante 찾다 → 찾고 말겠다 ("eu vou encontrar isso aconteça o que acontecer"). Quase sempre vem na primeira pessoa e voltado para o futuro, já que anuncia uma resolução; na escrita ou na fala formal você também pode ver -고야 말겠다 com 야 acrescentado para dar ênfase extra (해내고야 말겠다 "eu vou conseguir, com toda a certeza").\n\nO vizinho próximo a observar é o passado -고 말았다, o uso de conclusão/arrependimento do mesmo -고 말다. Compare 졸업하고 말겠다 ("eu vou me formar custe o que custar" — determinação) com 졸업하고 말았다 ("acabei me formando" / "finalmente me formei", muitas vezes com uma nuance de inevitabilidade ou de surpresa com certo pesar). Então o tempo verbal inverte o significado: -겠다 = um juramento sobre o futuro, -았다 = um resultado que já aconteceu, frequentemente lamentável. Registro: aqui -겠다 soa firme e declarativo, comum em 다짐 (promessas) e na fala dramática; suavize para -고 말겠어요/-고 말 거예요 numa conversa educada. O erro mais comum de quem aprende é usar -고 말겠다 para planos futuros corriqueiros, em que um simples -겠다 ou -(으)ㄹ 거예요 bastaria — reserve -고 말다 para uma resolução genuína, contra todas as probabilidades, e não para intenções do dia a dia.',
      '-고 말겠다 แสดงความตั้งใจส่วนตัวอย่างแรงกล้าที่จะทำสิ่งใดสิ่งหนึ่ง "ไม่ว่าจะเกิดอะไรขึ้นก็ตาม" — เป็นการใช้รูปอนาคตของ -고 말다 ซึ่งผู้พูดให้คำมั่นว่าจะทำการกระทำนั้นให้สำเร็จจนถึงที่สุด ให้เติม -고 ต่อท้ายรากคำกริยาโดยตรง (ไม่มีการเปลี่ยนรูปอัลโลมอร์ฟ ไม่ว่าจะมี 받침 หรือไม่) แล้วเติม 말겠다: รากที่ลงท้ายด้วยสระ 이기다 → 이기고 말겠다 ("ฉันจะชนะให้ได้ ไม่ว่าจะต้องแลกด้วยอะไร") รากที่ลงท้ายด้วยพยัญชนะ 찾다 → 찾고 말겠다 ("ฉันจะหามันให้เจอ ไม่ว่าจะเกิดอะไรขึ้น") มักใช้กับบุรุษที่หนึ่งและมุ่งไปข้างหน้าเสมอ เพราะเป็นการประกาศความตั้งใจ ในงานเขียนหรือการพูดทางการ คุณอาจเห็น -고야 말겠다 ที่เติม 야 เข้าไปเพื่อเน้นย้ำมากขึ้น (해내고야 말겠다 "ฉันจะทำให้สำเร็จให้ได้อย่างแน่นอน")\n\nเพื่อนบ้านใกล้ชิดที่ต้องระวังคือรูปอดีต -고 말았다 ซึ่งเป็นการใช้ในความหมายของการเสร็จสิ้น/ความเสียดายของ -고 말다 ตัวเดียวกัน ลองเทียบ 졸업하고 말겠다 ("ฉันจะเรียนจบให้ได้ ไม่ว่าจะเกิดอะไรขึ้น" — ความตั้งใจ) กับ 졸업하고 말았다 ("ในที่สุดฉันก็เรียนจบ" / "สุดท้ายก็เรียนจบจนได้" ซึ่งมักมีนัยของความหลีกเลี่ยงไม่ได้หรือความประหลาดใจปนเสียดาย) ดังนั้นกาลจึงพลิกความหมาย: -겠다 = คำมั่นเกี่ยวกับอนาคต, -았다 = ผลลัพธ์ที่เกิดขึ้นไปแล้ว ซึ่งมักน่าเสียดาย ระดับภาษา: -겠다 ในที่นี้ฟังดูหนักแน่นและเป็นการบอกเล่า พบบ่อยใน 다짐 (คำปฏิญาณ) และคำพูดที่ดราม่า ให้ผ่อนเป็น -고 말겠어요/-고 말 거예요 ในการสนทนาแบบสุภาพ ข้อผิดพลาดที่ผู้เรียนทำบ่อยที่สุดคือการใช้ -고 말겠다 กับแผนในอนาคตทั่วๆ ไป ซึ่งแค่ -겠다 หรือ -(으)ㄹ 거예요 ก็เพียงพอแล้ว — ให้เก็บ -고 말다 ไว้ใช้กับความมุ่งมั่นที่แท้จริงและฝ่าฟันอุปสรรค ไม่ใช่ความตั้งใจในชีวิตประจำวัน',
      '-고 말겠다 mengungkapkan tekad pribadi yang kuat untuk melakukan sesuatu "apa pun yang terjadi" — ini adalah penggunaan bentuk masa depan dari -고 말다, di mana penutur bersumpah untuk menuntaskan suatu tindakan sampai akhir. Tempelkan -고 langsung pada akar kata kerja (tanpa perubahan alomorf, terlepas dari ada tidaknya 받침), lalu tambahkan 말겠다: akar berakhiran vokal 이기다 → 이기고 말겠다 ("aku akan menang, apa pun taruhannya"), akar berakhiran konsonan 찾다 → 찾고 말겠다 ("aku akan menemukannya apa pun yang terjadi"). Hampir selalu berbentuk orang pertama dan berorientasi ke depan, karena ia mengumumkan sebuah keputusan; dalam tulisan atau ujaran formal kamu juga bisa menjumpai -고야 말겠다 dengan tambahan 야 untuk penekanan ekstra (해내고야 말겠다 "aku pasti akan berhasil melakukannya").\n\nTetangga dekat yang perlu diperhatikan adalah bentuk lampau -고 말았다, penggunaan -고 말다 yang sama untuk makna penyelesaian/penyesalan. Bandingkan 졸업하고 말겠다 ("aku akan lulus apa pun yang terjadi" — tekad) dengan 졸업하고 말았다 ("aku akhirnya lulus" / "pada akhirnya aku lulus juga," sering dengan nuansa keniscayaan atau keterkejutan yang disertai sedikit penyesalan). Jadi kala membalik maknanya: -겠다 = sumpah tentang masa depan, -았다 = hasil yang sudah terjadi, sering kali disesali. Ragam bahasa: -겠다 di sini terdengar tegas dan deklaratif, lazim dalam 다짐 (ikrar) dan ujaran dramatis; perhalus menjadi -고 말겠어요/-고 말 거예요 dalam percakapan sopan. Kesalahan paling umum yang dibuat pembelajar adalah memakai -고 말겠다 untuk rencana masa depan biasa yang sebenarnya cukup dengan -겠다 atau -(으)ㄹ 거예요 — simpan -고 말다 untuk tekad yang sungguh-sungguh dan menentang segala rintangan, bukan untuk niat sehari-hari.',
      '-고 말겠다 thể hiện quyết tâm cá nhân mạnh mẽ làm một việc gì đó "bằng mọi giá" — đây là cách dùng ở thì tương lai của -고 말다, trong đó người nói thề sẽ theo đuổi hành động đến cùng. Gắn -고 trực tiếp vào gốc động từ (không thay đổi biến thể, bất kể có 받침 hay không), rồi thêm 말겠다: gốc kết thúc bằng nguyên âm 이기다 → 이기고 말겠다 ("tôi nhất định sẽ thắng, dù phải đánh đổi điều gì"), gốc kết thúc bằng phụ âm 찾다 → 찾고 말겠다 ("tôi sẽ tìm cho ra nó dù có chuyện gì xảy ra"). Hầu như luôn ở ngôi thứ nhất và hướng về tương lai, vì nó tuyên bố một quyết tâm; trong văn viết hoặc lời nói trang trọng, bạn cũng có thể thấy -고야 말겠다 với 야 được thêm vào để nhấn mạnh hơn (해내고야 말겠다 "tôi nhất định sẽ làm được").\n\nNgười hàng xóm gần gũi cần lưu ý là thì quá khứ -고 말았다, cách dùng mang nghĩa hoàn thành/tiếc nuối của cùng một -고 말다. Hãy so sánh 졸업하고 말겠다 ("tôi nhất định sẽ tốt nghiệp dù có chuyện gì" — quyết tâm) với 졸업하고 말았다 ("rốt cuộc tôi đã tốt nghiệp" / "cuối cùng tôi cũng tốt nghiệp," thường mang sắc thái không thể tránh khỏi hoặc bất ngờ pha chút tiếc nuối). Vậy nên thì làm đảo ngược ý nghĩa: -겠다 = một lời thề về tương lai, -았다 = một kết quả đã xảy ra rồi, thường đáng tiếc. Văn phong: -겠다 ở đây nghe chắc chắn và mang tính khẳng định, thường gặp trong 다짐 (lời cam kết) và lời nói đầy kịch tính; hãy làm dịu nó thành -고 말겠어요/-고 말 거예요 trong hội thoại lịch sự. Lỗi phổ biến nhất của người học là dùng -고 말겠다 cho những kế hoạch tương lai bình thường mà chỉ cần -겠다 hoặc -(으)ㄹ 거예요 là đủ — hãy để dành -고 말다 cho quyết tâm thực sự, vượt qua mọi trở ngại, chứ không phải cho những dự định thường ngày.',
      '-고 말겠다 は、何があっても何かをやり遂げるという強い個人的な決意を表します。これは -고 말다 の未来形としての用法で、話し手がある行動を最後までやり通すと誓うものです。-고 を動詞の語幹に直接つけ（받침 の有無に関わらず異形態の変化はありません）、そのあとに 말겠다 を加えます。母音語幹 이기다 → 이기고 말겠다（「何としても勝ってみせる」）、子音語幹 찾다 → 찾고 말겠다（「何があっても必ず見つけ出す」）。決意を宣言するため、ほぼ常に一人称で未来志向です。書き言葉やフォーマルな話し言葉では、強調のために 야 を加えた -고야 말겠다 を見かけることもあります（해내고야 말겠다「絶対にやり遂げてみせる」）。\n\n注意すべき近い親戚が、過去形の -고 말았다 です。これは同じ -고 말다 の完了・後悔の用法です。졸업하고 말겠다（「何があっても卒業してみせる」＝決意）と、졸업하고 말았다（「結局卒業してしまった」「ついに卒業した」、しばしば不可避さや、ややほろ苦い驚きのニュアンスを伴う）を比べてみましょう。つまり、テンスが意味を反転させます。-겠다 ＝未来についての誓い、-았다 ＝すでに起きてしまった結果で、しばしば残念な含みを持ちます。語調について。ここでの -겠다 は断固として断定的に響き、다짐（誓い）やドラマチックな台詞でよく使われます。丁寧な会話では -고 말겠어요/-고 말 거예요 と和らげましょう。学習者が最もよくする間違いは、単なる -겠다 や -(으)ㄹ 거예요 で十分なありふれた未来の予定に -고 말겠다 を使ってしまうことです。-고 말다 は、日常的な意図ではなく、困難に立ち向かう本物の決意のために取っておきましょう。',
    ),
  '-았/었어야 했다': L(
      'Expresses regret or reproach over a past action you should have done but didn\'t (or shouldn\'t have done but did): "should have...". It is built on the past tense of the verb: take the stem, add -았어야 했다 after a bright vowel (ㅏ/ㅗ) and -었어야 했다 elsewhere. So 가다 → 갔어야 했다 "should have gone" (vowel stem, ㅏ contracts), 먹다 → 먹었어야 했다 "should have eaten" (consonant/받침 stem). 하다 verbs become 했어야 했다 (공부했어야 했다 "should have studied"), and 이다 gives 이었어야/였어야 했다. The final 했다 can also appear as 했는데 to trail off with lingering regret: 일찍 잤어야 했는데 "I should have gone to bed early...".\n\nCompare it with -(으)ㄹ걸 (그랬다), the casual spoken cousin: 갔어야 했다 states the regret as a fact ("I should have gone"), while 갈걸 (그랬어) is a softer, sighing self-talk ("ugh, I should\'ve gone"). Minimal pair: 미리 예약했어야 했어요 vs. 미리 예약할걸 — both mean "I should\'ve booked ahead", but the first is firmer and works in writing or explaining a mistake, the second is intimate, almost muttered. Politeness simply rides on the final 했다: 했어 (반말), 했어요 (polite), 했습니다 (formal). The most common learner mistake is forgetting that the FIRST verb must be past tense — 가야 했다 means "had to go (obligation)", not "should have gone"; the regret reading needs the extra 았/었 layer, 갔어야 했다.',
      'Expresa arrepentimiento o reproche por una acción pasada que debías haber hecho pero no hiciste (o que no debías haber hecho pero hiciste): "debería haber...". Se construye sobre el pasado del verbo: tomá la raíz y agregá -았어야 했다 tras vocal brillante (ㅏ/ㅗ) y -었어야 했다 en los demás casos. Así 가다 → 갔어야 했다 "debería haber ido" (raíz vocálica, ㅏ se contrae), 먹다 → 먹었어야 했다 "debería haber comido" (raíz con consonante/받침). Los verbos en 하다 dan 했어야 했다 (공부했어야 했다 "debería haber estudiado"), y 이다 da 이었어야/였어야 했다. El 했다 final también puede aparecer como 했는데 para dejar la frase en suspenso con un dejo de arrepentimiento: 일찍 잤어야 했는데 "debería haberme acostado temprano...".\n\nComparalo con -(으)ㄹ걸 (그랬다), su primo coloquial y hablado: 갔어야 했다 enuncia el arrepentimiento como un hecho ("debería haber ido"), mientras que 갈걸 (그랬어) es un monólogo más suave y suspirado ("uf, debería haber ido"). Par mínimo: 미리 예약했어야 했어요 vs. 미리 예약할걸 — ambos significan "debería haber reservado con anticipación", pero el primero es más firme y sirve por escrito o para explicar un error, y el segundo es íntimo, casi murmurado. La cortesía simplemente va sobre el 했다 final: 했어 (반말), 했어요 (cortés), 했습니다 (formal). El error más común de quien aprende es olvidar que el PRIMER verbo debe ir en pasado — 가야 했다 significa "tenía que ir (obligación)", no "debería haber ido"; la lectura de arrepentimiento necesita la capa extra de 았/었, 갔어야 했다.',
      'Exprime le regret ou le reproche au sujet d\'une action passée que tu aurais dû faire mais que tu n\'as pas faite (ou que tu n\'aurais pas dû faire mais que tu as faite) : "j\'aurais dû...". Il se construit sur le passé du verbe : prends le radical, ajoute -았어야 했다 après une voyelle claire (ㅏ/ㅗ) et -었어야 했다 ailleurs. Ainsi 가다 → 갔어야 했다 "j\'aurais dû y aller" (radical vocalique, ㅏ se contracte), 먹다 → 먹었어야 했다 "j\'aurais dû manger" (radical à consonne/받침). Les verbes en 하다 donnent 했어야 했다 (공부했어야 했다 "j\'aurais dû étudier"), et 이다 donne 이었어야/였어야 했다. Le 했다 final peut aussi apparaître sous la forme 했는데 pour laisser la phrase en suspens avec un regret persistant : 일찍 잤어야 했는데 "j\'aurais dû me coucher tôt...".\n\nCompare-le avec -(으)ㄹ걸 (그랬다), son cousin familier de l\'oral : 갔어야 했다 énonce le regret comme un fait ("j\'aurais dû y aller"), tandis que 갈걸 (그랬어) est un monologue plus doux et soupiré ("ah, j\'aurais dû y aller"). Paire minimale : 미리 예약했어야 했어요 vs. 미리 예약할걸 — les deux veulent dire "j\'aurais dû réserver à l\'avance", mais le premier est plus ferme et convient à l\'écrit ou pour expliquer une erreur, le second est intime, presque murmuré. La politesse se loge simplement sur le 했다 final : 했어 (반말), 했어요 (poli), 했습니다 (formel). L\'erreur la plus fréquente des apprenants est d\'oublier que le PREMIER verbe doit être au passé — 가야 했다 signifie "il fallait y aller (obligation)", pas "j\'aurais dû y aller" ; la lecture de regret exige la couche supplémentaire de 았/었, 갔어야 했다.',
      'Expressa arrependimento ou reproche por uma ação passada que você deveria ter feito mas não fez (ou que não deveria ter feito mas fez): "deveria ter...". É construído sobre o passado do verbo: pegue o radical e adicione -았어야 했다 depois de vogal clara (ㅏ/ㅗ) e -었어야 했다 nos demais casos. Assim 가다 → 갔어야 했다 "deveria ter ido" (radical em vogal, ㅏ se contrai), 먹다 → 먹었어야 했다 "deveria ter comido" (radical com consoante/받침). Os verbos em 하다 viram 했어야 했다 (공부했어야 했다 "deveria ter estudado"), e 이다 dá 이었어야/였어야 했다. O 했다 final também pode aparecer como 했는데 para deixar a frase em suspenso com um arrependimento persistente: 일찍 잤어야 했는데 "eu deveria ter ido dormir cedo...".\n\nCompare com -(으)ㄹ걸 (그랬다), o primo coloquial e falado: 갔어야 했다 enuncia o arrependimento como um fato ("eu deveria ter ido"), enquanto 갈걸 (그랬어) é um monólogo mais suave e suspirado ("ah, eu deveria ter ido"). Par mínimo: 미리 예약했어야 했어요 vs. 미리 예약할걸 — ambos significam "eu deveria ter reservado com antecedência", mas o primeiro é mais firme e funciona por escrito ou para explicar um erro, e o segundo é íntimo, quase murmurado. A polidez simplesmente recai sobre o 했다 final: 했어 (반말), 했어요 (polido), 했습니다 (formal). O erro mais comum de quem aprende é esquecer que o PRIMEIRO verbo precisa estar no passado — 가야 했다 significa "tinha que ir (obrigação)", não "deveria ter ido"; a leitura de arrependimento precisa da camada extra de 았/었, 갔어야 했다.',
      'ใช้แสดงความเสียใจหรือการตำหนิตัวเองต่อการกระทำในอดีตที่ควรทำแต่ไม่ได้ทำ (หรือไม่ควรทำแต่กลับทำไป): "ควรจะ...แล้ว". สร้างขึ้นบนรูปอดีตของคำกริยา: เอาก้าน (stem) มา แล้วเติม -았어야 했다 หลังสระสว่าง (ㅏ/ㅗ) และเติม -었어야 했다 ในกรณีอื่น ดังนั้น 가다 → 갔어야 했다 "ควรจะไปแล้ว" (ก้านลงท้ายด้วยสระ ㅏ หดรวมกัน), 먹다 → 먹었어야 했다 "ควรจะกินแล้ว" (ก้านมีพยัญชนะ/받침) คำกริยา 하다 จะกลายเป็น 했어야 했다 (공부했어야 했다 "ควรจะอ่านหนังสือแล้ว") และ 이다 จะได้เป็น 이었어야/였어야 했다 ส่วน 했다 ท้ายประโยคยังปรากฏเป็น 했는데 ได้ด้วย เพื่อทิ้งท้ายแบบค้างคาด้วยความเสียใจที่ยังคงอยู่: 일찍 잤어야 했는데 "น่าจะเข้านอนเร็วกว่านี้แล้วแท้ๆ...".\n\nลองเปรียบเทียบกับ -(으)ㄹ걸 (그랬다) ซึ่งเป็นญาติแบบลำลองในภาษาพูด: 갔어야 했다 เป็นการพูดความเสียใจออกมาเหมือนเป็นข้อเท็จจริง ("ควรจะไปแล้วแท้ๆ") ขณะที่ 갈걸 (그랬어) เป็นการบ่นกับตัวเองที่นุ่มนวลและถอนหายใจกว่า ("เฮ้อ น่าจะไปซะ") คู่เทียบขั้นต่ำ: 미리 예약했어야 했어요 vs. 미리 예약할걸 — ทั้งคู่แปลว่า "น่าจะจองล่วงหน้าแล้วแท้ๆ" แต่รูปแรกหนักแน่นกว่าและใช้ในงานเขียนหรืออธิบายความผิดพลาดได้ ส่วนรูปหลังเป็นกันเองมาก เกือบเหมือนพึมพำกับตัวเอง ระดับความสุภาพเพียงแค่อาศัย 했다 ท้ายประโยค: 했어 (반말), 했어요 (สุภาพ), 했습니다 (ทางการ) ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือลืมว่าคำกริยา "ตัวแรก" ต้องอยู่ในรูปอดีต — 가야 했다 แปลว่า "ต้องไป (ภาระหน้าที่)" ไม่ใช่ "ควรจะไปแล้ว"; ความหมายเชิงเสียใจต้องมีชั้นของ 았/었 เพิ่มเข้าไปด้วย คือ 갔어야 했다.',
      'Mengungkapkan penyesalan atau celaan atas tindakan di masa lampau yang seharusnya kamu lakukan tetapi tidak kamu lakukan (atau yang seharusnya tidak kamu lakukan tetapi kamu lakukan): "seharusnya tadi...". Bentuk ini dibangun di atas bentuk lampau dari kata kerja: ambil akar katanya, tambahkan -았어야 했다 setelah vokal terang (ㅏ/ㅗ) dan -었어야 했다 untuk lainnya. Jadi 가다 → 갔어야 했다 "seharusnya pergi" (akar bervokal, ㅏ mengalami kontraksi), 먹다 → 먹었어야 했다 "seharusnya makan" (akar berkonsonan/받침). Kata kerja 하다 menjadi 했어야 했다 (공부했어야 했다 "seharusnya belajar"), dan 이다 menjadi 이었어야/였어야 했다. 했다 di akhir juga bisa muncul sebagai 했는데 untuk menggantungkan kalimat dengan penyesalan yang masih membekas: 일찍 잤어야 했는데 "seharusnya aku tidur lebih awal...".\n\nBandingkan dengan -(으)ㄹ걸 (그랬다), sepupunya yang santai dan lebih lisan: 갔어야 했다 menyatakan penyesalan sebagai sebuah fakta ("seharusnya aku pergi"), sedangkan 갈걸 (그랬어) adalah gumaman pada diri sendiri yang lebih lembut dan disertai helaan napas ("ah, harusnya aku pergi tadi"). Pasangan minimal: 미리 예약했어야 했어요 vs. 미리 예약할걸 — keduanya berarti "seharusnya aku memesan lebih dahulu", tetapi yang pertama lebih tegas dan cocok untuk tulisan atau saat menjelaskan kesalahan, sedangkan yang kedua bersifat akrab, hampir seperti gumaman. Tingkat kesopanan cukup menumpang pada 했다 di akhir: 했어 (반말), 했어요 (sopan), 했습니다 (formal). Kesalahan paling umum bagi pembelajar adalah lupa bahwa kata kerja PERTAMA harus dalam bentuk lampau — 가야 했다 berarti "harus pergi (kewajiban)", bukan "seharusnya pergi"; makna penyesalan membutuhkan lapisan tambahan 았/었, yaitu 갔어야 했다.',
      'Diễn tả sự hối tiếc hoặc tự trách về một hành động trong quá khứ mà lẽ ra bạn nên làm nhưng đã không làm (hoặc lẽ ra không nên làm nhưng đã làm): "lẽ ra nên...". Nó được dựng trên thì quá khứ của động từ: lấy thân từ, thêm -았어야 했다 sau nguyên âm sáng (ㅏ/ㅗ) và -었어야 했다 trong các trường hợp còn lại. Vậy 가다 → 갔어야 했다 "lẽ ra nên đi" (thân từ nguyên âm, ㅏ co lại), 먹다 → 먹었어야 했다 "lẽ ra nên ăn" (thân từ có phụ âm/받침). Động từ 하다 trở thành 했어야 했다 (공부했어야 했다 "lẽ ra nên học bài"), và 이다 cho ra 이었어야/였어야 했다. 했다 ở cuối cũng có thể xuất hiện dưới dạng 했는데 để bỏ lửng câu nói với nỗi tiếc nuối còn vương lại: 일찍 잤어야 했는데 "lẽ ra mình nên đi ngủ sớm...".\n\nHãy so sánh nó với -(으)ㄹ걸 (그랬다), người anh em thân mật trong khẩu ngữ: 갔어야 했다 nêu nỗi hối tiếc như một sự thật ("lẽ ra mình nên đi"), trong khi 갈걸 (그랬어) là lời tự nhủ nhẹ nhàng, có chút thở dài hơn ("hầy, lẽ ra mình đã nên đi"). Cặp tối thiểu: 미리 예약했어야 했어요 vs. 미리 예약할걸 — cả hai đều nghĩa là "lẽ ra mình nên đặt chỗ trước", nhưng câu đầu chắc chắn hơn và dùng được trong văn viết hoặc khi giải thích một sai lầm, còn câu sau thì thân mật, gần như lẩm bẩm. Mức độ lịch sự chỉ đơn giản dựa vào 했다 ở cuối: 했어 (반말), 했어요 (lịch sự), 했습니다 (trang trọng). Lỗi phổ biến nhất của người học là quên rằng động từ ĐẦU TIÊN phải ở thì quá khứ — 가야 했다 nghĩa là "phải đi (nghĩa vụ)", chứ không phải "lẽ ra nên đi"; nghĩa hối tiếc cần thêm lớp 았/었, tức 갔어야 했다.',
      '「〜すべきだったのにしなかった」（あるいは「すべきでなかったのにしてしまった」）過去の行為への後悔や非難を表します。動詞の過去形の上に作ります。語幹を取り、明るい母音（ㅏ/ㅗ）の後には -았어야 했다 を、それ以外には -었어야 했다 を付けます。よって 가다 → 갔어야 했다「行くべきだった」（母音語幹、ㅏが縮約）、먹다 → 먹었어야 했다「食べるべきだった」（子音/받침語幹）となります。하다動詞は 했어야 했다 となり（공부했어야 했다「勉強すべきだった」）、이다 は 이었어야/였어야 했다 になります。文末の 했다 は 했는데 の形にもなり、後悔の余韻を残して言いさすことができます：일찍 잤어야 했는데「早く寝るべきだったのに…」。\n\n口語的でくだけた親戚である -(으)ㄹ걸 (그랬다) と比べてみましょう。갔어야 했다 は後悔を事実として述べます（「行くべきだった」）が、갈걸 (그랬어) はもっと柔らかく、ため息まじりの独り言です（「あー、行けばよかった」）。ミニマルペア：미리 예약했어야 했어요 と 미리 예약할걸 — どちらも「前もって予約しておくべきだった」ですが、前者の方がしっかりしていて、文章や失敗を説明する場面に向き、後者は親密で、ほとんどつぶやくような響きです。丁寧さは文末の 했다 に乗るだけです：했어（반말）、했어요（丁寧）、했습니다（フォーマル）。学習者が最もよくする間違いは、最初の動詞が過去形でなければならないことを忘れることです — 가야 했다 は「行かなければならなかった（義務）」であって「行くべきだった」ではありません。後悔の読みには 았/었 の層を足した 갔어야 했다 が必要です。',
    ),
  '-(으)ㄹ 테니까': L(
      '-(으)ㄹ 테니까 attaches to a verb or adjective stem to give a reason rooted either in the speaker\'s own intention ("since I\'ll...") or in a strong supposition about someone/something else ("it must be that..., so..."). Form: vowel/ㄹ stem → -ㄹ 테니까 (가다 → 갈 테니까 "since I\'ll go", 만들다 → 만들 테니까, ㄹ kept); consonant stem → -을 테니까 (먹다 → 먹을 테니까 "since I\'ll eat", 읽다 → 읽을 테니까). When it\'s your own plan, the subject is usually first person and the second clause is a request or suggestion: 제가 청소할 테니까 너는 쉬어 "I\'ll clean, so you rest." When it\'s a guess about a third party — often with an adjective — use any subject: 길이 막힐 테니까 일찍 출발하세요 "the road will surely be jammed, so leave early"; 피곤할 테니까 좀 쉬세요 "you must be tired, so rest a bit." For past suppositions, add -았/었을: 피곤했을 테니까 "since you must have been tired."\n\nThe closest neighbor to watch is plain -(으)니까 ("because"), which states a present fact, while -(으)ㄹ 테니까 layers in futurity plus intention or conjecture. Compare 비가 오니까 우산을 가져가 "it\'s raining, so take an umbrella" (observed fact) with 비가 올 테니까 우산을 가져가 "it\'ll surely rain, so take an umbrella" (prediction). Register-wise 테니까 is neutral and fits both 해요 and 합니다 speech; the more casual spoken contraction is -(으)ㄹ 테니 (갈 테니), heard often in conversation. The most common learner mistake is using it for someone else\'s intention — you can say 제가 갈 테니까 but for another person\'s plan use their own statement or -(으)ㄹ 거니까 instead; reserve the second-/third-person 테니까 for suppositions, not their decisions.',
      '-(으)ㄹ 테니까 se une a la raíz de un verbo o adjetivo para dar una razón que nace o bien de la propia intención del hablante ("ya que voy a...") o bien de una suposición fuerte sobre alguien/algo más ("seguro que está..., así que..."). Forma: raíz terminada en vocal o en ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 "ya que voy a ir", 만들다 → 만들 테니까, la ㄹ se mantiene); raíz terminada en consonante → -을 테니까 (먹다 → 먹을 테니까 "ya que voy a comer", 읽다 → 읽을 테니까). Cuando se trata de tu propio plan, el sujeto suele ir en primera persona y la segunda cláusula es un pedido o una sugerencia: 제가 청소할 테니까 너는 쉬어 "yo limpio, así que vos descansá". Cuando es una conjetura sobre un tercero —a menudo con un adjetivo— podés usar cualquier sujeto: 길이 막힐 테니까 일찍 출발하세요 "seguro que el camino va a estar congestionado, así que salí temprano"; 피곤할 테니까 좀 쉬세요 "seguro estás cansado, así que descansá un poco". Para suposiciones sobre el pasado, agregá -았/었을: 피곤했을 테니까 "ya que seguro estabas cansado".\n\nEl vecino más cercano que conviene vigilar es el simple -(으)니까 ("porque"), que enuncia un hecho presente, mientras que -(으)ㄹ 테니까 le añade una capa de futuridad más intención o conjetura. Compará 비가 오니까 우산을 가져가 "está lloviendo, así que llevá paraguas" (hecho observado) con 비가 올 테니까 우산을 가져가 "seguro que va a llover, así que llevá paraguas" (predicción). En cuanto al registro, 테니까 es neutro y encaja tanto en el habla 해요 como en la 합니다; la contracción hablada más informal es -(으)ㄹ 테니 (갈 테니), que se oye mucho en la conversación. El error más común de los estudiantes es usarlo para la intención de otra persona: podés decir 제가 갈 테니까, pero para el plan de otro usá su propia afirmación o -(으)ㄹ 거니까 en su lugar; reservá el 테니까 de segunda o tercera persona para suposiciones, no para sus decisiones.',
      '-(으)ㄹ 테니까 s\'attache au radical d\'un verbe ou d\'un adjectif pour donner une raison ancrée soit dans l\'intention propre du locuteur (« puisque je vais... »), soit dans une forte supposition à propos de quelqu\'un ou de quelque chose d\'autre (« ce doit être que..., donc... »). Forme : radical en voyelle ou en ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 « puisque je vais y aller », 만들다 → 만들 테니까, le ㄹ est conservé) ; radical en consonne → -을 테니까 (먹다 → 먹을 테니까 « puisque je vais manger », 읽다 → 읽을 테니까). Quand il s\'agit de ton propre projet, le sujet est généralement à la première personne et la seconde proposition est une requête ou une suggestion : 제가 청소할 테니까 너는 쉬어 « je vais faire le ménage, alors repose-toi ». Quand c\'est une supposition à propos d\'un tiers — souvent avec un adjectif — utilise n\'importe quel sujet : 길이 막힐 테니까 일찍 출발하세요 « la route sera sûrement embouteillée, alors pars tôt » ; 피곤할 테니까 좀 쉬세요 « tu dois être fatigué, alors repose-toi un peu ». Pour les suppositions au passé, ajoute -았/었을 : 피곤했을 테니까 « puisque tu devais être fatigué ».\n\nLe voisin le plus proche à surveiller est le simple -(으)니까 (« parce que »), qui énonce un fait présent, tandis que -(으)ㄹ 테니까 y superpose une dimension de futur plus de l\'intention ou de la conjecture. Compare 비가 오니까 우산을 가져가 « il pleut, alors prends un parapluie » (fait observé) avec 비가 올 테니까 우산을 가져가 « il va sûrement pleuvoir, alors prends un parapluie » (prédiction). Côté registre, 테니까 est neutre et convient aussi bien au style 해요 qu\'au style 합니다 ; la contraction parlée plus familière est -(으)ㄹ 테니 (갈 테니), qu\'on entend souvent à l\'oral. L\'erreur la plus courante des apprenants est de l\'employer pour l\'intention de quelqu\'un d\'autre : tu peux dire 제가 갈 테니까, mais pour le projet d\'une autre personne, utilise sa propre déclaration ou -(으)ㄹ 거니까 à la place ; réserve le 테니까 à la deuxième ou troisième personne pour des suppositions, pas pour leurs décisions.',
      '-(으)ㄹ 테니까 se liga ao radical de um verbo ou adjetivo para dar uma razão enraizada ou na própria intenção do falante ("já que eu vou...") ou em uma suposição forte sobre outra pessoa ou coisa ("deve ser que..., então..."). Forma: radical terminado em vogal ou em ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 "já que eu vou", 만들다 → 만들 테니까, o ㄹ é mantido); radical terminado em consoante → -을 테니까 (먹다 → 먹을 테니까 "já que eu vou comer", 읽다 → 읽을 테니까). Quando é o seu próprio plano, o sujeito costuma estar na primeira pessoa e a segunda oração é um pedido ou sugestão: 제가 청소할 테니까 너는 쉬어 "eu vou limpar, então você descansa". Quando é um palpite sobre um terceiro — muitas vezes com um adjetivo — use qualquer sujeito: 길이 막힐 테니까 일찍 출발하세요 "com certeza a estrada vai estar congestionada, então saia cedo"; 피곤할 테니까 좀 쉬세요 "você deve estar cansado, então descanse um pouco". Para suposições sobre o passado, acrescente -았/었을: 피곤했을 테니까 "já que você devia estar cansado".\n\nO vizinho mais próximo a se observar é o simples -(으)니까 ("porque"), que enuncia um fato presente, enquanto -(으)ㄹ 테니까 acrescenta uma camada de futuridade mais intenção ou conjectura. Compare 비가 오니까 우산을 가져가 "está chovendo, então leve um guarda-chuva" (fato observado) com 비가 올 테니까 우산을 가져가 "com certeza vai chover, então leve um guarda-chuva" (previsão). Quanto ao registro, 테니까 é neutro e cabe tanto na fala 해요 quanto na 합니다; a contração falada mais informal é -(으)ㄹ 테니 (갈 테니), ouvida com frequência na conversa. O erro mais comum dos estudantes é usá-lo para a intenção de outra pessoa: você pode dizer 제가 갈 테니까, mas para o plano de outra pessoa use a fala dela mesma ou -(으)ㄹ 거니까; reserve o 테니까 de segunda ou terceira pessoa para suposições, não para as decisões delas.',
      '-(으)ㄹ 테니까 เติมท้ายรากของคำกริยาหรือคำคุณศัพท์ เพื่อบอกเหตุผลที่มีรากฐานมาจากความตั้งใจของผู้พูดเอง ("เพราะฉันจะ...") หรือจากการคาดเดาอย่างมั่นใจเกี่ยวกับคนหรือสิ่งอื่น ("คงจะเป็นเพราะว่า... ดังนั้น..."). รูป: รากที่ลงท้ายด้วยสระหรือ ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 "เพราะฉันจะไป", 만들다 → 만들 테니까 โดย ㄹ ยังคงอยู่); รากที่ลงท้ายด้วยพยัญชนะ → -을 테니까 (먹다 → 먹을 테니까 "เพราะฉันจะกิน", 읽다 → 읽을 테니까). เมื่อเป็นแผนของตัวคุณเอง ประธานมักเป็นบุรุษที่หนึ่ง และอนุประโยคที่สองเป็นคำขอร้องหรือคำเสนอแนะ: 제가 청소할 테니까 너는 쉬어 "ฉันจะทำความสะอาดเอง เธอพักผ่อนไปเถอะ". เมื่อเป็นการคาดเดาเกี่ยวกับบุคคลที่สาม — มักใช้กับคำคุณศัพท์ — ใช้ประธานใดก็ได้: 길이 막힐 테니까 일찍 출발하세요 "ถนนคงจะรถติดแน่ ๆ เพราะฉะนั้นออกแต่เนิ่น ๆ นะ"; 피곤할 테니까 좀 쉬세요 "คุณคงจะเหนื่อย พักสักหน่อยเถอะ". สำหรับการคาดเดาในอดีต ให้เติม -았/었을: 피곤했을 테니까 "เพราะคุณคงจะเหนื่อยมาแล้ว".\n\nเพื่อนบ้านที่ใกล้เคียงที่สุดที่ต้องระวังคือ -(으)니까 แบบธรรมดา ("เพราะว่า") ซึ่งบอกข้อเท็จจริงในปัจจุบัน ในขณะที่ -(으)ㄹ 테니까 เพิ่มชั้นของความเป็นอนาคตบวกกับความตั้งใจหรือการคาดเดาเข้าไป. เปรียบเทียบ 비가 오니까 우산을 가져가 "ฝนกำลังตก เพราะฉะนั้นเอาร่มไปด้วย" (ข้อเท็จจริงที่สังเกตเห็น) กับ 비가 올 테니까 우산을 가져가 "ฝนคงจะตกแน่ ๆ เพราะฉะนั้นเอาร่มไปด้วย" (การทำนาย). ในด้านระดับภาษา 테니까 เป็นกลางและใช้ได้ทั้งกับภาษาแบบ 해요 และ 합니다; รูปย่อที่ใช้พูดและเป็นกันเองกว่าคือ -(으)ㄹ 테니 (갈 테니) ซึ่งได้ยินบ่อยในการสนทนา. ข้อผิดพลาดที่ผู้เรียนพบบ่อยที่สุดคือการใช้มันกับความตั้งใจของคนอื่น — คุณพูดได้ว่า 제가 갈 테니까 แต่สำหรับแผนของคนอื่นให้ใช้คำพูดของเขาเองหรือ -(으)ㄹ 거니까 แทน; ให้สงวน 테니까 ที่เป็นบุรุษที่สอง/ที่สามไว้สำหรับการคาดเดา ไม่ใช่การตัดสินใจของพวกเขา.',
      '-(으)ㄹ 테니까 melekat pada akar kata kerja atau kata sifat untuk memberikan alasan yang berakar entah pada niat penutur sendiri ("karena aku akan...") atau pada dugaan kuat tentang orang/sesuatu yang lain ("pasti karena..., jadi..."). Bentuk: akar berakhiran vokal atau ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 "karena aku akan pergi", 만들다 → 만들 테니까, ㄹ tetap dipertahankan); akar berakhiran konsonan → -을 테니까 (먹다 → 먹을 테니까 "karena aku akan makan", 읽다 → 읽을 테니까). Ketika ini rencanamu sendiri, subjeknya biasanya orang pertama dan klausa kedua berupa permintaan atau saran: 제가 청소할 테니까 너는 쉬어 "aku yang akan membersihkan, jadi kamu istirahat saja". Ketika ini dugaan tentang pihak ketiga — sering kali dengan kata sifat — gunakan subjek apa pun: 길이 막힐 테니까 일찍 출발하세요 "jalanan pasti akan macet, jadi berangkatlah lebih awal"; 피곤할 테니까 좀 쉬세요 "Anda pasti lelah, jadi istirahatlah sebentar". Untuk dugaan tentang masa lalu, tambahkan -았/었을: 피곤했을 테니까 "karena Anda pasti sudah lelah".\n\nTetangga terdekat yang perlu diwaspadai adalah -(으)니까 biasa ("karena"), yang menyatakan fakta masa kini, sedangkan -(으)ㄹ 테니까 menambahkan lapisan ke-masa-depan-an plus niat atau dugaan. Bandingkan 비가 오니까 우산을 가져가 "sedang hujan, jadi bawalah payung" (fakta yang teramati) dengan 비가 올 테니까 우산을 가져가 "pasti akan hujan, jadi bawalah payung" (ramalan). Soal ragam bahasa, 테니까 bersifat netral dan cocok baik untuk tutur 해요 maupun 합니다; kontraksi lisan yang lebih santai adalah -(으)ㄹ 테니 (갈 테니), yang sering terdengar dalam percakapan. Kesalahan paling umum bagi pembelajar adalah menggunakannya untuk niat orang lain — kamu boleh berkata 제가 갈 테니까, tetapi untuk rencana orang lain gunakan pernyataan dari orang itu sendiri atau -(으)ㄹ 거니까; simpan 테니까 orang kedua/ketiga untuk dugaan, bukan untuk keputusan mereka.',
      '-(으)ㄹ 테니까 gắn vào gốc của động từ hoặc tính từ để nêu một lý do bắt nguồn hoặc từ ý định của chính người nói ("vì tôi sẽ...") hoặc từ một sự phỏng đoán mạnh về người/vật khác ("chắc hẳn là..., nên..."). Cách dùng: gốc kết thúc bằng nguyên âm hoặc ㄹ → -ㄹ 테니까 (가다 → 갈 테니까 "vì tôi sẽ đi", 만들다 → 만들 테니까, ㄹ được giữ lại); gốc kết thúc bằng phụ âm → -을 테니까 (먹다 → 먹을 테니까 "vì tôi sẽ ăn", 읽다 → 읽을 테니까). Khi đó là kế hoạch của chính bạn, chủ ngữ thường ở ngôi thứ nhất và mệnh đề thứ hai là một lời đề nghị hoặc gợi ý: 제가 청소할 테니까 너는 쉬어 "tôi sẽ dọn dẹp, nên cậu cứ nghỉ ngơi đi". Khi đó là phỏng đoán về một người thứ ba — thường đi với tính từ — hãy dùng bất kỳ chủ ngữ nào: 길이 막힐 테니까 일찍 출발하세요 "đường chắc chắn sẽ kẹt, nên hãy khởi hành sớm"; 피곤할 테니까 좀 쉬세요 "chắc anh/chị mệt rồi, nên hãy nghỉ một chút". Đối với phỏng đoán về quá khứ, thêm -았/었을: 피곤했을 테니까 "vì hẳn là anh/chị đã mệt".\n\nCấu trúc gần gũi nhất cần lưu ý là -(으)니까 thông thường ("bởi vì"), vốn nêu một sự thật ở hiện tại, trong khi -(으)ㄹ 테니까 phủ thêm sắc thái tương lai cộng với ý định hoặc sự suy đoán. Hãy so sánh 비가 오니까 우산을 가져가 "trời đang mưa, nên hãy mang theo ô" (sự thật quan sát được) với 비가 올 테니까 우산을 가져가 "trời chắc chắn sẽ mưa, nên hãy mang theo ô" (dự đoán). Về sắc thái ngữ vực, 테니까 mang tính trung lập và phù hợp với cả lối nói 해요 lẫn 합니다; dạng rút gọn khẩu ngữ thân mật hơn là -(으)ㄹ 테니 (갈 테니), thường được nghe thấy trong hội thoại. Lỗi phổ biến nhất của người học là dùng nó cho ý định của người khác — bạn có thể nói 제가 갈 테니까, nhưng đối với kế hoạch của người khác hãy dùng chính lời nói của họ hoặc -(으)ㄹ 거니까; hãy dành 테니까 ở ngôi thứ hai/thứ ba cho các phỏng đoán, chứ không phải cho quyết định của họ.',
      '-(으)ㄹ 테니까 は動詞や形容詞の語幹に付き、話し手自身の意図（「私が…するから」）か、他の人や物事についての強い推量（「きっと…だろうから」）のどちらかに根ざした理由を述べます。形：母音またはㄹで終わる語幹 → -ㄹ 테니까（가다 → 갈 테니까「私が行くから」、만들다 → 만들 테니까、ㄹは保たれる）；子音で終わる語幹 → -을 테니까（먹다 → 먹을 테니까「私が食べるから」、읽다 → 읽을 테니까）。自分の計画のときは、主語はたいてい一人称で、後の節は依頼や提案になります：제가 청소할 테니까 너는 쉬어「私が掃除するから、あなたは休んで」。第三者についての推量のとき（多くは形容詞とともに）は、どんな主語でも使えます：길이 막힐 테니까 일찍 출발하세요「道はきっと混むだろうから、早めに出発してください」；피곤할 테니까 좀 쉬세요「お疲れでしょうから、少し休んでください」。過去の推量には -았/었을 を加えます：피곤했을 테니까「お疲れだったでしょうから」。\n\n最も近く、注意すべき隣人は、現在の事実を述べる素の -(으)니까（「〜だから」）です。一方 -(으)ㄹ 테니까 はそこに未来性と意図あるいは推量の層を重ねます。비가 오니까 우산을 가져가「雨が降っているから、傘を持っていって」（観察された事実）と、비가 올 테니까 우산을 가져가「きっと雨が降るだろうから、傘を持っていって」（予測）を比べてみてください。文体としては 테니까 は中立で、해요 体にも 합니다 体にも合います；よりくだけた話し言葉の縮約形は -(으)ㄹ 테니（갈 테니）で、会話でよく耳にします。学習者が最もよくする間違いは、他人の意図に対してこれを使ってしまうことです——제가 갈 테니까 とは言えますが、他人の計画にはその人自身の発言か -(으)ㄹ 거니까 を使ってください；二人称・三人称の 테니까 は推量のためにとっておき、彼らの決断には使わないようにしましょう。',
    ),
}
